insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lower_name', 1, '감나무 집 우물', '감나무 집 우물', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "묵창 나루 우물가에서 아낙 하나가 두레박을 올리다 말고 손을 멈췄다. 우물 옆 대문간에 감나무가 서 있었고, 그 곁 기둥에 키 잰 금이 여러 줄 그어져 있었다."}, {"s": null, "t": "아낙은 나를 보고 물동이를 내려놓았다. 손끝에 먹이 묻어 있었다. 아침마다 문패를 새로 쓰는 나루 사람의 손이었다."}, {"s": "q:sx_mk_onsaemi", "t": "바깥 분이시죠. 여기선 저를 우물가 아낙이라고 불러요. 우물 옆 감나무 집에 살거든요."}, {"s": null, "t": "감나무라는 말에 나는 잿빛 갈대숲 물가에서 만난 사내를 떠올렸다. 대문 옆 감나무와 키 잰 금이 그어진 기둥을 이야기하던 사내였다."}, {"s": null, "t": "나는 갈대숲으로 떠밀려 온 사내 이야기를 했다. 사내가 끌어안고 있던 문패와, 그가 갈대 영사로 꿰맨 딸의 이름까지 모두 들려주었다."}, {"s": null, "t": "아낙은 한참 대답하지 않았다. 물동이 끈을 쥔 손가락이 하얗게 질려 있었다."}, {"s": "q:sx_mk_onsaemi", "t": "그 문패에 꿰맨 이름이…… 온새미였나요?"}, {"s": null, "t": "내가 고개를 끄덕이자, 아낙은 우물가 돌 위에 털썩 주저앉았다."}, {"s": "q:sx_mk_onsaemi", "t": "아버지는 먹비 오던 아침에 사라졌어요. 문패를 고쳐 쓰러 나갔다가 안 돌아오셨어요. 물가에는 붓 한 자루만 떨어져 있었고요."}, {"s": "q:sx_mk_onsaemi", "t": "다들 강에 빠지셨다고 했어요. 그래서 저는 해마다 그날이면 우물가에 국 한 그릇을 떠 놓았어요."}, {"s": null, "t": "온새미는 소매로 눈가를 꾹 눌렀다. 그러고는 대문간의 문패를 돌아보았다. 아침에 쓴 글씨가 벌써 먹비에 지워져 있었다."}, {"s": "q:sx_mk_onsaemi", "t": "아버지를 뵈러 가고 싶어요. 그런데 빈손으로는 못 가겠어요. 이 집 문패는 아버지가 손수 깎으셨거든요. 저도 아버지 문패를 대문에 걸 판자를 깎아 드리고 싶어요."}, {"s": "q:sx_mk_onsaemi", "t": "빈칸 벌판에 뜯긴 문패가 쌓인 데가 있대요. 거기서 지워진 문패 조각 두 개만 주워다 주세요. 깎는 건 제가 할게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lower_name', 2, '안쪽으로 접은 자리', '빈칸 벌판에서 지워진 문패 조각을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["erased_plate"], "r": ["blank_field"], "n": 2}]}'::jsonb, '[{"s": null, "t": "내가 주워 온 문패 조각을 건네자, 온새미는 마루에 앉아 칼로 모서리를 다듬었다. 글자가 지워진 면을 손끝으로 쓸어 보다가, 그 면을 안쪽으로 돌려 두 조각을 맞댔다."}, {"s": "q:sx_mk_onsaemi", "t": "남의 이름이 지워진 자리에 제 글씨를 쓰기는 미안하잖아요. 안쪽으로 접어 두면 그 사람 자리도 그대로 남고요."}, {"s": null, "t": "온새미는 다듬은 판자를 보자기에 쌌다. 보따리 끈을 묶는 손이 조금 떨렸다."}, {"s": "q:sx_mk_onsaemi", "t": "아버지가 반요가 되셨다는 건 알아요. 이름도 기억 못 하신다면서요. 저를 보셔도 모르실지 몰라요."}, {"s": "q:sx_mk_onsaemi", "t": "……그래도 가 볼래요. 잿빛 갈대숲까지 같이 가 주세요. 아버지가 문패를 꿰매셨다는 갈대 영사도 세 타래쯤 거둬 가요. 판자에 문패를 매달 실도 같은 갈대 영사로 할래요."}]'::jsonb, '{"xp": 2320}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lower_name', 3, '낫을 내려놓은 아낙', '잿빛 갈대숲에 간다, 잿빛 갈대숲에서 갈대 영사을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "travel", "r": ["ash_reeds"], "n": 1}, {"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": null, "t": "갈대 영사를 거둬 물가로 나오자 낫 소리가 들렸다. 새암이 갈대를 쳐 내다가 나를 알아보고 낫을 내렸다."}, {"s": "q:sx_saeam", "t": "또 왔네. 그런데 이번엔 혼자가 아니구나."}, {"s": null, "t": "온새미가 내 뒤에서 한 걸음 나섰다. 보자기를 가슴에 안은 채 고개를 숙였다."}, {"s": "q:sx_mk_onsaemi", "t": "문패에 제 이름을 꿰맨 분을 찾아왔어요. 제 아버지예요."}, {"s": null, "t": "새암은 온새미를 오래 바라보았다. 그러다 낫을 갈대 더미에 꽂고 손을 털었다."}, {"s": "q:sx_saeam", "t": "그 사람, 반요촌에 있어. 날마다 대문 앞에 앉아서 문패를 무릎에 올려놓고 있지. 누가 지나가면 꼭 고개를 들어 봐."}, {"s": "q:sx_saeam", "t": "그래도 바로 가지는 마. 섬 공기를 처음 마시면 바깥사람은 머리가 핑 돌아. 반요촌에서 하룻밤 쉬고 아침에 만나. 그 사람도 아침이 낫고. 밤만 되면 자꾸 물가로 나가려고 하거든."}]'::jsonb, '{"xp": 2320}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lower_name', 4, '그 소리 하나', '반요촌에서 쉰다', '{"at": ["banyo_village"], "tasks": [{"t": "rest", "r": ["banyo_village"], "n": 1}]}'::jsonb, '[{"s": null, "t": "이튿날 아침, 반요촌 골목 끝 집 대문 앞에 사내가 앉아 있었다. 무릎 위에 놓인 문패에서 갈대 영사로 꿰맨 글자 세 자가 아침 햇살을 받아 반짝였다."}, {"s": null, "t": "온새미가 걸음을 멈추자, 사내가 고개를 들었다. 사내의 눈은 다정했지만, 온새미를 처음 보는 사람의 눈이었다."}, {"s": "q:sx_tteomilin", "t": "손님이시오. ……이 집에 무슨 볼일이라도 있소."}, {"s": null, "t": "온새미의 입술이 떨렸다. 한참 만에야 목소리가 나왔다."}, {"s": "q:sx_mk_onsaemi", "t": "아버지."}, {"s": null, "t": "사내의 손이 문패 위에서 멈췄다. 그는 문패의 글자와 온새미의 얼굴을 번갈아 보았다. 무언가를 찾으려는 눈이었고, 끝내 찾지 못한 눈이었다."}, {"s": "q:sx_tteomilin", "t": "……그 소리를 알 것 같소. 그 소리 하나만은 알 것 같소. 그런데 미안하오. 그 뒤가 생각나지 않소."}, {"s": null, "t": "온새미는 고개를 저었다. 눈가가 붉었지만 목소리는 흔들리지 않았다."}, {"s": "q:sx_mk_onsaemi", "t": "괜찮아요. 제가 기억하니까요."}, {"s": null, "t": "온새미는 사내 곁에 앉아 문패를 들여다보았다. 위 칸에는 제 이름이 고르지 않은 땀으로 꿰매져 있었고, 아래 칸은 비어 있었다."}, {"s": null, "t": "뒤따라온 새암이 대문 기둥에 기대서서 그 빈칸을 턱짓으로 가리켰다."}, {"s": "q:sx_saeam", "t": "아래 칸은 그 애가 언젠가 와서 적어 줄지도 모른다고 비워 둔 거야. 네가 그 애구나."}, {"s": null, "t": "온새미는 빈칸을 오래 쓰다듬었다. 그러다 고개를 들어 나를 보았다."}, {"s": "q:sx_mk_onsaemi", "t": "아래 칸을 꿰매기 전에 하나만 더 부탁드려요. 아버지 이름은 제가 알아요. 아버지는 모르시지만요."}, {"s": "q:sx_mk_onsaemi", "t": "그 이름을 이름 먹 부적에 적어서 아버지 품에 넣어 드리고 싶어요. 이름은 잊으셨어도 몸에는 지니고 계시게요. 부적 한 장만 지어 주세요."}]'::jsonb, '{"xp": 2320}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lower_name', 5, '아래 칸', '이름 먹 부적을(를) 만든다, 이름 먹 부적을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["name_ink_charm"], "n": 1}], "give": {"name_ink_charm": 1}}'::jsonb, '[{"s": null, "t": "내가 지어 온 이름 먹 부적에 온새미가 붓으로 아버지의 이름을 적었다. 나는 그 이름을 들여다보지 않았다. 온새미는 부적을 접어 사내의 저고리 안쪽에 넣고 옷깃을 여며 주었다."}, {"s": "q:sx_tteomilin", "t": "가슴께가 따뜻하오. 무엇을 넣었소?"}, {"s": null, "t": "온새미는 사내의 옷깃을 한 번 더 쓸어내렸다."}, {"s": "q:sx_mk_onsaemi", "t": "아버지 거요. 원래 아버지 거였어요."}, {"s": null, "t": "온새미는 새암에게서 바늘을 받아 갈대 영사를 꿰었다. 그러고는 문패 아래 칸에 한 땀씩 글자를 박았다. 세 글자였다."}, {"s": null, "t": "「아버지」."}, {"s": null, "t": "새암이 바늘 끝을 내려다보며 고개를 갸웃했다."}, {"s": "q:sx_saeam", "t": "아래 칸엔 섬에서 지은 이름을 적는 거라니까."}, {"s": null, "t": "온새미는 마지막 땀을 매듭짓고 실을 이로 끊었다."}, {"s": "q:sx_mk_onsaemi", "t": "알아요. 그래서 이걸 적었어요. 아버지가 섬에 오셔서도 기억하신 이름이잖아요."}, {"s": null, "t": "사내는 문패를 들어 아래 칸을 손끝으로 더듬었다. 글자를 읽지는 못했다. 그런데도 소리 내어 따라 했다."}, {"s": "q:sx_tteomilin", "t": "아버지."}, {"s": null, "t": "사내가 웃었다. 갈대숲에서도, 반요촌에서도 본 적 없는 웃음이었다. 온새미는 그 어깨에 이마를 기대고 오래 울었다."}, {"s": null, "t": "울음을 그친 온새미는 나루에서 깎아 온 판자를 대문 기둥에 박고, 그 위에 아버지의 문패를 갈대 영사로 매달았다. 무릎 위에만 있던 문패가 처음으로 대문에 걸렸다."}, {"s": null, "t": "나루로 돌아오는 길에 온새미는 달마다 섬에 건너오겠다고 했다. 그리고 올해부터는 그날이 와도 우물가에 국을 떠 놓지 않겠다고 했다."}]'::jsonb, '{"xp": 2320, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
