insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_carp', 1, '이름 없는 뱃머리', '이름 없는 뱃머리', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "묵창 나루 선창 끝에 낡은 나룻배 한 척이 뭍으로 끌어올려져 있었다. 쉰 줄의 아낙 하나가 배 옆에 쪼그려 앉아 뱃머리를 걸레로 닦고 있었다."}, {"s": null, "t": "아낙은 같은 자리를 몇 번이고 문질렀다. 뱃머리에는 글자를 새겼던 홈만 남아 있고, 홈 안은 먹물이 배어 검었다."}, {"s": "q:sx_mk_baetjip", "t": "닦아도 안 나와. 먹비가 다 먹어 버렸어."}, {"s": null, "t": "아낙은 걸레를 무릎에 내려놓고 강 쪽을 돌아보았다. 나는 무슨 이름이 적혀 있었느냐고 물었다."}, {"s": "q:sx_mk_baetjip", "t": "우리 집 양반이 이 배에 이름을 붙였거든. 그 양반 가고 나서 해마다 내가 덧새겼는데, 올봄부터는 새기려고 칼을 대면 무슨 글자였는지 생각이 안 나."}, {"s": "q:sx_mk_baetjip", "t": "나루 사람들은 나를 뱃집 아낙이라고 불러. 배가 있는 집이라서. 배 이름을 잊으면 나는 무슨 집 아낙이 되나 몰라."}, {"s": null, "t": "아낙은 웃으려다 말고 걸레를 다시 쥐었다. 그러다 무언가 생각난 듯 손을 멈추고 먹빛 강물을 가리켰다."}, {"s": "q:sx_mk_baetjip", "t": "옛날부터 나루에 내려오는 말이 있어. 먹비에 지워진 글자는 강으로 흘러가고, 그걸 문패 잉어가 삼킨대. 그래서 그 잉어 비늘에는 지워진 글자가 비친다고."}, {"s": "q:sx_mk_baetjip", "t": "그 잉어는 아무 미끼나 안 물어. 버들치나 피라미, 쏘가리, 동자개 같은 강물고기를 걸어야 냄새를 맡고 올라온대."}, {"s": "q:sx_mk_baetjip", "t": "미끼할 물고기부터 몇 마리 낚아 주겠어? 선창 앞 먹물 여울에서 세 번만 낚아 보면 그중에 하나쯤은 걸릴 거야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_carp', 2, '미끼 바구니', '묵창 나루에서 낚시를 한다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "n": 3}]}'::jsonb, '[{"s": null, "t": "여울에서 낚은 물고기를 바구니에 담아 가자, 뱃집 아낙이 바구니를 들여다보고 한 마리씩 손가락으로 짚었다."}, {"s": "q:sx_mk_baetjip", "t": "이건 미끼가 되고, 이것도 되고. 잘 낚았네."}, {"s": "q:sx_mk_baetjip", "t": "미끼는 가방에 넣어 두고, 낚시할 때 낚시 칸에서 미끼로 골라 걸면 돼. 그래야 낚싯바늘에 꿰어지지."}, {"s": null, "t": "아낙은 바구니를 내게 돌려주고, 하늘을 한 번 올려다보았다. 구름이 낮게 깔려 있었다."}, {"s": "q:sx_mk_baetjip", "t": "문패 잉어는 땅거미 질 무렵에만 올라와. 그것도 가랑비가 보슬보슬 내리는 날, 세우 오는 저녁에만."}, {"s": "q:sx_mk_baetjip", "t": "우리 양반도 꼭 그런 저녁에 배를 댔어. 비 맞은 뱃머리에서 이름이 반짝반짝했지."}, {"s": null, "t": "아낙은 그 말을 하고 오래 강을 보았다. 그러고는 내 쪽으로 몸을 돌렸다."}, {"s": "q:sx_mk_baetjip", "t": "세우 오는 땅거미에 먹물 여울에서 문패 잉어를 한 마리만 낚아 줘. 비늘만 한 번 보면 돼."}]'::jsonb, '{"xp": 3093}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_carp', 3, '비늘에 비친 글자', '묵창 나루에서 문패 잉어을(를) 낚는다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "f": ["doorplate_carp"], "n": 1}]}'::jsonb, '[{"s": null, "t": "가랑비 속에서 낚아 올린 잉어는 팔뚝만 했다. 비늘마다 획이 하나씩 새겨져 있었다. 물을 뚝뚝 흘리며 퍼덕일 때마다 획들이 자리를 바꾸었다."}, {"s": null, "t": "뱃집 아낙이 맨손으로 잉어를 받아 들었다. 비 맞은 비늘을 등불 가까이 대고, 숨도 쉬지 않고 들여다보았다."}, {"s": "q:sx_mk_baetjip", "t": "……먹, 제, 비."}, {"s": null, "t": "아낙의 입술이 한 글자씩 움직였다. 비늘 위의 획이 그제야 멈추어 세 글자로 맞춰졌다."}, {"s": "q:sx_mk_baetjip", "t": "먹제비. 그래, 먹제비였어. 먹비가 와도 낮게 날아 집으로 돌아오는 제비라고, 그 양반이 그렇게 지었어."}, {"s": null, "t": "아낙은 잉어를 품에 안은 채 한참 아무 말도 하지 않았다. 그러다 코를 훌쩍이고 나를 올려다보았다."}, {"s": "q:sx_mk_baetjip", "t": "이번에는 안 잊게 단단히 새겨야지. 그 전에 나부터 이름을 붙들어 둬야겠어."}, {"s": "q:sx_mk_baetjip", "t": "문패 잉어를 고아서 이름 새김 탕을 끓이면, 먹어도 한동안 이름이 안 흐려진대. 한 그릇만 지어다 줘. 그거 먹고 칼을 잡을게."}]'::jsonb, '{"xp": 3093}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_carp', 4, '다시 새긴 뱃머리', '이름 새김 탕을(를) 만든다, 이름 새김 탕을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["name_carving_soup"], "n": 1}], "give": {"name_carving_soup": 1}}'::jsonb, '[{"s": null, "t": "이름 새김 탕을 건네자, 뱃집 아낙은 그릇을 두 손으로 받쳐 들고 천천히 다 비웠다. 그리고 칼을 들어 뱃머리의 빈 홈에 날을 댔다."}, {"s": null, "t": "아낙의 손은 이번에는 멈추지 않았다. 아낙은 먹, 제, 비 세 글자를 차례로 새겼다. 글자가 홈을 따라 깊게 패었다."}, {"s": "q:sx_mk_baetjip", "t": "됐다. 이제 나도 먹제비 뱃집 아낙이야."}, {"s": null, "t": "아낙은 칼을 내려놓고 뱃머리를 손바닥으로 쓸었다. 그 손길은 사람의 등을 쓰다듬는 것 같았다."}, {"s": "q:sx_mk_baetjip", "t": "내년 봄에 또 먹비가 오면 또 지워지겠지. 그래도 괜찮아. 이제는 어디 가서 찾으면 되는지 아니까."}, {"s": null, "t": "내가 선창을 떠날 때, 아낙은 배 옆에 앉아 강을 보고 있었다. 이번에는 걸레를 쥐고 있지 않았다."}]'::jsonb, '{"xp": 3093, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mks_porter', 'side', '채집·빙혼곡', '빙혼곡을 넘는 짐꾼', '묵창 나루로 소금과 쌀을 지고 가던 짐꾼이 고갯길에서 짐을 잃었다. 짐에 적힌 이름이 모두 지워져 누구 짐인지도 모른다.', 'frost_valley', 40, '{mkq_1}'::text[], null, 1312, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_porter' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_porter', 1, '바위에 앉은 덩치', '바위에 앉은 덩치', '{"at": ["frost_valley"]}'::jsonb, '[{"s": null, "t": "빙혼곡 고갯길 바위 위에 덩치 큰 사내 하나가 앉아 엉엉 울고 있었다. 빈 지게가 발치에 쓰러져 있었다."}, {"s": null, "t": "사내는 나를 보자 눈물을 소매로 쓱 닦고 가슴을 쭉 폈다."}, {"s": "q:sx_mk_dumbawoo", "t": "울긴 누가 울어! 바람이 눈에 들어간 거야. 나는 이 고개를 서른 번 넘은 덤바우야. 소금 짐꾼 덤바우."}, {"s": "q:sx_mk_dumbawoo", "t": "그런데…… 서리 까마귀 떼가 덮치는 바람에 짐을 다 놓쳤어. 묵창 나루로 갈 소금 섬하고 쌀자루야. 고갯길 여기저기 굴러갔을 거야."}, {"s": null, "t": "덤바우의 목소리가 점점 작아졌다. 배에서 꼬르륵 소리가 났다."}, {"s": "q:sx_mk_dumbawoo", "t": "하나만 더 말할게. 아침도 못 먹었어. 짐 좀 같이 찾아 줘. 고갯길을 세 번만 훑어 주면 내가 나머지는 다 지고 갈 수 있어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_porter', 2, '줄어든 쌀자루', '빙혼곡을(를) 살핀다', '{"at": ["frost_valley"], "tasks": [{"t": "search", "r": ["frost_valley"], "n": 3}]}'::jsonb, '[{"s": null, "t": "고갯길 곳곳에서 소금 섬과 쌀자루를 찾아 지게 옆에 쌓았다. 그런데 쌀자루 하나가 처음보다 눈에 띄게 홀쭉했다."}, {"s": null, "t": "덤바우가 그 자루를 등 뒤로 슬쩍 감췄다. 입가에 쌀알 하나가 붙어 있었다."}, {"s": "q:sx_mk_dumbawoo", "t": "이, 이건 까마귀가 쪼아 먹은 거야. 까마귀가 엄청 컸거든. 나만 했어."}, {"s": null, "t": "나는 덤바우의 입가를 가리켰다. 덤바우는 쌀알을 떼어 냈다가, 그것마저 입에 넣고 우물거렸다."}, {"s": "q:sx_mk_dumbawoo", "t": "……생쌀은 맛도 없더라. 그래도 나루 사람들한테 모자란 쌀을 내밀 순 없잖아. 노정 건량 세 개만 지어 줘. 그걸로 모자란 몫을 채울게. 소금 한 줌씩 덤으로 얹어 주면 아무도 뭐라 안 할 거야."}]'::jsonb, '{"xp": 3093}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_porter', 3, '고개 너머', '노정 건량을(를) 만든다, 노정 건량을(를) 넘긴다', '{"at": ["frost_valley"], "tasks": [{"t": "craft", "items": ["travel_ration"], "n": 3}], "give": {"travel_ration": 3}}'::jsonb, '[{"s": null, "t": "내가 지어 온 노정 건량을 덤바우는 쌀자루 맨 위에 조심스럽게 얹었다. 하나를 집어 들고 한참 들여다보다가, 마음을 고쳐먹은 듯 도로 내려놓았다."}, {"s": "q:sx_mk_dumbawoo", "t": "이건 내 거 아니야. 나루 사람들 거야. 나는 참을 수 있어. ……아마도."}, {"s": null, "t": "덤바우는 지게를 지고 일어섰다. 다리가 후들거렸지만 목소리는 다시 커졌다."}, {"s": "q:sx_mk_dumbawoo", "t": "자, 나루까지 같이 가자! 가서 주막 평상에 드러누울 거야. 해가 질 때까지 아무도 나 못 깨워."}]'::jsonb, '{"xp": 3093}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_porter', 4, '주인 없는 소금 한 섬', '묵창 나루에 간다, 묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "travel", "r": ["mukchang_ferry"], "n": 1}, {"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "주막 평상에서 한숨 자고 일어나 보니, 덤바우의 지게 둘레에 나루 사람들이 모여 있었다. 짐마다 적어 둔 받는 사람 이름이 먹비에 모두 지워져 있었다."}, {"s": "q:sx_mk_dumbawoo", "t": "큰일 났네. 누가 누구 짐인지 하나도 모르겠어."}, {"s": null, "t": "나루 사람들은 이름 대신 저마다 사는 자리를 댔다. 우물가 집은 쌀 한 자루를, 선창 끝 집은 소금 두 섬을, 주막은 소금 세 섬을 받아 갔다."}, {"s": null, "t": "마지막으로 소금 한 섬이 남았다. 아무도 제 것이라고 나서지 않았다. 덤바우가 머리를 긁적이며 그 섬을 주막 아주머니 앞에 내려놓았다."}, {"s": "q:sx_mk_dumbawoo", "t": "이건…… 내가 이 고개를 넘을 때마다 주막에서 얻어먹은 국밥값이야. 이번엔 꼭 갚으려고 하나 더 지고 왔어."}, {"s": null, "t": "덤바우는 그렇게 말하고는 노정 건량 하나를 슬쩍 집어 들었다. 이번에는 아무도 말리지 않았다."}]'::jsonb, '{"xp": 3093, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
