delete from public.world_quest_steps where quest_id = 'mks_tab_ledger' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_tab_ledger', 1, '하얀 장부', '하얀 장부', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "묵창 주막 평상에서 큰 소리가 났다. 주막 아주머니가 국자를 든 채 장부 한 권을 펼쳐 들고 손님들 앞에 서 있었다. 장부 안은 눈이 내린 것처럼 하얬다."}, {"s": "q:sx_mk_jumak", "t": "봐! 다 지워졌어! 석 달 치 외상이 한 줄도 안 남았다고!"}, {"s": null, "t": "평상에 앉은 손님들은 일제히 딴청을 피웠다. 국밥집 노인이 수염을 쓰다듬으며 먼저 입을 열었다."}, {"s": "q:sx_mk_gukbap", "t": "나야 국밥집을 하는 사람이야. 내가 남의 집 국밥을 왜 먹어. 왜 먹겠어. 내 이름은 그 장부에 처음부터 없었을 거야."}, {"s": null, "t": "그 옆에서 독장수가 손사래를 쳤다. 귀 끝이 빨갰다."}, {"s": "q:sx_mk_dokjang", "t": "저는 물만 마셨어요. 진짜예요. 장독 지고 다니면 목이 마르잖아요."}, {"s": null, "t": "아주머니는 국자로 평상을 탁 내리쳤다. 그러다 나를 발견하고는 국자 끝으로 나를 가리켰다."}, {"s": "q:sx_mk_jumak", "t": "마침 잘 왔어, 바깥 양반. 장부부터 다시 매야겠어. 먹비 맞은 종이는 다시 써도 또 지워지거든."}, {"s": "q:sx_mk_jumak", "t": "빈칸 벌판에 흩어진 서리 짐에서 나오는 빈칸 한지는 안 지워진대. 세 장만 주워다 줘. 오늘 국밥값은 내가 받을 테니까 그걸로 쳐."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_tab_ledger', 2, '기억하는 손님들', '빈칸 벌판에서 빈칸 한지을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["blank_hanji"], "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "내가 주워 온 빈칸 한지를 받아 든 아주머니는 그 자리에서 실로 꿰매 새 장부를 맸다. 그러고는 붓을 들었다가 그대로 멈췄다."}, {"s": "q:sx_mk_jumak", "t": "……그런데 누가 뭘 먹었는지를 내가 모르네."}, {"s": null, "t": "평상의 손님들이 동시에 숨을 내쉬었다. 국밥집 노인은 아예 눈을 감고 콧노래를 불렀다."}, {"s": null, "t": "아주머니가 국자로 제 이마를 톡톡 두드리다가, 무언가 생각난 듯 벌판 쪽 하늘을 올려다보았다."}, {"s": "q:sx_mk_jumak", "t": "바깥 양반, 먹귀가 사람 기억을 들고 다닌다며? 이 주막 평상에서 밥 먹던 사람들 가운데 이름이 거둬진 사람도 많아. 그 사람들은 다 기억하고 있을 거야. 누가 누구랑 앉아서 뭘 먹었는지."}, {"s": "q:sx_mk_jumak", "t": "빈칸 벌판에서 떠도는 먹귀를 여덟만 풀어 보내 봐. 하나라도 이 평상 이야기를 들고 있으면 그걸로 장부를 쓰자고."}, {"s": null, "t": "독장수의 귀가 새빨개졌다."}]'::jsonb, '{"xp": 3093}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_tab_ledger', 3, '막걸리 세 사발', '떠도는 먹귀을(를) 물리친다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "win", "m": ["mk_field_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "먹귀를 풀어 보낼 때마다 남의 기억이 손끝을 스쳐 갔다. 그 가운데 셋은 이 주막 평상에 앉아 있었다."}, {"s": null, "t": "하나는 독장수가 막걸리 세 사발을 시켜 놓고 「외상!」을 외치던 저녁이었다. 하나는 국밥집 노인이 국밥을 두 그릇 비우고 「우리 집이 더 낫군」 하던 점심이었다."}, {"s": null, "t": "내가 들은 대로 이야기하자, 평상이 조용해졌다. 독장수가 두 손으로 귀를 감쌌다."}, {"s": "q:sx_mk_dokjang", "t": "그, 그건…… 물처럼 맑은 막걸리였어요. 그러니까 물 마신 거나 마찬가지예요."}, {"s": null, "t": "국밥집 노인은 수염을 쓰다듬던 손을 멈추고 먼 산을 보았다."}, {"s": "q:sx_mk_gukbap", "t": "맛을 보러 온 거였어. 장사꾼은 남의 국밥 맛을 알아야 해. 알아야 하고말고. 두 그릇은 비교를 하느라 그런 거야."}, {"s": null, "t": "아주머니는 국자를 허리춤에 꽂고 새 장부에 두 사람 몫을 큼직하게 적었다. 그러고는 남은 장을 넘기며 한숨을 쉬었다."}, {"s": "q:sx_mk_jumak", "t": "이게 다가 아니야. 석 달이면 손님이 백은 넘어. 바깥 양반, 오늘은 여기 눌러앉아서 나랑 같이 장부를 맞춰 줘. 기억나는 걸 하나씩 불러 주면 내가 받아 적을게."}]'::jsonb, '{"xp": 3093}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_tab_ledger', 4, '갚음', '자율 활동을 끝까지 마친다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "idle", "n": 1, "k": "research"}]}'::jsonb, '[{"s": null, "t": "해가 지도록 아주머니와 나는 장부를 맞췄다. 마지막 장까지 이름이 들어차자, 국밥집 노인의 외상이 서른두 그릇이라는 셈이 나왔다."}, {"s": "q:sx_mk_gukbap", "t": "……비교를 꽤 오래 했네. 꽤 오래."}, {"s": null, "t": "손님들이 한바탕 웃었다. 아주머니도 웃다가, 맨 끝 장에서 붓을 멈췄다."}, {"s": null, "t": "먹귀의 기억 하나가 남아 있었다. 이름이 거둬진 늙은 뱃사람이 평상 구석에서 국 한 그릇을 먹고, 엽전이 모자라 고개를 숙이던 저녁이었다."}, {"s": null, "t": "아주머니는 그 사람의 몫을 장부에 적었다. 그 옆에 붓으로 두 글자를 덧붙였다."}, {"s": null, "t": "「갚음」."}, {"s": "q:sx_mk_jumak", "t": "그 양반, 그 뒤로 날마다 우리 주막 앞을 쓸어 줬어. 그럼 갚은 거지. 내가 그걸 깜빡했네."}, {"s": null, "t": "아주머니는 장부를 덮고 국자로 솥을 두드렸다. 독장수가 슬그머니 엽전 꾸러미를 평상에 올려놓았다. 귀가 아직도 빨갰다."}]'::jsonb, '{"xp": 3093, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
