values ('mks_crow_letters', 'side', '전투·빈칸 벌판', '까마귀가 쪼아 간 글자', '빈칸 까마귀 떼가 문패 글자를 물어다 나른다. 떨어진 글자가 엉뚱한 문패에 붙어 나루에 엉터리 이름이 생겼다.', 'blank_field', 41, '{mkq_1}'::text[], null, 1314, '[]'::jsonb, true, null, null)
