delete from public.world_quest_steps where quest_id = 'mks_crow_letters' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_crow_letters', 1, '건넛까악', '건넛까악', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "나루 골목에서 작은 아이 하나가 대문 앞에 서서 볼을 잔뜩 부풀리고 있었다. 아이는 대문 위 문패를 손가락으로 가리켰다."}, {"s": null, "t": "문패에는 「건넛까악」이라고 적혀 있었다. 「집」 자리에 낯선 글자 두 개가 비뚤게 붙어 있었다."}, {"s": "q:sx_mk_geonneot", "t": "이것 좀 봐요! 아침에 분명 건넛집이라고 썼거든요. 그런데 까마귀가 날아가면서 이상한 글자를 떨어뜨렸어요."}, {"s": "q:sx_mk_geonneot", "t": "이제 다들 저를 건넛까악이라고 불러요. 저 까악 아니에요!"}, {"s": null, "t": "아이가 발을 동동 굴렀다. 그 머리 위로 까마귀 한 마리가 지나가며 무언가를 떨어뜨렸다. 글자 하나가 옆집 문패에 철썩 붙었다."}, {"s": "q:sx_mk_geonneot", "t": "또 그래! 빈칸 벌판에서 오는 까마귀들이에요. 벌판의 빈칸 까마귀 떼를 여덟만 쫓아 주세요. 그럼 덜 오겠죠?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_crow_letters', 2, '그래도 떨어지는 글자', '빈칸 까마귀 떼을(를) 물리친다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "win", "m": ["mk_field_2"], "n": 8}]}'::jsonb, '[{"s": null, "t": "까마귀 떼를 쫓고 나루로 돌아오자, 아이는 대문 앞에 쪼그려 앉아 떨어진 글자들을 바구니에 줍고 있었다. 바구니 안에서 글자들이 꼼지락거렸다."}, {"s": "q:sx_mk_geonneot", "t": "덜 오긴 해요. 그런데 아직도 떨어져요. 까마귀가 글자를 어디 모아 두나 봐요."}, {"s": null, "t": "아이는 바구니에서 「까」 자를 집어 들고 눈을 가늘게 떴다."}, {"s": "q:sx_mk_geonneot", "t": "할머니가 그러는데요, 까마귀는 반짝이는 걸 둥지에 모은대요. 지워진 문패 글자도 반짝이나 봐요. 벌판 어딘가에 둥지가 있을 거예요. 세 번만 둘러봐 주세요."}]'::jsonb, '{"xp": 3236}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_crow_letters', 3, '글자 둥지', '빈칸 벌판을(를) 살핀다', '{"at": ["blank_field"], "tasks": [{"t": "search", "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "벌판 안쪽, 까마귀 앉은 장승 꼭대기에 커다란 둥지가 얹혀 있었다. 둥지는 나뭇가지가 아니라 문패에서 떨어져 나온 글자들로 엮여 있었다."}, {"s": null, "t": "둥지에는 「돌」·「순」·「댁」·「집」 같은 글자 수백 개가 서로 얽혀 있었다. 바람이 불 때마다 글자들이 바스락거렸다."}, {"s": null, "t": "어느새 따라온 아이가 장승 밑에서 까치발을 들고 둥지를 올려다보았다. 입이 떡 벌어져 있었다."}, {"s": "q:sx_mk_geonneot", "t": "와, 나루 사람들 이름이 다 여기 있네요. 그런데 이 중에 우리 집 「집」은 어느 거예요?"}, {"s": "q:sx_mk_geonneot", "t": "우리 집 글자는 할머니가 써서 끝이 동그랗게 말려 있어요. 잘 찾아봐 주세요. 저는 키가 안 닿아요."}]'::jsonb, '{"xp": 3236}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_crow_letters', 4, '끝이 말린 글자', '빈칸 벌판에서 실마리를 찾는다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "clue", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "둥지 한가운데에서 끝이 동그랗게 말린 「집」 자를 찾아냈다. 나루로 돌아와 아이 손바닥에 그 글자를 올려 주었다."}, {"s": null, "t": "아이가 글자를 문패 제자리에 꾹 눌러 붙이자, 문패가 다시 「건넛집」이 되었다. 아이는 문패 앞에서 팔짝팔짝 뛰었다."}, {"s": "q:sx_mk_geonneot", "t": "됐다! 이제 저 건넛집 꼬마예요!"}, {"s": null, "t": "그때 까마귀 한 마리가 지붕 위에 내려앉았다. 부리에 글자 하나를 물고 있었다. 까마귀는 아이 앞에 그 글자를 톡 떨어뜨리고 날아갔다."}, {"s": null, "t": "「꼬」 자였다. 아이는 그 글자를 주워 들고 한참 들여다보다가 품에 넣었다."}, {"s": "q:sx_mk_geonneot", "t": "이건 선물인가 봐요. 까마귀도 제가 꼬마인 걸 아나 봐요. 이건 버리지 말고 가지고 있을래요."}]'::jsonb, '{"xp": 3236, "gil": 169, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
