insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_snakehead', 1, '지워지는 지도', '지워지는 지도', '{"at": ["blank_field"]}'::jsonb, '[{"s": null, "t": "빈칸 벌판 들머리 둔덕에 사내 하나가 화판을 세워 놓고 앉아 있었다. 사내는 붓대를 입에 문 채 화판의 지도와 벌판을 번갈아 보았다."}, {"s": null, "t": "지도는 빈틈없이 그려져 있었다. 둑길도, 고랑도, 쓰러진 이정표도 있었다. 다만 벌판 안쪽 늪 자리만 하얗게 비어 있었다."}, {"s": "q:sx_mk_nungeum", "t": "아, 조사원이시죠? 저는 정청 측량 서리예요. 다들 눈금이라고 불러요. 눈금만 보고 산다고요."}, {"s": "q:sx_mk_nungeum", "t": "이 벌판 지도를 벌써 아흐레째 그리고 있어요. 그런데 여기, 번진 먹 늪 자리만 아침마다 빈칸이 돼 있어요. 어제 분명히 그렸는데요."}, {"s": null, "t": "눈금이는 붓대로 허공에 늪 둘레를 그려 보였다. 나는 누가 지우는 것이냐고 물었다."}, {"s": "q:sx_mk_nungeum", "t": "그걸 모르겠어요. 밤에 지켜도 봤는데, 지도에 손대는 사람은 없었어요. 대신 늪에서 철벅 소리가 나더라고요. 큰 물고기가 뛰는 소리요."}, {"s": "q:sx_mk_nungeum", "t": "늪가 사람들은 빈칸 가물치 짓이라고 해요. 지워진 자리를 몸에 지고 다니는 가물치래요. 이름을 믿는 정청 사람이 이런 말을 하면 좀 우습지만요."}, {"s": "q:sx_mk_nungeum", "t": "그래도 확인은 해 봐야죠. 가물치를 낚으려면 미꾸라지나 드렁허리, 갈대 버들붕어, 먹점 납자루 같은 늪물고기가 미끼로 있어야 한대요. 번진 먹 늪에서 세 번만 낚아 주시겠어요?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_snakehead', 2, '늪가의 손', '빈칸 벌판에서 낚시를 한다', '{"at": ["blank_field"], "tasks": [{"t": "fish", "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "늪물고기를 바구니에 담아 둔덕으로 돌아오니, 눈금이가 화판 앞에 서서 늪 쪽을 노려보고 있었다. 화판 모서리가 찢겨 나가 있었다."}, {"s": "q:sx_mk_nungeum", "t": "조사원이 낚시하는 동안 억새 그늘에서 손이 쑥 나왔어요. 지도 모서리를 뜯어 가더라고요. 꼭 문패를 뜯듯이요."}, {"s": null, "t": "눈금이는 찢긴 자리를 손가락으로 쓸었다. 거기에는 늪가 둑길의 이름이 적혀 있었다."}, {"s": "q:sx_mk_nungeum", "t": "문패 뜯는 손이에요. 이름 적힌 건 뭐든 잡아채요. 저것들이 늪가에 몰려 있으면 밤에 낚싯대를 드리울 수가 없어요."}, {"s": "q:sx_mk_nungeum", "t": "늪가에 숨은 문패 뜯는 손을 넷만 풀어 보내 주세요. 그동안 저는 뜯긴 자리를 다시 그릴게요."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_snakehead', 3, '구름 낀 삼경', '문패 뜯는 손을(를) 물리친다', '{"at": ["blank_field"], "tasks": [{"t": "win", "m": ["mk_field_3"], "n": 4}]}'::jsonb, '[{"s": null, "t": "문패 뜯는 손이 흩어지자 늪가가 조용해졌다. 눈금이는 다시 그린 둑길을 손등으로 문질러 보고, 먹이 번지지 않는 것을 확인했다."}, {"s": "q:sx_mk_nungeum", "t": "이제 낚시만 남았네요. 늪가 사람들 말로는 빈칸 가물치가 구름 낀 삼경에만 올라온대요. 담운 끼어 달도 별도 안 보이는 밤이요."}, {"s": "q:sx_mk_nungeum", "t": "저는 그 시각에 화판 앞에 붙어 있을 거예요. 가물치가 올라오는 순간 지도가 어떻게 되는지 봐야 하니까요."}, {"s": null, "t": "눈금이는 붓을 먹물에 담갔다 꺼내 들고 늪 쪽으로 화판을 돌려 세웠다."}, {"s": "q:sx_mk_nungeum", "t": "미끼는 아까 낚은 늪물고기를 거세요. 담운 낀 삼경에, 번진 먹 늪에서요. 부탁드려요."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_snakehead', 4, '몸에 진 빈칸', '빈칸 벌판에서 빈칸 가물치을(를) 낚는다', '{"at": ["blank_field"], "tasks": [{"t": "fish", "r": ["blank_field"], "f": ["blank_snakehead"], "n": 1}]}'::jsonb, '[{"s": null, "t": "캄캄한 늪에서 끌어올린 가물치는 몸통 한가운데가 종이처럼 하얬다. 하얀 자리에는 둑길과 고랑의 선이 희미하게 비쳤다. 눈금이의 지도에서 사라졌던 바로 그 늪이었다."}, {"s": null, "t": "눈금이가 등불을 들고 달려왔다. 화판의 빈칸과 가물치의 하얀 몸을 번갈아 보더니, 붓을 떨어뜨렸다."}, {"s": "q:sx_mk_nungeum", "t": "지도가…… 고기 몸으로 옮겨 가 있었네요."}, {"s": "q:sx_mk_nungeum", "t": "이 늪은 정청이 이름을 거둔 마을 자리예요. 기록에 그렇게 적혀 있어요. 지도에 그리면 그 마을이 다시 있는 것처럼 보이니까, 늪이 그걸 안 받아 주는 거예요."}, {"s": null, "t": "눈금이는 한동안 말이 없었다. 그러다 떨어뜨린 붓을 주워 들고, 나를 보았다."}, {"s": "q:sx_mk_nungeum", "t": "지우지도 못하고, 그리지도 못하면 빈칸을 메우는 수밖에 없겠어요. 이 가물치로 빈칸 메움 환을 빚으면, 빈자리에 스미는 요기가 준대요."}, {"s": "q:sx_mk_nungeum", "t": "하나만 빚어다 주세요. 늪가에 뿌려 보고, 그래도 지도가 지워지면 그때는 저도 포기할게요."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_snakehead', 5, '빈칸이라고 적은 자리', '빈칸 메움 환을(를) 만든다, 빈칸 메움 환을(를) 넘긴다', '{"at": ["blank_field"], "tasks": [{"t": "craft", "items": ["blank_fill_pill"], "n": 1}], "give": {"blank_fill_pill": 1}}'::jsonb, '[{"s": null, "t": "빈칸 메움 환을 건네자, 눈금이는 환을 늪가에 녹여 뿌렸다. 늪 위의 먹 얼룩이 조금 옅어졌다."}, {"s": null, "t": "눈금이는 화판 앞에 앉아 늪 자리를 다시 그리려다 붓을 멈췄다. 한참 생각하더니, 빈칸 한가운데에 작은 글씨로 무언가를 적었다."}, {"s": null, "t": "「여기 마을이 있었음. 이름은 거둬짐.」"}, {"s": "q:sx_mk_nungeum", "t": "그려 넣을 수 없으면, 없다는 걸 적어 두는 게 맞겠죠. 측량은 있는 걸 적는 일이지만, 없어진 것도 있었던 거니까요."}, {"s": null, "t": "이튿날 아침, 눈금이가 화판을 들고 나를 찾아왔다. 빈칸 한가운데의 그 글씨는 지워지지 않고 남아 있었다."}]'::jsonb, '{"xp": 2427, "gil": 169, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
