values ('mks_nameless_boat', 'side', '제작·묵창 나루', '이름 없는 나룻배', '이름이 지워진 나룻배가 강 한가운데서 꼼짝하지 않는다. 늙은 사공은 배에도 이름이 있어야 물이 길을 내준다고 한다.', 'mukchang_ferry', 41, '{mkq_1}'::text[], null, 1316, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_nameless_boat' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_nameless_boat', 1, '서 버린 배', '서 버린 배', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "선창 끝에서 늙은 사공 노을 영감이 장대를 짚고 강을 노려보고 있었다. 강 한가운데에 빈 나룻배 한 척이 물살도 없는데 그대로 멈춰 있었다."}, {"s": "q:sx_mk_sagong", "t": "저 배가 오늘 아침부터 서 버렸네. 노를 저어도, 장대로 밀어도 꿈쩍을 안 하네."}, {"s": null, "t": "사공은 장대 끝으로 물을 한 번 짚었다. 그러고는 배의 뱃머리를 가리켰다. 뱃머리에 써 둔 글자가 하나도 남지 않았다."}, {"s": "q:sx_mk_sagong", "t": "먹비에 배 이름이 지워졌네. 이 강은 이름 없는 배를 안 받아 주거든. 사람도 배도 이름이 있어야 물이 길을 내준다고, 우리 아버지가 그랬지."}, {"s": null, "t": "나는 다시 써 넣으면 되지 않느냐고 물었다. 사공은 고개를 저었다."}, {"s": "q:sx_mk_sagong", "t": "아무 먹으로 쓰면 또 지워지네. 빈칸 벌판 물가에 묵창 갈대 먹이 나는데, 그 먹이라야 버티지. 두 덩이만 걷어다 주게. 배는 내가 끌어오겠네."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_nameless_boat', 2, '생각나지 않는 이름', '빈칸 벌판에서 묵창 갈대 먹을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["mukchang_ink"], "r": ["blank_field"], "n": 2}]}'::jsonb, '[{"s": null, "t": "내가 갈대 먹을 걷어 오자, 사공은 어느새 밧줄로 배를 선창까지 끌어다 놓고 있었다. 사공은 먹을 벼루에 갈고 붓을 들었다. 그러고는 뱃머리 앞에서 한참을 서 있었다."}, {"s": "q:sx_mk_sagong", "t": "……이상하군. 이 배 이름이 생각나지 않네."}, {"s": null, "t": "사공은 장대로 물을 짚으려다 말고 장대를 내려놓았다. 손이 허공에서 갈 곳을 잃었다."}, {"s": "q:sx_mk_sagong", "t": "이 배는 우리 할멈이 이름을 붙였네. 처음 띄우던 날, 강 건너 빙혼곡 쪽 매어 두는 말뚝에 그 이름을 새겼지. 거기 가면 있을 걸세."}, {"s": "q:sx_mk_sagong", "t": "그런데 이름 없는 배로 강을 건너려면 물값을 내야 하네. 강에서 낚은 물고기 두 마리를 강에 돌려주면, 물이 한 번은 봐준다는 말이 있지. 손님이 여울에서 두 마리만 낚아 주게."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_nameless_boat', 3, '물값', '묵창 나루에서 낚시를 한다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "n": 2}]}'::jsonb, '[{"s": null, "t": "내가 낚아 온 물고기 두 마리를 사공이 뱃전에서 강물에 놓아주었다. 물고기가 꼬리를 한 번 치고 사라지자, 배가 스르르 물살을 타기 시작했다."}, {"s": "q:sx_mk_sagong", "t": "됐네. 한 번은 봐준다는군."}, {"s": null, "t": "사공은 노를 잡았다. 그러고는 고물에 앉은 나를 돌아보며 장대로 강 건너를 가리켰다."}, {"s": "q:sx_mk_sagong", "t": "빙혼곡 쪽 물가에 말뚝이 여럿 박혀 있네. 서리를 맞아 다 비슷해 보일 걸세. 둘러보며 할멈 글씨가 남은 말뚝을 찾아 주게."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_nameless_boat', 4, '말뚝에 새긴 글자', '빙혼곡에 간다, 빙혼곡을(를) 살핀다', '{"at": ["frost_valley"], "tasks": [{"t": "travel", "r": ["frost_valley"], "n": 1}, {"t": "search", "r": ["frost_valley"], "n": 2}]}'::jsonb, '[{"s": null, "t": "서리 덮인 물가를 뒤지다가, 이끼 낀 말뚝 하나에서 칼로 새긴 글자를 찾았다. 서리를 손으로 털어 내자 비뚤배뚤한 글씨가 드러났다."}, {"s": null, "t": "「우리 배」."}, {"s": null, "t": "그 글자를 본 사공이 한동안 말이 없었다. 그러다 장대로 물을 한 번 짚고 크게 웃었다."}, {"s": "q:sx_mk_sagong", "t": "하하. 그렇지. 할멈이 이름을 따로 안 지었네. 그냥 우리 배라고 불렀지. 그러니 내가 아무리 떠올려도 이름이 안 나왔던 걸세."}, {"s": "q:sx_mk_sagong", "t": "이번에는 안 지워지게 써야겠네. 이름 먹 부적 두 장을 지어 주게. 하나는 뱃머리에 붙이고, 하나는 이 말뚝에 매어 두겠네."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_nameless_boat', 5, '우리 배', '이름 먹 부적을(를) 만든다, 이름 먹 부적을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["name_ink_charm"], "n": 2}], "give": {"name_ink_charm": 2}}'::jsonb, '[{"s": null, "t": "사공은 내가 지어 온 부적 한 장에 「우리 배」라고 적어 빙혼곡 쪽 말뚝에 매었다. 다른 한 장은 나루로 돌아와 뱃머리에 붙였다."}, {"s": null, "t": "사공이 장대로 선창을 밀자, 배가 미끄러지듯 강으로 나아갔다. 물살이 뱃머리를 비켜 가며 길을 열었다."}, {"s": "q:sx_mk_sagong", "t": "손님, 이 배를 탈 일이 있으면 언제든 오게. 손님 뱃삯은 할멈 몫으로 받겠네."}, {"s": null, "t": "나는 할멈 몫이 무엇이냐고 물었다. 사공은 장대로 물을 한 번 짚고 먼 산을 보았다."}, {"s": "q:sx_mk_sagong", "t": "우리 배라고 한 번만 불러 주면 되네. 할멈이 그 소리를 제일 좋아했지."}]'::jsonb, '{"xp": 2427, "gil": 169, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
