insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mks_reed_clinic', 'side', '제작·빈칸 벌판', '억새 속 약막', '정청 의무소에서 쫓겨난 늙은 의원이 빈칸 벌판 한가운데 약막을 차렸다. 의원은 이름이 흐린 사람만 돌본다.', 'blank_field', 41, '{mkq_1}'::text[], null, 1317, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_reed_clinic' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_reed_clinic', 1, '억새 속 지붕', '억새 속 지붕', '{"at": ["blank_field"]}'::jsonb, '[{"s": null, "t": "흰 억새 들 한가운데에 억새로 지붕을 얹은 초막이 있었다. 초막 앞에서 늙은 사내 하나가 약초를 다듬으며 탕약을 달이고 있었다."}, {"s": null, "t": "사내는 나를 흘끗 보고는 손에 든 약초를 내려놓지 않은 채 말했다."}, {"s": "q:sx_mk_yakmak", "t": "다친 데가 없으면 그냥 지나가시오. 나는 몸 다친 사람은 안 보오."}, {"s": null, "t": "나는 그럼 누구를 보느냐고 물었다. 의원은 약탕기 뚜껑을 열어 김을 한 번 날려 보냈다."}, {"s": "q:sx_mk_yakmak", "t": "이름이 흐린 사람을 보오. 정청 의무소에 있을 때 그런 사람을 돌보다가 쫓겨났소. 이름 흐린 것은 병이 아니라는 거요. 병이 아니면 아픈 것도 아니라는 거지."}, {"s": "q:sx_mk_yakmak", "t": "아프지 않다는 사람이 밤마다 울고 있으니, 나는 병으로 치고 고치오. 할 일이 많소. 야령초가 떨어졌소. 이 벌판에 나는 야령초 세 줌만 캐 오시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_reed_clinic', 2, '쓴 약', '빈칸 벌판에서 야령초을(를) 모은다', '{"at": ["blank_field"], "tasks": [{"t": "gather", "items": ["herb"], "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "내가 캐 온 야령초를 의원은 손으로 비벼 냄새를 맡아 보았다. 그러고는 고개를 끄덕이고 약초 바구니에 던져 넣었다."}, {"s": "q:sx_mk_yakmak", "t": "쓸 만하오. 그런데 이것만으로는 안 되오. 이름이 흐린 사람은 마음이 먼저 흔들리오. 마음이 흔들리면 남은 이름도 놓치오."}, {"s": null, "t": "의원은 다듬던 약초를 손에 쥔 채 초막 안쪽을 가리켰다. 거적 위에 사람 셋이 웅크려 잠들어 있었다."}, {"s": "q:sx_mk_yakmak", "t": "저 사람들한테 청심환 세 알을 먹여야겠소. 내 손이 떨려 환을 빚기가 어렵소. 손님이 지어 주시오."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_reed_clinic', 3, '서로 부르는 밤', '청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["blank_field"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 3}], "give": {"tonic": 3}}'::jsonb, '[{"s": null, "t": "의원은 내가 지어 온 청심환을 한 알씩 물에 풀어 잠든 사람들의 입에 흘려 넣었다. 그러고는 초막 문간에 앉아 하늘을 보았다."}, {"s": "q:sx_mk_yakmak", "t": "약은 반이오. 나머지 반은 밤에 하오. 손님도 오늘은 여기서 묵으시오. 이 약막이 무엇을 고치는지 보여 드리겠소."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_reed_clinic', 4, '이름 부르기', '빈칸 벌판에서 쉰다', '{"at": ["blank_field"], "tasks": [{"t": "rest", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤이 깊자 잠들었던 사람들이 하나둘 일어났다. 그들은 모닥불 둘레에 둘러앉아 서로의 얼굴을 보며 이름을 불렀다. 한 사람이 부르면 불린 사람이 대답하고, 그 사람이 다음 사람을 불렀다."}, {"s": null, "t": "대답이 늦는 사람이 있으면 모두 기다렸다. 아무도 재촉하지 않았다."}, {"s": null, "t": "의원은 모닥불에 약초를 하나 던져 넣고 나를 보았다."}, {"s": "q:sx_mk_yakmak", "t": "이름은 누가 불러 줘야 붙어 있소. 정청은 그걸 약으로 치지 않소. 나는 치오."}, {"s": "q:sx_mk_yakmak", "t": "그런데 이 약막까지 오는 길이 험해서, 오다가 먹귀에게 붙들리는 사람이 많소. 손님, 벌판을 한 번 크게 돌며 길을 터 주시오. 나루에서 오는 사람들이 덜 다치게."}]'::jsonb, '{"xp": 2427}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_reed_clinic', 5, '늘어난 자리', '빈칸 벌판에 원정을 다녀온다', '{"at": ["blank_field"], "tasks": [{"t": "expedition", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정에서 돌아오니 약막 앞에 낯선 얼굴이 넷이나 더 앉아 있었다. 내가 터 놓은 길을 따라 나루에서 걸어온 사람들이었다."}, {"s": null, "t": "의원은 약초를 쥔 손으로 새로 온 사람들을 하나씩 가리키며 자리를 정해 주었다. 무뚝뚝한 말투는 그대로였는데, 거적을 깔아 주는 손은 느리고 조심스러웠다."}, {"s": "q:sx_mk_yakmak", "t": "자리가 모자라겠소. 지붕을 넓혀야겠군."}, {"s": null, "t": "의원은 그렇게 말하고는 처음으로 약초를 내려놓았다. 그리고 새로 온 사람 앞에 쪼그려 앉아 이름을 물었다."}]'::jsonb, '{"xp": 2427, "gil": 169, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
