values ('mks_n_salmon', 'side', '낚시·먹비 숲', '남의 꿈을 거슬러', '남의 꿈만 꾸는 약초꾼에게 하룻밤 제 꿈을 돌려준다.', 'meokbi_forest', 42, '{mkq_2}'::text[], null, 1318, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_n_salmon' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_salmon', 1, '남의 아궁이', '남의 아궁이', '{"at": ["meokbi_forest"]}'::jsonb, '[{"s": null, "t": "먹비 숲 들머리 비가림 아래에 작은 약초막이 있었다. 늙은 할미 하나가 처마 밑에 앉아 약초를 다듬다가, 손을 멈추고 꾸벅 졸았다."}, {"s": null, "t": "내가 다가가자 할미가 눈을 떴다. 눈동자가 한참 동안 나를 알아보지 못하고 헤맸다."}, {"s": "q:sx_mk_pulnae", "t": "아…… 미안하오. 방금 남의 집 아궁이 앞에 앉아 있었소. 처음 보는 집이었는데, 불 냄새가 아주 좋았소."}, {"s": "q:sx_mk_pulnae", "t": "이 숲에서 약초를 캔 지 쉰 해요. 먹비를 하도 맞아서, 언제부턴가 잠만 들면 남의 꿈을 꾸오. 내 꿈은 꾼 지가 오래되었소."}, {"s": null, "t": "할미는 다듬던 약초를 바구니에 넣고 손바닥을 내려다보았다. 손금마다 먹물이 배어 있었다."}, {"s": "q:sx_mk_pulnae", "t": "숲 사람들 말이 있소. 먹비 오는 새벽에 못을 거슬러 오르는 대산천어를 보면, 하룻밤 제 꿈을 돌려받는다고."}, {"s": "q:sx_mk_pulnae", "t": "늙은이 소원 하나 들어 주겠소? 그 전에 먹비 이끼를 좀 캐다 주오. 이끼를 달여 마셔 두면 남의 꿈이 덜 끼어드오. 숲에서 세 번만 캐면 되오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_salmon', 2, '미끼가 될 고기', '먹비 숲에서 먹비 이끼을(를) 모은다', '{"at": ["meokbi_forest"], "tasks": [{"t": "gather", "items": ["meokbi_moss"], "r": ["meokbi_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "캐 온 먹비 이끼를 건네자, 풀내는 그것을 탕관에 넣고 약초막 화로에 올렸다. 쓴 냄새가 처마 밑에 고였다."}, {"s": "q:sx_mk_pulnae", "t": "이제 고기 이야기를 하오. 대산천어는 못물고기 냄새를 맡고 올라오오. 빙어나 열목어, 안개 낀 날이면 물안개 각시붕어도 좋소."}, {"s": "q:sx_mk_pulnae", "t": "그것들을 먼저 낚아 가방에 넣어 두오. 낚시할 때 낚시 칸에서 미끼로 골라 걸면 되오. 우리 영감도 그렇게 했소."}, {"s": null, "t": "할미는 영감 이야기를 하고는 눈을 감았다. 잠깐 졸았는지 고개가 앞으로 떨어졌다가 다시 들렸다."}, {"s": "q:sx_mk_pulnae", "t": "먹비 고인 못에서 세 번만 낚아 오오. 나는 그동안 이끼 탕을 달이고 있겠소."}]'::jsonb, '{"xp": 2536}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_salmon', 3, '약초막의 밤', '먹비 숲에서 낚시를 한다', '{"at": ["meokbi_forest"], "tasks": [{"t": "fish", "r": ["meokbi_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "못에서 낚은 물고기를 바구니째 내려놓자, 풀내는 이끼 탕을 한 사발 떠서 천천히 마셨다. 그리고 남은 탕을 내 쪽으로 밀었다."}, {"s": "q:sx_mk_pulnae", "t": "대산천어는 해돋이에 올라오오. 그것도 장우가 쏟아지는 새벽이어야 하오. 먹비가 억수로 내리는 날 말이오."}, {"s": "q:sx_mk_pulnae", "t": "그런 새벽은 기다려야 오오. 오늘 밤은 여기서 눈을 붙이오. 숲에서 자 봐야 이 숲 비가 언제 굵어지는지 알 수 있소."}, {"s": null, "t": "할미는 약초막 한쪽에 거적을 깔아 주었다. 처마 끝에서 먹물 같은 빗방울이 똑똑 떨어졌다."}]'::jsonb, '{"xp": 2536}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_salmon', 4, '거슬러 오르는 것', '먹비 숲에서 쉰다', '{"at": ["meokbi_forest"], "tasks": [{"t": "rest", "r": ["meokbi_forest"], "n": 1}]}'::jsonb, '[{"s": null, "t": "숲에서 하룻밤을 자고 나니 빗소리가 귀에 익었다. 굵어지는 비와 가늘어지는 비가 소리로 들렸다."}, {"s": null, "t": "풀내는 먼저 깨어 처마 밑에 앉아 있었다. 밤새 남의 꿈을 꾸었는지 눈 밑이 검었다."}, {"s": "q:sx_mk_pulnae", "t": "간밤에는 고깃배 위에 있었소. 누군가의 아들이 그물을 당기고 있었소. 그물이 무거웠소."}, {"s": "q:sx_mk_pulnae", "t": "남의 아들 꿈은 그만 꾸고 싶소. 장우 쏟아지는 해돋이에, 먹비 고인 못에서 대산천어를 낚아 주오. 내가 못가에 나가 지켜보겠소."}]'::jsonb, '{"xp": 2536}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_salmon', 5, '할미의 꿈', '먹비 숲에서 먹비 대산천어을(를) 낚는다', '{"at": ["meokbi_forest"], "tasks": [{"t": "fish", "r": ["meokbi_forest"], "f": ["meokbi_salmon"], "n": 1}]}'::jsonb, '[{"s": null, "t": "억수 같은 먹비 속에서 낚아 올린 대산천어는 물 밖에서도 꼬리로 비를 거슬러 치고 있었다. 풀내는 못가에 선 채 그것을 오래 보았다."}, {"s": null, "t": "할미는 아무 말 없이 약초막으로 돌아가 거적 위에 누웠다. 그날 낮, 할미는 해가 질 때까지 깨지 않았다."}, {"s": null, "t": "저녁에 눈을 뜬 풀내의 눈이 젖어 있었다."}, {"s": "q:sx_mk_pulnae", "t": "내 꿈을 꾸었소. 영감이 이 약초막 지붕을 고치고 있었소. 비가 새니까 빨리 내려오라고 내가 소리를 질렀소."}, {"s": "q:sx_mk_pulnae", "t": "영감은 내려오지 않고 웃기만 했소. 그 얼굴을 잊고 있었소. 이제 생각이 나오."}, {"s": null, "t": "할미는 지붕을 올려다보았다. 처마 한쪽은 아직도 비가 샜다."}, {"s": "q:sx_mk_pulnae", "t": "내일은 내가 지붕을 고쳐야겠소. 영감이 하다 만 데부터."}]'::jsonb, '{"xp": 2536, "gil": 173, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
