delete from public.world_quest_steps where quest_id = 'mks_other_brush' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_other_brush', 1, '비가림 아래의 노인', '비가림 아래의 노인', '{"at": ["meokbi_forest"]}'::jsonb, '[{"s": null, "t": "먹비 숲 들머리 비가림 아래에 늙은 사내 하나가 쪼그려 앉아 있었다. 무릎 위에 살이 부러진 우산을 펼쳐 놓고, 흑단 살을 한 대씩 갈아 끼우고 있었다."}, {"s": null, "t": "내가 비가림 안으로 들어서자 노인은 고개도 들지 않고 우산살을 손끝으로 퉁겼다."}, {"s": "q:sx_mk_daesal", "t": "젖지 말고 이리 들어와. 이 숲 비는 옷만 적시는 게 아니야."}, {"s": "q:sx_mk_daesal", "t": "난 대살이라고 해. 이 숲에 드나드는 사람들 우산을 고쳐 주고 밥을 얻어먹지."}, {"s": null, "t": "노인은 우산을 내려놓고 품에서 천에 싼 것을 꺼냈다. 천을 풀자 손가락 길이만 한 몽당붓 한 자루가 나왔다."}, {"s": "q:sx_mk_daesal", "t": "숲 안쪽 옛 조사원 숙소 알지? 지난달에 거기 지붕을 덮어 주러 갔다가 마루 밑에서 이걸 주웠어."}, {"s": "q:sx_mk_daesal", "t": "그 숙소 주인이던 조사원은 칼로 새긴 것처럼 반듯하게 쓰던 사람이라더군. 그런데 이 붓은 털이 다 비뚤어졌어. 어린애가 꾹꾹 눌러 쓴 붓이야."}, {"s": null, "t": "나는 그 붓이 왜 마음에 걸리느냐고 물었다. 노인은 대답 대신 우산살을 한 번 더 퉁겼다."}, {"s": "q:sx_mk_daesal", "t": "모르겠어. 쥐고 있으면 손바닥이 따뜻해. 그게 이상해서 그래."}, {"s": "q:sx_mk_daesal", "t": "숙소 둘레를 좀 살펴봐 줘. 붓 임자가 남긴 게 더 있을지도 모르니까. 숲 안쪽을 세 번쯤 돌아보면 뭐라도 나올 거야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_other_brush', 2, '기둥에 그은 금', '먹비 숲을(를) 살핀다', '{"at": ["meokbi_forest"], "tasks": [{"t": "search", "r": ["meokbi_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "숙소 둘레를 세 번 돌고 비가림으로 돌아왔다. 대살은 그새 우산 하나를 다 고쳐 놓고, 젖은 손을 앞치마에 문지르고 있었다."}, {"s": null, "t": "나는 숙소 뒤 처마 기둥에서 본 것을 이야기했다. 어른 허리 높이에 칼로 그은 금이 몇 줄 있었고, 금마다 옆에 글자 한 자씩이 반쯤 지워진 채 남아 있었다."}, {"s": "q:sx_mk_daesal", "t": "키를 잰 금이구먼. 애들 키 재 주던 금이야."}, {"s": null, "t": "노인은 그 말을 하고 한동안 말이 없었다. 손에 쥔 몽당붓을 내려다보며 엄지로 붓대를 쓸었다."}, {"s": "q:sx_mk_daesal", "t": "숙소 주인 조사원이 아이를 키웠다는 얘기는 들은 적이 없는데."}, {"s": "q:sx_mk_daesal", "t": "금 옆 글자가 뭐였는지 알면 좋겠어. 숙소 안쪽 마루에 젖은 서책 더미가 있었지? 거기 뭐가 적혀 있을지도 몰라. 한 번만 더 뒤져 봐 줘."}]'::jsonb, '{"xp": 2536}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_other_brush', 3, '글자 연습 종이', '먹비 숲에서 실마리를 찾는다', '{"at": ["meokbi_forest"], "tasks": [{"t": "clue", "r": ["meokbi_forest"], "n": 1}]}'::jsonb, '[{"s": null, "t": "젖은 서책 더미 맨 밑에서 접힌 종이 한 장이 나왔다. 종이에는 같은 글자가 줄마다 빽빽이 적혀 있었다. 처음 몇 줄은 삐뚤었고, 뒤로 갈수록 획이 반듯해졌다."}, {"s": null, "t": "종이 귀퉁이에 어른 글씨로 짧게 적힌 말이 있었다. 「오늘은 끝까지 썼다. 잘했다.」"}, {"s": null, "t": "비가림으로 돌아와 종이를 건네자, 대살은 그것을 받아 들고 눈을 가늘게 떴다. 종이를 쥔 손이 떨렸다."}, {"s": "q:sx_mk_daesal", "t": "이 글자…… 「살」이야. 우산살 할 때 그 살."}, {"s": null, "t": "노인은 종이를 무릎에 내려놓고 제 손바닥을 오래 들여다보았다. 굳은살이 박인 손이었다."}, {"s": "q:sx_mk_daesal", "t": "어릴 적에 이 숲에서 비 피하는 일을 했어. 먹비 오는 날 사람들한테 우산 씌워 주고 동전 한 닢씩 받았지. 그런데 그 시절이 통 생각이 안 나. 이 숲 비를 너무 오래 맞았나 봐."}, {"s": null, "t": "그때 숲 안쪽에서 날갯짓 소리가 났다. 검은 반딧불이 떼를 지어 비가림 쪽으로 몰려오고 있었다. 반딧불이 지나간 자리마다 먹비가 더 짙어졌다."}, {"s": "q:sx_mk_daesal", "t": "저놈들이 남의 꿈을 물고 다닌다더니, 이 종이 냄새를 맡았나 봐. 저것들 좀 흩어 줘. 종이가 젖기 전에."}]'::jsonb, '{"xp": 2536}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_other_brush', 4, '떨어진 꿈 한 조각', '먹비 반딧불 떼을(를) 물리친다', '{"at": ["meokbi_forest"], "tasks": [{"t": "win", "m": ["mk_forest_3"], "n": 4}]}'::jsonb, '[{"s": null, "t": "마지막 반딧불 떼가 흩어지자, 빛 한 점이 비가림 지붕 아래로 떨어져 노인의 손등에 앉았다. 대살은 그 빛을 손으로 감쌌다."}, {"s": null, "t": "노인은 눈을 감고 한참 앉아 있었다. 다시 눈을 떴을 때 눈가가 젖어 있었다."}, {"s": "q:sx_mk_daesal", "t": "생각났어. 비가 오던 날이었어. 숙소 처마 밑에서 비를 긋는데, 거기 살던 조사원이 나를 불러들였지. 이름이 뭐냐고 묻더라고."}, {"s": "q:sx_mk_daesal", "t": "이름을 쓸 줄 모른다니까, 그 사람이 이 붓을 쥐여 줬어. 날마다 한 줄씩 쓰라고. 내 이름을 내가 못 쓰면 남이 지울 때 막을 수가 없다고."}, {"s": null, "t": "대살은 몽당붓을 종이 옆에 나란히 놓았다. 털이 비뚤어진 붓은 그 종이의 삐뚤삐뚤한 첫 줄과 꼭 맞았다."}, {"s": "q:sx_mk_daesal", "t": "기둥에 그은 금은 내 키였어. 그 사람이 비 오는 날마다 재 줬지. 그러다 어느 해부터 숙소에 안 갔어. 왜 안 갔는지는 끝내 생각이 안 나."}, {"s": "q:sx_mk_daesal", "t": "그 사람한테 갚을 길은 없겠지. 대신 숙소 처마에 우산 하나 걸어 두고 싶어. 비 긋던 애가 이제 우산을 고친다고."}, {"s": "q:sx_mk_daesal", "t": "먹비 우산 하나만 지어 줘. 흑단 살은 내가 고르는 것보다 조사원 손으로 지은 게 낫겠어. 그 사람도 조사원이었으니까."}]'::jsonb, '{"xp": 2536}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_other_brush', 5, '처마에 건 우산', '먹비 우산을(를) 만든다, 먹비 우산을(를) 넘긴다', '{"at": ["meokbi_forest"], "tasks": [{"t": "craft", "items": ["meokbi_umbrella"], "n": 1}], "give": {"meokbi_umbrella": 1}}'::jsonb, '[{"s": null, "t": "지어 온 먹비 우산을 건네자 대살은 살을 하나하나 손끝으로 퉁겨 보았다. 소리가 고르게 울리자 노인은 고개를 끄덕였다."}, {"s": null, "t": "우리는 함께 옛 조사원 숙소로 갔다. 노인은 처마 기둥의 금 옆에 우산을 펼쳐 걸고, 몽당붓으로 기둥에 글자 한 자를 새로 적었다. 「살」."}, {"s": "q:sx_mk_daesal", "t": "비뚤어졌지? 그래도 끝까지 썼어."}, {"s": null, "t": "기둥에 새로 쓴 글자 위로 먹비가 떨어졌다. 빗방울은 우산에 막혀 글자에 닿지 못하고 옆으로 흘러내렸다."}, {"s": "q:sx_mk_daesal", "t": "다음에 이 숲 오면 비가림에 들러. 우산은 늘 공짜로 고쳐 줄게. 그 사람한테 진 빚이니까."}, {"s": null, "t": "숲을 나서며 돌아보니, 노인이 처마 밑에 서서 기둥의 금을 손바닥으로 재고 있었다. 이제 금은 노인의 허리에도 닿지 않았다."}]'::jsonb, '{"xp": 2536, "gil": 173, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
