values ('mks_scarecrow', 'side', '전투·빈칸 벌판', '허수아비가 입은 문패', '벌판 한가운데 허수아비가 뜯긴 문패 수백 장을 몸에 걸고 서 있다. 강둑 집 노인은 그 가운데 제 집 문패를 찾는다.', 'blank_field', 42, '{mkq_2}'::text[], null, 1320, '[]'::jsonb, true, null, null)
