delete from public.world_quest_steps where quest_id = 'mks_scarecrow' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_scarecrow', 1, '고랑 앞의 노인', '고랑 앞의 노인', '{"at": ["blank_field"]}'::jsonb, '[{"s": null, "t": "빈칸 벌판 들머리 둔덕에서 노인 하나가 지팡이를 짚고 서 있었다. 노인 앞의 고랑마다 먹물이 고여 있었고, 그 위에서 부풀어 오른 두꺼비들이 독한 숨을 뿜고 있었다."}, {"s": null, "t": "노인은 지팡이로 땅을 두 번 두드리고 나를 돌아보았다."}, {"s": "q:sx_mk_gangduk", "t": "나는 묵창 나루 강둑 집에 사는 늙은이요. 저 너머에 허수아비가 하나 서 있소. 그 허수아비가 우리 집 문패를 입고 있소."}, {"s": "q:sx_mk_gangduk", "t": "할멈이 쓴 문패요. 할멈 이름은 정청이 거둬 갔소. 그 뒤로는 할멈 이름이 생각나지 않소. 그래도 그 문패만은 다시 보고 싶소."}, {"s": "q:sx_mk_gangduk", "t": "그런데 이 늙은 다리로는 저 고랑을 못 건너오. 고랑의 먹물 두꺼비 다섯만 치워 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_scarecrow', 2, '문패를 입은 것', '먹물 두꺼비을(를) 물리친다', '{"at": ["blank_field"], "tasks": [{"t": "win", "m": ["mk_field_4"], "n": 5}]}'::jsonb, '[{"s": null, "t": "두꺼비가 사라진 고랑을 노인과 함께 건넜다. 벌판 한가운데에 사람 키의 세 배는 되는 허수아비가 서 있었다. 몸에 매단 문패가 바람에 부딪쳐 덜그럭거렸다."}, {"s": null, "t": "노인은 지팡이로 땅을 두 번 두드리고, 허수아비의 가슴께를 가리켰다."}, {"s": "q:sx_mk_gangduk", "t": "저기, 귀퉁이가 깨진 문패가 보이오? 저게 우리 집 것이오. 할멈이 문패를 걸다 떨어뜨려서 저렇게 깨졌지."}, {"s": "q:sx_mk_gangduk", "t": "저것은 한 번 쓰러뜨려도 문패를 주워 다시 일어선다고 하오. 두 번은 쓰러뜨려야 문패를 놓을 거요. 조심하시오."}]'::jsonb, '{"xp": 3382}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_scarecrow', 3, '흩어진 문패', '이름 걸린 허수아비을(를) 물리친다', '{"at": ["blank_field"], "tasks": [{"t": "win", "m": ["mk_field_5"], "n": 2}]}'::jsonb, '[{"s": null, "t": "허수아비가 두 번째로 쓰러지자 매달려 있던 문패들이 사방으로 흩어졌다. 억새 사이사이에 깨진 문패 조각이 박혔다."}, {"s": null, "t": "노인은 무릎을 꿇고 억새를 헤쳤다. 손이 떨려 조각을 자꾸 놓쳤다."}, {"s": "q:sx_mk_gangduk", "t": "산산조각이 났구려. 조각이라도 모으면 맞춰 볼 수 있을 거요. 귀퉁이가 깨진 조각을 중심으로, 지워진 문패 조각 셋만 더 찾아 주시오."}]'::jsonb, '{"xp": 3382}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_scarecrow', 4, '할멈의 글씨', '빈칸 벌판에서 지워진 문패 조각을(를) 모은다', '{"at": ["blank_field"], "tasks": [{"t": "gather", "items": ["erased_plate"], "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "내가 찾아온 조각들을 노인은 둔덕 위 평평한 돌에 하나씩 맞춰 놓았다. 귀퉁이가 깨진 문패가 다시 모양을 갖추었다."}, {"s": null, "t": "문패에는 이름이 둘 적혀 있었다. 하나는 먹이 거둬져 하얗게 비어 있었다. 다른 하나는 노인의 이름이었다."}, {"s": null, "t": "노인은 비어 있는 칸을 오래 쓰다듬었다. 그러다 제 이름이 적힌 칸으로 손을 옮겼다."}, {"s": "q:sx_mk_gangduk", "t": "할멈 이름은 끝내 못 읽겠소. 그런데 이 글씨는 알겠소. 내 이름을 이렇게 쓰는 사람은 할멈 하나뿐이었소. 획 끝을 꼭 한 번 꺾었거든."}, {"s": null, "t": "노인은 지팡이로 땅을 두 번 두드렸다. 이번에는 아무 말도 덧붙이지 않았다. 조각을 보자기에 싸서 품에 넣고, 강둑 쪽으로 천천히 걸어갔다."}, {"s": null, "t": "노인이 지나간 둔덕에, 억새 하나가 바람도 없는데 한 번 고개를 숙였다."}]'::jsonb, '{"xp": 3382, "gil": 173, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
