values ('mks_broken_brush', 'side', '전투·먹비 숲', '꺾인 붓의 주인', '백 년 전 붓장이 집안이 먹비 숲 고목을 꺾어 정청에 붓을 바쳤다. 그 붓으로 거둔 이름의 값을 고목이 받으러 왔다.', 'meokbi_forest', 43, '{mkq_2}'::text[], null, 1321, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_broken_brush' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_broken_brush', 1, '고목을 베러 온 사내', '고목을 베러 온 사내', '{"at": ["meokbi_forest"]}'::jsonb, '[{"s": null, "t": "먹비 숲 붓끝 같은 가지 숲에서 비단 도포를 입은 사내 하나가 일꾼 둘에게 도끼를 쥐여 주고 있었다. 일꾼들은 도끼를 든 채 서로 눈치만 보았다."}, {"s": null, "t": "사내는 나를 보자 반색하며 손짓했다. 도포 자락에 먹비가 얼룩덜룩 번져 있었다."}, {"s": "q:sx_mk_dampil", "t": "마침 잘 오셨어요. 조사원이시죠? 제 집안이 백 년째 정청에 붓을 대는 붓장이 집안이에요. 담필이라고 하면 서고 서리들은 다 알아요."}, {"s": "q:sx_mk_dampil", "t": "저기 꺾인 고목 보이시죠? 저 나무로 맨 붓이 정청 명부를 다 썼어요. 할아버지의 할아버지가 꺾어 오신 거래요. 남은 둥치를 베어 가면 붓 천 자루는 더 나와요."}, {"s": null, "t": "고목은 붓대처럼 곧게 자라다 중간에서 부러져 있었다. 부러진 자리에서 검은 먹이 끈적하게 흘러내렸다."}, {"s": "q:sx_mk_dampil", "t": "그런데 일꾼들이 겁을 먹었어요. 둥치 둘레에 먹비 넋이 우글거린다고요. 넋 같은 거야 조사원이 쫓아 주시면 되잖아요."}, {"s": null, "t": "나는 넋이 왜 그 고목 곁에 모이는지 물었다. 담필은 손사래를 쳤다."}, {"s": "q:sx_mk_dampil", "t": "그런 건 알 필요 없어요. 값은 넉넉히 쳐 드릴게요. 둥치 둘레의 먹비 넋 여덟만 쫓아 주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_broken_brush', 2, '넋이 부르던 말', '먹비 넋을(를) 물리친다', '{"at": ["meokbi_forest"], "tasks": [{"t": "win", "m": ["mk_forest_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "먹비 넋을 풀어 보낼 때마다 넋은 꼭 같은 말을 웅얼거렸다. 「붓을 돌려줘.」 여덟째 넋은 끝까지 그 말을 놓지 않았다."}, {"s": null, "t": "돌아와 그 말을 전하자, 담필의 얼굴에서 웃음기가 가셨다. 사내는 도포 소매로 이마의 먹비를 훔쳤다."}, {"s": "q:sx_mk_dampil", "t": "붓을 돌려 달라고요? 우리 집 붓으로 이름이 거둬진 사람들이 그런다는 거예요?"}, {"s": "q:sx_mk_dampil", "t": "그건 우리 탓이 아니잖아요. 우리는 붓만 맸어요. 이름을 거둔 건 정청이고요."}, {"s": null, "t": "그때 꺾인 고목이 삐걱거리며 몸을 틀었다. 담필의 발치 땅바닥에 먹 글씨가 저절로 떠올랐다. 담필의 이름 석 자였다. 부러진 자리에서 가지 하나가 붓처럼 뻗어 나와, 그 이름 위에 한 줄을 그어 반쯤 지웠다."}, {"s": "q:sx_mk_dampil", "t": "이, 이거 뭐예요? 제 이름이 왜 땅에 써 있어요? 왜 지워져요?"}, {"s": null, "t": "일꾼 둘이 도끼를 내던지고 숲 밖으로 달아났다. 담필은 주저앉은 채 내 소매를 붙들었다."}, {"s": "q:sx_mk_dampil", "t": "조사원, 저 고목 좀 어떻게 해 주세요. 두 번만 쓰러뜨리면 잠잠해질 거예요. 제발요. 할아버지가 그러셨어요. 저 나무는 두 번 꺾여야 죽는다고."}]'::jsonb, '{"xp": 3531}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_broken_brush', 3, '붓 값', '꺾인 붓 고목을(를) 물리친다', '{"at": ["meokbi_forest"], "tasks": [{"t": "win", "m": ["mk_forest_5"], "n": 2}]}'::jsonb, '[{"s": null, "t": "고목은 두 번째로 쓰러지고 나서야 움직임을 멈췄다. 부러진 자리에서 흐르던 먹이 멎었다. 그 대신 둥치 틈에서 낡은 붓 한 자루가 굴러떨어졌다."}, {"s": null, "t": "붓대에 붓장이 집안의 낙관이 찍혀 있었다. 백 년 전 정청에 바친 첫 붓이었다."}, {"s": null, "t": "담필은 그 붓을 주워 들고 한참을 말없이 서 있었다. 땅바닥의 제 이름은 반쯤 지워진 그대로였다."}, {"s": "q:sx_mk_dampil", "t": "할아버지가 늘 자랑하셨어요. 우리 붓으로 거둔 이름이 만 개가 넘는다고요. 저는 그게 자랑인 줄만 알았어요."}, {"s": "q:sx_mk_dampil", "t": "이름이 반쯤 지워지니까 알겠어요. 무서워요. 내가 누군지 손으로 붙잡고 있어야 할 것 같아요."}, {"s": null, "t": "나는 둥치를 베어 갈 거냐고 물었다. 담필은 고개를 세게 저었다."}, {"s": "q:sx_mk_dampil", "t": "안 베어요. 이 붓도 돌려줄 거예요. 넋들이 비 맞으며 기다렸잖아요. 비라도 가려 주고 싶어요."}, {"s": "q:sx_mk_dampil", "t": "먹비 우산 두 개만 지어 주세요. 하나는 이 고목 앞에 펼쳐 두고, 하나는 제가 쓰고 집에 갈래요. 집에 가서 할아버지 장부도 다 태울 거예요."}]'::jsonb, '{"xp": 3531}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_broken_brush', 4, '고목 앞에 펼친 우산', '먹비 우산을(를) 만든다, 먹비 우산을(를) 넘긴다', '{"at": ["meokbi_forest"], "tasks": [{"t": "craft", "items": ["meokbi_umbrella"], "n": 2}], "give": {"meokbi_umbrella": 2}}'::jsonb, '[{"s": null, "t": "지어 온 우산 하나를 담필이 고목 앞에 펼쳐 세웠다. 그 아래 땅을 손으로 파고, 낙관 찍힌 첫 붓을 묻었다."}, {"s": "q:sx_mk_dampil", "t": "백 년 늦었어요. 우리 집 붓으로 이름이 지워진 분들, 잘못했습니다."}, {"s": null, "t": "사내는 비단 도포가 진흙에 젖는 것도 모르고 땅에 이마를 댔다. 그가 일어서자 땅바닥에 반쯤 지워져 있던 그의 이름이 먹비에 씻겨 다시 또렷해졌다."}, {"s": null, "t": "담필은 남은 우산을 받아 쓰고, 도끼 두 자루를 어깨에 걸쳤다. 일꾼들이 버리고 간 것이었다."}, {"s": "q:sx_mk_dampil", "t": "앞으로 붓은 정청이 아니라 서당에 맬 거예요. 애들이 제 이름 쓰는 붓으로요. 그게 값이 덜 나가도요."}, {"s": null, "t": "숲을 나서는 사내의 우산 위로 먹비가 후드득 떨어졌다. 고목 앞의 우산 아래에는 비가 한 방울도 들지 않았다. 넋들이 그 아래 모여, 더는 아무것도 부르지 않았다."}]'::jsonb, '{"xp": 3531, "gil": 177, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
