values ('mks_n_tuna', 'side', '낚시·묵창 나루', '바람 부는 새벽의 그물', '허리 다친 어부 셋 대신 먹비늘 다랑어 내기에 나선다.', 'mukchang_ferry', 43, '{mkq_1}'::text[], null, 1322, '[]'::jsonb, true, null, null)
