delete from public.world_quest_steps where quest_id = 'mks_n_tuna' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_tuna', 1, '세 영감의 내기', '세 영감의 내기', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "묵창 나루 주막 앞 평상에 늙은 어부 셋이 나란히 엎드려 있었다. 셋 다 허리에 찜질 천을 감고 있었다."}, {"s": null, "t": "가운데 엎드린 영감이 나를 보더니 고개만 번쩍 들었다."}, {"s": "q:sx_mk_seonchang", "t": "어이, 거기 조사원! 이리 좀 와 봐. 우리가 사는 자리를 따서 부르면 나는 선창 영감, 이쪽은 둑길 영감, 저쪽은 갈밭 영감이야."}, {"s": null, "t": "왼쪽에 엎드린 영감이 허리를 짚으며 끙 소리를 냈다."}, {"s": "q:sx_mk_dukgil", "t": "우리 셋이 해마다 먹비늘 다랑어를 두고 내기를 하는데, 올해는 셋 다 이 꼴이야. 그물 당기다가 셋이 한꺼번에 허리를 삐었지."}, {"s": null, "t": "오른쪽 끝의 가장 젊어 보이는 영감이 조용히 고개를 들었다."}, {"s": "q:sx_mk_galbat", "t": "내기를 거르면 나루 사람들이 셋 다 늙었다고 놀리오. 그래서 대신 낚아 줄 사람을 찾고 있었소."}, {"s": null, "t": "셋이 동시에 나를 보았다. 나는 누구 몫으로 낚아야 하느냐고 물었다. 셋이 동시에 자기 몫이라고 했다. 선창 영감이 둘을 손으로 막으며 목소리를 높였다."}, {"s": "q:sx_mk_seonchang", "t": "그건 낚은 다음에 정하자고. 우선 미끼부터 있어야 해. 다랑어는 전어나 고등어, 광어, 갯장어 같은 바닷물고기 냄새를 따라 들어와."}, {"s": "q:sx_mk_seonchang", "t": "선창 너머 묵창 앞바다에서 세 번만 낚아 와. 우리 셋 중에 누가 가르쳐 줬다고 하면 안 돼. 내가 가르쳐 준 거야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_tuna', 2, '미끼 자랑', '묵창 나루에서 낚시를 한다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "n": 3}]}'::jsonb, '[{"s": null, "t": "앞바다에서 낚은 바닷물고기를 평상 위에 늘어놓자, 세 영감이 엎드린 채 고개만 내밀어 한 마리씩 품평했다. 둑길 영감이 먼저 전어를 손가락으로 집어 들었다."}, {"s": "q:sx_mk_dukgil", "t": "전어는 기름이 올라야 냄새가 좋은데, 이건 아직 덜 올랐네."}, {"s": null, "t": "선창 영감이 그 전어를 빼앗아 코에 대 보았다."}, {"s": "q:sx_mk_seonchang", "t": "무슨 소리야. 딱 좋구먼."}, {"s": null, "t": "갈밭 영감은 두 사람을 보지도 않고 내게 말했다."}, {"s": "q:sx_mk_galbat", "t": "미끼는 가방에 넣어 두었다가, 낚시할 때 낚시 칸에서 골라 거시오. 그건 내가 가르쳐 드린 거요."}, {"s": null, "t": "선창 영감이 갈밭 영감을 노려보았다. 그러고는 허리를 짚으며 끙 하고 돌아누웠다. 돌아누운 채로도 입은 쉬지 않았다."}, {"s": "q:sx_mk_seonchang", "t": "그런데 우리 셋이 엎드려 있는 동안 밥은 누가 해? 다랑어가 들 때까지 며칠이 걸릴지 모르는데."}, {"s": null, "t": "둑길 영감이 배를 문지르며 거들었다."}, {"s": "q:sx_mk_dukgil", "t": "노정 건량이나 세 개 지어 줘. 하나씩 품에 넣어 두게. 배고프면 바다도 안 보여."}]'::jsonb, '{"xp": 2648}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_tuna', 3, '바람을 기다리는 동안', '노정 건량을(를) 만든다, 노정 건량을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["travel_ration"], "n": 3}], "give": {"travel_ration": 3}}'::jsonb, '[{"s": null, "t": "노정 건량을 하나씩 나누어 주자, 세 영감은 엎드린 채로 건량을 씹었다. 바람이 바다 쪽에서 한 번 불어왔다가 잦아들었다. 갈밭 영감이 건량을 내려놓고 바다 쪽을 보았다."}, {"s": "q:sx_mk_galbat", "t": "다랑어는 해돋이에 앞바다로 드오. 삭풍이 세게 부는 새벽이어야 하오. 바람이 물을 뒤집어야 깊은 데서 올라오오."}, {"s": null, "t": "선창 영감이 코웃음을 치며 손을 내저었다."}, {"s": "q:sx_mk_seonchang", "t": "오늘 바람으로는 어림도 없어. 바람 들 때까지 놀고 있지 말고, 빈칸 벌판에나 한 바퀴 다녀와. 거기 바람 부는 걸 보면 나루에 언제 삭풍이 들지 알 수 있어."}, {"s": null, "t": "둑길 영감이 고개를 번쩍 들었다."}, {"s": "q:sx_mk_dukgil", "t": "그건 내가 하려던 말이야."}, {"s": null, "t": "셋은 또 다투기 시작했다. 나는 그 소리를 뒤로하고 채비를 꾸렸다."}]'::jsonb, '{"xp": 2648}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_tuna', 4, '바람이 들었다', '빈칸 벌판에 원정을 다녀온다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "expedition", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정에서 돌아오는 길에 벌판의 억새가 모두 한쪽으로 누워 있었다. 나루에 닿자 바다 쪽에서 찬바람이 몰려왔다."}, {"s": null, "t": "평상의 세 영감이 동시에 고개를 들었다. 바람 냄새를 맡는 얼굴이 셋 다 똑같았다. 선창 영감이 가장 먼저 소리쳤다."}, {"s": "q:sx_mk_seonchang", "t": "왔다, 왔어. 내일 새벽이야."}, {"s": null, "t": "둑길 영감이 손가락을 꼽으며 날을 셌다."}, {"s": "q:sx_mk_dukgil", "t": "삭풍 부는 해돋이에, 묵창 앞바다야. 미끼는 아까 그 바닷물고기를 걸고."}, {"s": null, "t": "갈밭 영감은 낮은 목소리로 한마디만 보탰다."}, {"s": "q:sx_mk_galbat", "t": "다랑어가 물면 줄을 당기지 말고 버티시오. 저 녀석이 먼저 지칠 때까지."}]'::jsonb, '{"xp": 2648}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_tuna', 5, '누구 몫인가', '묵창 나루에서 먹비늘 다랑어을(를) 낚는다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "f": ["inkscale_tuna"], "n": 1}]}'::jsonb, '[{"s": null, "t": "새벽 바람 속에서 끌어올린 다랑어는 비늘이 먹물처럼 번들거렸다. 선창으로 끌고 오자 세 영감이 허리를 짚고 일어나 달려왔다. 허리를 삔 사람들 같지 않았다. 선창 영감이 다랑어 꼬리를 먼저 붙잡았다."}, {"s": "q:sx_mk_seonchang", "t": "내 몫이지! 미끼를 내가 가르쳐 줬잖아."}, {"s": null, "t": "둑길 영감이 다랑어 머리 쪽을 붙잡았다."}, {"s": "q:sx_mk_dukgil", "t": "건량을 시킨 건 나야."}, {"s": null, "t": "갈밭 영감은 다랑어 배를 손바닥으로 짚었다."}, {"s": "q:sx_mk_galbat", "t": "버티라고 한 건 나요."}, {"s": null, "t": "셋이 다랑어를 둘러싸고 한참 다투었다. 그러다 선창 영감이 먼저 웃음을 터뜨렸다. 나머지 둘도 따라 웃었다."}, {"s": "q:sx_mk_seonchang", "t": "됐다, 됐어. 올해는 셋 다 진 걸로 하자. 다랑어는 낚은 사람 몫이야. 우리는 그 옆에서 고등어나 구워 먹자고."}, {"s": null, "t": "둑길 영감이 허리를 펴며 나를 가리켰다."}, {"s": "q:sx_mk_dukgil", "t": "내년엔 허리 펴고 우리가 낚는다. 그때는 구경만 해."}, {"s": null, "t": "그날 저녁 주막 앞 평상에서 나루 사람들이 고등어를 구워 나눠 먹었다. 세 영감은 가장 좋은 자리에 나란히 앉아, 서로 자기가 제일 많이 도왔다고 우겼다."}]'::jsonb, '{"xp": 2648, "gil": 177, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
