values ('mks_totem', 'side', '전투·먹비 숲', '목장승이 지키던 마을', '새긴 이름이 지워져 누구를 지키는지 모르게 된 목장승들. 장승을 깎은 늙은 장승장이가 장승이 지키던 마을 이름을 찾는다.', 'meokbi_forest', 43, '{mkq_2}'::text[], null, 1323, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_totem' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_totem', 1, '걸어 다니는 장승', '걸어 다니는 장승', '{"at": ["meokbi_forest"]}'::jsonb, '[{"s": null, "t": "먹비 숲 흑단 고목 숲길에 장승 하나가 서 있었다. 그런데 내가 한 걸음 다가가자, 장승이 뿌리째 땅을 뽑고 한 걸음 물러섰다."}, {"s": null, "t": "등 뒤에서 혀를 차는 소리가 났다. 지팡이 대신 끌 자루를 짚은 노인 하나가 젖은 바위에 걸터앉아 그 장승을 노려보고 있었다."}, {"s": "q:sx_mk_segeol", "t": "쳐다보지 마. 저놈이 눈이 마주치면 따라와."}, {"s": "q:sx_mk_segeol", "t": "내가 깎은 놈이야. 쉰 해 전에. 이 숲 안쪽 마을 어귀에 세웠지. 이름도 내가 새겼어. 마을 이름하고 장승 이름하고."}, {"s": null, "t": "노인은 끌로 허공을 한 번 깎는 시늉을 했다. 장승의 가슴께는 먹비에 씻겨 글자 한 획 남지 않았다."}, {"s": "q:sx_mk_segeol", "t": "먹비를 백 년 맞으면 돌처럼 굳는다더니, 쉰 해 만에 저 꼴이야. 이름이 지워지니까 누굴 지키는지 몰라서 아무나 막아서."}, {"s": "q:sx_mk_segeol", "t": "그 마을 이름이 나도 생각이 안 나. 내 손으로 새긴 걸."}, {"s": "q:sx_mk_segeol", "t": "저렇게 걸어 다니는 놈들을 먼저 쓰러뜨려 줘. 먹 먹은 목장승 다섯이면 마을 어귀 길이 열릴 거야. 장승은 내가 다시 깎으면 돼."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_totem', 2, '장승 밑동의 끌 자국', '먹 먹은 목장승을(를) 물리친다', '{"at": ["meokbi_forest"], "tasks": [{"t": "win", "m": ["mk_forest_4"], "n": 5}]}'::jsonb, '[{"s": null, "t": "쓰러진 장승들은 다시 나무토막이 되어 숲길에 누웠다. 세걸이 끌 자루를 짚고 와서 장승 밑동을 하나씩 뒤집어 보았다."}, {"s": null, "t": "밑동마다 같은 끌 자국이 있었다. 노인의 손버릇대로 비스듬히 세 번 그은 자국이었다."}, {"s": "q:sx_mk_segeol", "t": "다 내 것이구먼. 하나도 빠짐없이."}, {"s": null, "t": "노인은 그중 한 밑동을 쓰다듬다가 손을 멈췄다. 비스듬한 자국 옆에, 다른 손으로 새긴 작은 글자가 있었다. 아이 손톱으로 긁은 것처럼 얕았다."}, {"s": "q:sx_mk_segeol", "t": "이건 내가 안 새겼어. 마을 애들이 장난친 거겠지."}, {"s": "q:sx_mk_segeol", "t": "애들이 장승한테 제 이름을 새겨 두면 장승이 지켜 준다고들 믿었어. 그래서 장승 밑동은 늘 낙서투성이였지."}, {"s": null, "t": "노인은 그 얕은 글자를 오래 내려다보다가, 숲 안쪽을 끌로 가리켰다. 길이 덩굴로 꽉 막혀 있었다."}, {"s": "q:sx_mk_segeol", "t": "마을 터는 저 너머야. 그런데 흑단 덩굴귀가 길을 다 휘감았어. 가시에 먹물 독이 배어서 맨손으로는 못 걷어. 여덟 놈쯤 걷어 내면 지나갈 수 있을 거야."}]'::jsonb, '{"xp": 3531}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_totem', 3, '지붕 없는 집터', '흑단 덩굴귀을(를) 물리친다', '{"at": ["meokbi_forest"], "tasks": [{"t": "win", "m": ["mk_forest_2"], "n": 8}]}'::jsonb, '[{"s": null, "t": "덩굴을 걷어 낸 길 끝에 마을 터가 있었다. 집은 한 채도 남아 있지 않았다. 주춧돌 몇 개와 무너진 우물만 먹비 속에 드러나 있었다."}, {"s": null, "t": "세걸은 주춧돌 하나하나에 끌 자루를 대 보며 천천히 걸었다. 그러다 우물가에서 걸음을 멈췄다."}, {"s": "q:sx_mk_segeol", "t": "여기서 애들이 물을 길었어. 장승을 다 세운 날 마을 사람들이 이 우물가에서 잔치를 했지. 나도 막걸리 한 사발 얻어먹었고."}, {"s": "q:sx_mk_segeol", "t": "그런데 그날 마을 이름을 뭐라고 불렀는지, 그게 안 떠올라. 다들 나를 「장승 아재」라고만 불렀거든."}, {"s": null, "t": "노인은 우물 돌을 손바닥으로 문질렀다. 먹비에 씻긴 돌에는 이끼만 끼어 있었다."}, {"s": "q:sx_mk_segeol", "t": "마을 사람들은 다 어디로 갔는지 몰라. 이름이 지워지면 사람도 흩어진다더니."}, {"s": "q:sx_mk_segeol", "t": "집터 둘레를 두어 번 더 살펴봐 줘. 우물 둘레돌이든 주춧돌이든, 이름 한 자라도 남은 게 있을 거야."}]'::jsonb, '{"xp": 3531}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_totem', 4, '우물 둘레돌 안쪽', '먹비 숲을(를) 살핀다', '{"at": ["meokbi_forest"], "tasks": [{"t": "search", "r": ["meokbi_forest"], "n": 2}]}'::jsonb, '[{"s": null, "t": "우물 안쪽 둘레돌, 먹비가 들이치지 않는 그늘진 면에 글자가 남아 있었다. 마을 이름 석 자였다. 그 아래로 아이들 이름이 손톱자국처럼 줄줄이 새겨져 있었다."}, {"s": null, "t": "나는 세걸을 불렀다. 노인은 우물가에 무릎을 꿇고 앉아, 둘레돌 안쪽을 손가락으로 한 자씩 더듬었다."}, {"s": "q:sx_mk_segeol", "t": "솔밭골."}, {"s": null, "t": "노인이 그 이름을 소리 내어 불렀다. 쉰 해 만에 불린 이름이었다. 숲길에 쓰러져 있던 장승 토막 하나가 바스락거리며 몸을 뒤척였다."}, {"s": "q:sx_mk_segeol", "t": "솔밭골이었어. 소나무 하나 없는 동네가 무슨 솔밭골이냐고 내가 놀렸지. 그랬더니 촌장이 그러더군. 이름을 그렇게 지어 놓으면 언젠가 소나무가 자란다고."}, {"s": null, "t": "노인은 끌을 꺼내 쓰러진 장승 하나를 바로 세웠다. 그리고 장승 가슴께에 「솔밭골」 석 자를 새로 새겼다. 끌 자국은 여전히 비스듬히 세 번이었다."}, {"s": "q:sx_mk_segeol", "t": "지킬 마을은 없어. 그래도 이름은 지켜야지. 이름까지 없어지면 여기 살던 애들은 어디로 돌아와."}, {"s": null, "t": "새로 새긴 장승은 걸어 다니지 않았다. 마을 터를 바라보고 똑바로 서 있었다. 그 발치, 무너진 주춧돌 틈에서 손가락만 한 소나무 싹 하나가 먹비를 맞고 있었다."}]'::jsonb, '{"xp": 3531, "gil": 177, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
