values ('mks_last_line', 'side', '조사·명부 탑', '서리귀의 마지막 줄', '평생 명부의 이름을 지운 서리의 넋이 지금도 탑을 오르내린다. 그가 지우지 않고 남겨 둔 단 한 줄을 그의 손녀가 찾으러 왔다.', 'myeongbu_tower', 44, '{mkq_3}'::text[], null, 1324, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_last_line' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_last_line', 1, '할아버지를 찾는 필사꾼', '할아버지를 찾는 필사꾼', '{"at": ["myeongbu_tower"]}'::jsonb, '[{"s": null, "t": "명부 탑 첫째 층 서고에서 젊은 여인 하나가 무너진 죽간을 한 장씩 주워 등불에 비추고 있었다. 귀에 붓 한 자루를 꽂고 있었다."}, {"s": null, "t": "여인은 나를 보고 죽간을 가지런히 내려놓았다. 손끝에 먹물이 배어 있었다."}, {"s": "q:sx_mk_yeonbi", "t": "조사원님이시군요. 놀라게 해 드렸다면 미안해요. 저는 서책을 베껴 쓰고 품삯을 받는 필사꾼이에요. 연비라고 해요."}, {"s": "q:sx_mk_yeonbi", "t": "할아버지가 이 탑에서 일하던 정청 서리였어요. 명부에서 이름을 지우는 일을 평생 하셨대요. 돌아가신 뒤에도 이 탑을 오르내린다는 소문이 있어서 와 봤어요."}, {"s": null, "t": "나는 탑 위층에서 붓을 들고 오르내리는 서리귀 이야기를 했다. 연비는 고개를 끄덕였다."}, {"s": "q:sx_mk_yeonbi", "t": "알아요. 이름 지우는 서리귀라고들 하죠. 할아버지일지도 몰라요."}, {"s": "q:sx_mk_yeonbi", "t": "그런데 그 서리귀한테 가려면 갈피마다 금줄을 두른 명부 갈피귀를 지나야 해요. 저 혼자서는 서가 하나도 못 넘어가요. 명부 갈피귀 여덟만 걷어 주시겠어요?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_last_line', 2, '붓을 든 서리귀', '명부 갈피귀을(를) 물리친다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "win", "m": ["mk_tower_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "금줄을 두른 갈피귀들이 흩어지자 위층으로 가는 서가 길이 열렸다. 연비가 등불을 들고 내 뒤를 따라왔다."}, {"s": null, "t": "셋째 층 서안 앞에 희미한 사람 형체가 앉아 있었다. 관복 차림의 넋이 붓을 쥐고, 펼친 명부에 줄을 긋고 있었다. 한 줄, 또 한 줄. 줄이 그어진 이름은 종이에서 사라졌다."}, {"s": null, "t": "연비가 숨을 들이켰다. 등불을 든 손이 떨렸다."}, {"s": "q:sx_mk_yeonbi", "t": "할아버지예요. 붓을 저렇게 쥐셨어요. 새끼손가락을 붓대에 걸고."}, {"s": null, "t": "넋은 연비를 돌아보지 않았다. 다만 서가 사이 곳곳에서 같은 형체가 하나씩 더 일어섰다. 모두 붓을 들고 있었다."}, {"s": "q:sx_mk_yeonbi", "t": "서리귀가 하나가 아니었네요. 이 탑에서 이름을 지우던 서리들이 다 저렇게 남은 거예요."}, {"s": "q:sx_mk_yeonbi", "t": "할아버지만 남기고, 다른 서리귀들을 풀어 보내 주세요. 다섯쯤이면 할아버지 곁으로 갈 수 있을 거예요. 할아버지 넋은 제가 마주하고 싶어요."}]'::jsonb, '{"xp": 3684}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_last_line', 3, '지우지 않은 한 줄', '이름 지우는 서리귀을(를) 물리친다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "win", "m": ["mk_tower_4"], "n": 5}]}'::jsonb, '[{"s": null, "t": "다른 서리귀들이 흩어지자 서안 앞에는 연비의 할아버지 넋만 남았다. 넋은 여전히 줄을 긋고 있었다. 그런데 펼친 명부 맨 아래 한 줄 앞에서만 붓이 멈칫멈칫 비켜 갔다."}, {"s": null, "t": "연비가 서안 앞에 무릎을 꿇었다. 넋의 붓이 그 한 줄 위에서 떨렸다."}, {"s": "q:sx_mk_yeonbi", "t": "할아버지. 저 연비예요. 우리 엄마 딸이요."}, {"s": null, "t": "넋은 대답하지 않았다. 다만 붓을 내려놓고, 맨 아래 한 줄을 손바닥으로 덮었다. 지우는 손이 아니라 가리는 손이었다."}, {"s": "q:sx_mk_yeonbi", "t": "엄마가 그러셨어요. 어릴 때 이름이 거둬질 뻔했는데, 할아버지가 명부에서 그 줄만 끝내 안 지우셨대요. 그 일로 정청에서 쫓겨나셨고요."}, {"s": "q:sx_mk_yeonbi", "t": "그 줄이 여기 있을 거예요. 탑 안쪽 서가를 두어 번 더 살펴봐 주세요. 그리고 할아버지가 무엇을 남기셨는지, 실마리를 찾아 주세요."}]'::jsonb, '{"xp": 3684}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_last_line', 4, '손녀가 베낀 이름', '명부 탑을(를) 살핀다, 명부 탑에서 실마리를 찾는다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "search", "r": ["myeongbu_tower"], "n": 2}, {"t": "clue", "r": ["myeongbu_tower"], "n": 1}]}'::jsonb, '[{"s": null, "t": "탑 안쪽 회수 명부 보관함 밑바닥에서 작은 쪽지 하나가 나왔다. 관복 소매에서 떨어진 것처럼 접혀 있었다. 「이 줄은 내가 지우지 않는다. 지워야 한다면 내 이름을 대신 지워라.」"}, {"s": null, "t": "쪽지를 서안 위에 놓자, 넋이 손바닥을 천천히 거두었다. 맨 아래 한 줄에 여자아이 이름 하나가 또렷이 남아 있었다. 연비 어머니의 이름이었다."}, {"s": null, "t": "연비는 귀에 꽂은 붓을 뽑아 들었다. 제 필사첩을 펼치고, 그 이름을 한 획씩 베껴 썼다. 마지막 획까지 눌러 쓴 뒤에야 붓을 내려놓았다."}, {"s": "q:sx_mk_yeonbi", "t": "이제 이 이름은 할아버지 혼자 지키지 않아도 돼요. 제가 베껴 뒀으니까요."}, {"s": null, "t": "넋이 처음으로 연비를 돌아보았다. 넋은 새끼손가락을 붓대에 건 채로, 펼친 명부를 덮었다. 그러고는 등불 빛 속으로 옅어졌다."}, {"s": "q:sx_mk_yeonbi", "t": "할아버지 이름은 정청 명부에서 지워졌대요. 그래서 제가 따로 적어 두려고요."}, {"s": null, "t": "연비는 필사첩 다음 장에 이름 하나를 더 적었다. 그 이름 아래에 작은 글씨로 덧붙였다. 「끝까지 한 줄을 지킨 사람.」"}]'::jsonb, '{"xp": 3684, "gil": 181, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
