values ('mks_lightning', 'side', '전투·명부 탑', '탑 꼭대기 번갯불', '번갯불이 탑 꼭대기 창틀에 앉아 내려오지 않는다. 늙은 필사꾼은 그것을 등불 삼아 밤일을 한다며 쫓지 말라고 한다.', 'myeongbu_tower', 44, '{mkq_3}'::text[], null, 1325, '[]'::jsonb, true, null, null)
