delete from public.world_quest_steps where quest_id = 'mks_lightning' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lightning', 1, '수염이 그을린 필사꾼', '수염이 그을린 필사꾼', '{"at": ["myeongbu_tower"]}'::jsonb, '[{"s": null, "t": "명부 탑 꼭대기 누각에서 늙은 노인 하나가 죽간을 베끼고 있었다. 창틀 위에 번갯불 하나가 앉아 탁탁 튀었고, 노인은 그 불빛에 기대 붓을 놀렸다."}, {"s": null, "t": "번갯불이 한 번 크게 튀자 노인의 수염 끝이 그을렸다. 노인은 붓을 내던지고 수염을 쥐어뜯었다."}, {"s": "q:sx_mk_baengmuk", "t": "또! 또 그랬어! 이놈들이 하나일 때는 얌전하더니, 새끼를 쳤어!"}, {"s": null, "t": "누각 창틀마다 번갯불이 하나씩 앉아 있었다. 셀 수도 없을 만큼 많았다."}, {"s": "q:sx_mk_baengmuk", "t": "난 백묵이야. 이 탑에서 밤마다 죽간을 베끼지. 등잔 기름값이 아까워서 저놈 하나를 길들여 등불로 썼어. 처음엔 기가 막혔지."}, {"s": "q:sx_mk_baengmuk", "t": "그런데 한 놈이 여덟 놈이 되니까 수염이 남아나질 않아. 등불은 하나면 돼. 나머지는 좀 내보내 줘. 탑 꼭대기 번갯불 여덟만."}, {"s": null, "t": "나는 하나만 남기면 되느냐고 물었다. 노인은 그을린 수염을 쓰다듬으며 망설였다."}, {"s": "q:sx_mk_baengmuk", "t": "하나는…… 남겨도 되고. 아니, 다 내보내. 아니, 하나는 남겨. 일단 여덟부터!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lightning', 2, '꺼진 누각', '탑 꼭대기 번갯불을(를) 물리친다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "win", "m": ["mk_tower_2"], "n": 8}]}'::jsonb, '[{"s": null, "t": "마지막 번갯불까지 창밖으로 흩어지자 누각이 캄캄해졌다. 어둠 속에서 노인이 수염을 쥐어뜯는 소리만 들렸다."}, {"s": "q:sx_mk_baengmuk", "t": "다 내보냈어? 하나도 안 남기고?"}, {"s": null, "t": "나는 일단 여덟부터라고 하지 않았느냐고 했다. 노인은 끙 소리를 냈다."}, {"s": "q:sx_mk_baengmuk", "t": "그건 그렇지. 내가 그랬지. 그래도 등불 하나는 남겨 줄 줄 알았지."}, {"s": null, "t": "노인은 더듬더듬 서안을 찾아 앉았다. 베끼다 만 죽간이 서안 위에 수북했다."}, {"s": "q:sx_mk_baengmuk", "t": "오늘 밤 안에 이걸 다 베껴야 품삯이 나와. 등잔 기름은 비싸고, 번갯불은 수염을 태우고. 늙은이가 어찌 살라고."}, {"s": "q:sx_mk_baengmuk", "t": "아, 맞다. 혜성 낙하지에 성진사라는 별모래가 있다지. 그걸 등잔 기름에 섞으면 불이 반나절은 꺼지지 않는대. 기름값이 반으로 준다는 거야. 두 줌만 구해 와 줘."}]'::jsonb, '{"xp": 3684}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lightning', 3, '별모래 한 줌', '혜성 낙하지에서 성진사을(를) 모은다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "gather", "items": ["star_sand"], "r": ["comet_crater"], "n": 2}]}'::jsonb, '[{"s": null, "t": "혜성 낙하지에서 거둔 성진사를 내밀자 노인은 어둠 속에서 그것을 손바닥에 쏟아 보았다. 별모래가 희미하게 반짝이며 노인의 주름진 손금을 비췄다."}, {"s": "q:sx_mk_baengmuk", "t": "이거야, 이거. 이 빛이면 수염 걱정 없이 쓰겠어."}, {"s": null, "t": "노인은 별모래를 한참 들여다보다가, 무언가 생각난 듯 손뼉을 쳤다. 별모래가 바닥에 조금 흩어졌다."}, {"s": "q:sx_mk_baengmuk", "t": "그런데 나한테 등잔이 없어. 번갯불을 쓰면서 등잔은 고물상에 팔아 버렸거든."}, {"s": null, "t": "나는 노인을 한동안 말없이 바라보았다. 노인은 헛기침을 하고 수염을 쓸었다."}, {"s": "q:sx_mk_baengmuk", "t": "그렇게 보지 마. 늙으면 다 그래. 어유 등잔 두 개만 지어 줘. 하나는 서안에 두고, 하나는 계단에 둘 거야. 내려가다 굴러떨어지면 품삯이고 뭐고 없으니까."}]'::jsonb, '{"xp": 3684}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_lightning', 4, '등잔 위의 손님', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 2}], "give": {"fish_oil_lamp": 2}}'::jsonb, '[{"s": null, "t": "지어 온 어유 등잔에 성진사를 섞은 기름을 붓고 불을 붙였다. 누각에 은은한 빛이 퍼졌다. 노인은 만족스럽게 고개를 끄덕이고 붓을 들었다."}, {"s": "q:sx_mk_baengmuk", "t": "좋아. 아주 좋아. 이제 번갯불 따위는……"}, {"s": null, "t": "그때 창밖에서 탁 소리가 났다. 아까 흩어진 번갯불 하나가 돌아와, 등잔 꼭대기에 살그머니 내려앉았다. 번갯불은 등잔 불꽃 옆에서 작게 웅크렸다."}, {"s": null, "t": "노인은 붓을 든 채 굳었다. 수염 끝이 파르르 떨렸다."}, {"s": "q:sx_mk_baengmuk", "t": "저리 가. 저리 가라니까. 너 때문에 기름을 샀는데."}, {"s": null, "t": "번갯불은 가지 않았다. 등잔 불꽃에 몸을 기대고 꾸벅꾸벅 조는 것처럼 깜빡였다. 이번에는 튀지도 않았다."}, {"s": "q:sx_mk_baengmuk", "t": "……딱 하나만이야. 하나만 봐주는 거야. 수염 태우면 그날로 끝이야."}, {"s": null, "t": "노인은 툴툴거리며 다시 붓을 놀렸다. 누각을 나서며 돌아보니, 노인이 등잔 위의 번갯불에게 붓대를 대어 주고 있었다. 번갯불은 붓대 끝에 올라앉아, 노인이 베끼는 글자를 내려다보았다."}]'::jsonb, '{"xp": 3684, "gil": 181, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
