insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_mirror_face', 1, '내 얼굴이 적힌 쪽', '내 얼굴이 적힌 쪽', '{"at": ["myeongbu_tower"]}'::jsonb, '[{"s": null, "t": "명부 탑 창 없는 열람실에 거울처럼 번들거리는 명부가 펼쳐져 있었다. 무심코 들여다본 순간, 종이 위에 내 얼굴이 떠올랐다. 내가 눈을 깜빡이자 종이 속 얼굴은 한 박자 늦게 눈을 깜빡였다."}, {"s": null, "t": "등 뒤에서 쇠망치가 바닥을 치는 소리가 났다. 잿빛 도포를 입은 사내가 열람실 문간에 서 있었다."}, {"s": "q:sx_mk_gyeongdo", "t": "들여다보셨군요. 너무 늦었습니다. 방금 그 쪽에 조사원님 얼굴이 적혔습니다."}, {"s": "q:sx_mk_gyeongdo", "t": "저는 경도라 합니다. 이 탑에서 거울 명부를 깨고 다니는 사람입니다. 저것들은 이름 대신 얼굴을 적습니다. 얼굴이 적힌 사람은 명부 안에 하나가 더 생기지요."}, {"s": null, "t": "나는 명부 안의 나는 무엇을 하느냐고 물었다. 경도는 대답하기 전에 쇠망치를 고쳐 쥐었다."}, {"s": "q:sx_mk_gyeongdo", "t": "처음에는 흉내만 냅니다. 그다음에는 먼저 움직입니다. 마지막에는 바깥사람이 명부 안의 사람을 흉내 내게 되지요."}, {"s": "q:sx_mk_gyeongdo", "t": "조사원님 얼굴이 어느 명부에 적혔는지 모릅니다. 이 층의 거울 명부를 다섯 권쯤 깨 주십시오. 그중에 있기를 빌어야지요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_mirror_face', 2, '깨진 거울 조각', '거울 명부을(를) 물리친다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "win", "m": ["mk_tower_3"], "n": 5}]}'::jsonb, '[{"s": null, "t": "다섯째 거울 명부가 깨지자 바닥에 거울 조각이 흩어졌다. 조각마다 내 얼굴이 하나씩 비쳤다. 그런데 조각 하나 속의 얼굴만은 나를 보고 있지 않았다. 열람실 문 쪽을 보고 있었다."}, {"s": null, "t": "경도가 그 조각을 쇠망치 끝으로 뒤집었다. 조각 뒷면은 비어 있었다."}, {"s": "q:sx_mk_gyeongdo", "t": "놓쳤습니다. 명부 안의 조사원님이 이미 밖으로 나갔습니다."}, {"s": "q:sx_mk_gyeongdo", "t": "저것은 조사원님이 자는 곳으로 찾아옵니다. 잠든 얼굴을 보고 배우려고요."}, {"s": null, "t": "경도는 망치를 어깨에 걸치고 탑 아래쪽을 가리켰다. 창 없는 열람실에서도 먹비 소리가 들렸다."}, {"s": "q:sx_mk_gyeongdo", "t": "오늘 밤은 묵창 나루 주막에서 주무십시오. 사람이 많은 곳이 낫습니다. 저것이 정말 찾아오는지 봐야 다음 수를 쓸 수 있습니다."}]'::jsonb, '{"xp": 2763}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_mirror_face', 3, '창밖에 선 얼굴', '묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "주막 객방에서 눈을 붙였다가 새벽에 깼다. 문창호지 너머에 사람 그림자 하나가 서 있었다. 키도, 어깨도, 머리를 기울이는 버릇도 나와 똑같았다."}, {"s": null, "t": "내가 숨을 죽이자 그림자도 숨을 죽였다. 내가 손을 들자 그림자는 손을 들지 않았다. 그림자는 그대로 서서, 나를 지켜보고만 있었다."}, {"s": null, "t": "동이 트자 그림자는 사라졌다. 객방 문을 여니 경도가 툇마루에 앉아 쇠망치를 무릎에 얹고 있었다. 밤새 거기 앉아 있었던 모양이었다."}, {"s": "q:sx_mk_gyeongdo", "t": "보셨지요. 이제는 흉내를 내지 않고 기다립니다. 조사원님이 먼저 움직이기를요."}, {"s": "q:sx_mk_gyeongdo", "t": "저것은 조사원님이 자기 얼굴을 떠올릴 때마다 또렷해집니다. 그러니 한동안 얼굴을 잊어야 합니다."}, {"s": null, "t": "나는 제 얼굴을 어떻게 잊느냐고 물었다. 경도는 처음으로 아주 조금 웃었다."}, {"s": "q:sx_mk_gyeongdo", "t": "일에 파묻히시면 됩니다. 거울 볼 틈도 없이요. 자율 활동을 하나 끝까지 마치고 오십시오. 그동안 저것은 배울 것이 없어 흐려질 겁니다."}]'::jsonb, '{"xp": 2763}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_mirror_face', 4, '흐려진 그림자', '자율 활동을 끝까지 마친다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "idle", "n": 1}]}'::jsonb, '[{"s": null, "t": "일을 마치고 주막으로 돌아오는 동안 한 번도 거울을 보지 않았다. 물웅덩이도 피해 걸었다."}, {"s": null, "t": "경도는 툇마루에 그대로 앉아 있었다. 그의 발치, 아침 햇살이 드는 자리에 그림자 하나가 눌어붙어 있었다. 사람 꼴이었지만 얼굴은 먹이 번진 것처럼 뭉개져 있었다."}, {"s": "q:sx_mk_gyeongdo", "t": "잘하셨습니다. 저것이 조사원님 얼굴을 반쯤 잊었습니다."}, {"s": "q:sx_mk_gyeongdo", "t": "이제 마무리를 해야 합니다. 거울 명부는 얼굴만 적고 이름을 적지 못합니다. 얼굴이 적힌 쪽에 이름을 덮어 쓰면 그 쪽은 더 이상 얼굴을 담지 못하지요."}, {"s": "q:sx_mk_gyeongdo", "t": "명부 탑에서 명부 죽간 세 장을 거둬 오십시오. 죽간에 조사원님 이름을 써서 그 쪽에 붙이겠습니다."}]'::jsonb, '{"xp": 2763}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_mirror_face', 5, '이름을 덮어 쓴 쪽', '명부 탑에서 명부 죽간을(를) 모은다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "gather", "items": ["register_slip"], "r": ["myeongbu_tower"], "n": 3}]}'::jsonb, '[{"s": null, "t": "거둬 온 명부 죽간 세 장에 내 이름을 적었다. 경도는 탑 열람실로 돌아가, 처음 내 얼굴이 떠올랐던 쪽을 다시 펼쳤다. 얼굴은 없었다. 사람 꼴만 하얗게 비어 있었다."}, {"s": null, "t": "경도가 죽간 세 장을 그 빈 꼴 위에 붙였다. 종이가 한 번 몸서리치듯 떨리더니, 거울 같던 윤기가 빠지고 누런 종이로 돌아왔다."}, {"s": "q:sx_mk_gyeongdo", "t": "끝났습니다. 이 쪽에는 이제 조사원님 이름만 있습니다. 얼굴은 없습니다."}, {"s": null, "t": "나는 경도에게 그는 왜 이 일을 하느냐고 물었다. 경도는 열람실 구석의 깨진 거울 하나를 망치 끝으로 가리켰다."}, {"s": "q:sx_mk_gyeongdo", "t": "스무 해 전에 저도 들여다봤습니다. 그때는 이름을 덮어 쓰는 법을 몰랐지요."}, {"s": null, "t": "깨진 거울 속에 경도의 얼굴이 비쳤다. 바깥의 경도는 웃지 않았다. 거울 속의 경도는 웃고 있었다."}, {"s": "q:sx_mk_gyeongdo", "t": "어느 쪽이 먼저 나온 것인지, 저도 이제는 모릅니다. 그러니 조사원님은 이름을 꼭 쥐고 다니십시오."}, {"s": null, "t": "경도는 망치를 들고 다음 층으로 올라갔다. 계단을 오르는 발소리는 하나였다. 그런데 계단참 벽에 비친 그림자는 둘이었다."}]'::jsonb, '{"xp": 2763, "gil": 181, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
