delete from public.world_quest_steps where quest_id = 'mks_n_eel' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_eel', 1, '외상값 장부', '외상값 장부', '{"at": ["myeongbu_tower"]}'::jsonb, '[{"s": null, "t": "명부 탑 아래 돌계단에 늙은 사내 하나가 쪼그려 앉아, 탑 밑 수로를 들여다보며 손가락을 꼽고 있었다."}, {"s": null, "t": "사내는 나를 보자 벌떡 일어나 손을 비볐다. 손가락 마디마다 먹 자국이 있었다."}, {"s": "q:sx_mk_semdol", "t": "마침 잘 왔소. 나는 나루에서 셈돌이라고 불리는 사람이오. 셈을 잘해서가 아니라 맨날 셈을 틀려서 셈돌이야."}, {"s": "q:sx_mk_semdol", "t": "내가 이 탑 서고에서 죽간 한 묶음을 몰래 빌려 썼거든. 거기다 나루 사람들 외상값을 적어 뒀지. 탑 죽간은 먹비를 맞아도 글자가 안 지워지니까."}, {"s": null, "t": "나는 탑 죽간에 외상값을 적어도 되느냐고 물었다. 셈돌은 못 들은 척 수로를 가리켰다."}, {"s": "q:sx_mk_semdol", "t": "그런데 그 묶음을 수로에 떨어뜨렸어. 저 밑에 사는 죽간 대장어가 그걸 몸에 칭칭 감고 다녀. 마디가 죽간 같은 장어라서 제 몸인 줄 아나 봐."}, {"s": "q:sx_mk_semdol", "t": "장어를 낚기 전에 죽간부터 좀 모아 줘. 묶음을 되찾아도 끈이 삭았을 테니 새 죽간으로 덧대야 해. 탑에서 명부 죽간 세 개만."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_eel', 2, '장어가 좋아하는 냄새', '명부 탑에서 명부 죽간을(를) 모은다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "gather", "items": ["register_slip"], "r": ["myeongbu_tower"], "n": 3}]}'::jsonb, '[{"s": null, "t": "명부 죽간 세 개를 건네자, 셈돌은 하나씩 손가락으로 두드려 보고 소매에 쑤셔 넣었다."}, {"s": "q:sx_mk_semdol", "t": "좋아. 이제 미끼야. 죽간 대장어는 수로 물고기 냄새를 따라 나와. 흑잉어나 수로 뱀장어, 돌틈 망둥이, 수문 잉어 같은 거."}, {"s": "q:sx_mk_semdol", "t": "그런데 이 탑 수로 물고기는 먹을 하도 먹어서 장어가 안 쳐다봐. 바깥 물에서 낚은 걸 걸어야 해. 구룡 폐수로 같은 데 말이야."}, {"s": null, "t": "나는 셈돌이 그걸 어떻게 아느냐고 물었다. 셈돌은 손가락을 꼽으며 한숨을 쉬었다."}, {"s": "q:sx_mk_semdol", "t": "내가 장어 낚겠다고 여기서 낚은 미끼를 스물세 번 걸었거든. 스물세 번 다 안 물었어. 아니, 스물네 번이었나."}, {"s": "q:sx_mk_semdol", "t": "구룡 폐수로에서 두 번만 낚아 와. 미끼는 가방에 넣어 두었다가 낚시 칸에서 골라 걸면 되고."}]'::jsonb, '{"xp": 2763}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_eel', 3, '안개 낀 삼경', '구룡 폐수로에서 낚시를 한다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "fish", "r": ["old_canal"], "n": 2}]}'::jsonb, '[{"s": null, "t": "바깥 수로 물고기를 들고 탑 아래로 돌아오자, 셈돌이 코를 킁킁거리며 바구니에 얼굴을 들이밀었다."}, {"s": "q:sx_mk_semdol", "t": "이거야, 이 냄새. 먹 냄새가 안 나잖아."}, {"s": "q:sx_mk_semdol", "t": "죽간 대장어는 삼경에 나와. 그것도 안개가 짙게 낀 밤에만. 농무 끼면 탑 꼭대기가 안 보이거든. 그때 장어가 수로 위로 머리를 내밀어."}, {"s": null, "t": "셈돌은 수로 둑에 앉아 손가락을 하나씩 접었다. 오늘이 며칠인지, 안개가 언제 들지 세어 보는 모양이었다. 셈은 세 번 다 다르게 나왔다."}, {"s": "q:sx_mk_semdol", "t": "농무 끼는 삼경에, 탑 밑 먹 수로에서 장어를 낚아 줘. 장어 몸에 감긴 죽간만 풀면 돼."}]'::jsonb, '{"xp": 2763}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_eel', 4, '풀어 낸 죽간', '명부 탑에서 죽간 대장어을(를) 낚는다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "fish", "r": ["myeongbu_tower"], "f": ["bamboo_eel"], "n": 1}]}'::jsonb, '[{"s": null, "t": "안개 속에서 끌어올린 장어 몸에 죽간 묶음이 칭칭 감겨 있었다. 셈돌이 달려와 장어 몸에서 죽간을 한 마디씩 풀어냈다."}, {"s": null, "t": "셈돌은 풀어낸 죽간을 둑 위에 펼쳤다. 그리고 한 줄씩 읽어 내려가다가, 갑자기 입을 다물었다."}, {"s": "q:sx_mk_semdol", "t": "……이거 내 외상이네."}, {"s": null, "t": "죽간에는 나루 사람들 이름이 아니라 셈돌의 이름이 줄줄이 적혀 있었다. 이름 아래에는 주막 외상과 국밥집 외상, 사공 뱃삯 외상이 차례로 적혀 있었다."}, {"s": "q:sx_mk_semdol", "t": "내가 남한테 받을 걸 적은 줄 알았는데, 내가 갚을 걸 적어 놨었구먼. 셈을 또 틀렸어."}, {"s": null, "t": "셈돌은 한참 죽간을 내려다보다가, 머리를 긁적이며 웃었다."}, {"s": "q:sx_mk_semdol", "t": "할 수 없지. 갚아야지. 빈손으로 가면 문전박대를 당할 테니, 그 장어로 명부 장어 구이를 하나 구워 줘. 그거 들고 주막에 가서 외상부터 빌어야겠어."}]'::jsonb, '{"xp": 2763}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_eel', 5, '첫 번째로 갚은 외상', '명부 장어 구이을(를) 만든다, 명부 장어 구이을(를) 넘긴다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "craft", "items": ["register_eel_grill"], "n": 1}], "give": {"register_eel_grill": 1}}'::jsonb, '[{"s": null, "t": "명부 장어 구이를 건네자, 셈돌은 그것을 보자기에 싸서 품에 안았다. 그리고 죽간을 다시 묶어 어깨에 멨다."}, {"s": "q:sx_mk_semdol", "t": "이걸 들고 가면 주막 아낙이 반은 깎아 주겠지. 아니, 삼 할이나 깎아 주려나."}, {"s": null, "t": "셈돌은 손가락을 꼽으며 돌계단을 내려갔다. 몇 걸음 가다 말고 돌아보았다."}, {"s": "q:sx_mk_semdol", "t": "조사원, 고맙소. 덕분에 내 이름이 죽간에 남아 있다는 걸 알았어. 갚을 게 있다는 건 나를 기억하는 사람이 있다는 거니까."}, {"s": null, "t": "셈돌은 다시 손가락을 꼽으며 나루 쪽으로 걸어갔다. 이번에는 몇 번을 세어도 같은 수가 나오는지, 고개를 끄덕이고 있었다."}]'::jsonb, '{"xp": 2763, "gil": 181, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
