values ('mke_daon_1', 'side', '외전·묵적록', '서른 개의 빈 위패', '다온이 공책에 적은 이름들을 이름 없는 사당의 빈 위패에 옮겨 적으려 한다.', 'mukchang_ferry', 45, '{mkq_5}'::text[], null, 1328, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_daon_1' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_1', 1, '공책 뒷장', '공책 뒷장', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "다온이 주막 평상에 공책을 펼쳐 놓고 손가락으로 이름을 하나씩 짚고 있었다. 내가 풀어 보낸 이들의 이름이었다. 이름 옆에는 「키가 큼」, 「웃음소리가 큼」 같은 작은 글씨가 붙어 있었다."}, {"s": "q:mk_daon", "t": "{이름} 님, 이 사람들 사당에 이름 써 주고 싶어요. 아무 글자 없는 위패가 아직 많잖아요."}, {"s": "q:mk_daon", "t": "근데 어느 나무가 누구 건지 몰라요. 아무거나 쓰면 안 되잖아요."}, {"s": null, "t": "아이는 공책 귀퉁이를 접었다 폈다 했다. 접힌 자리가 이미 닳아 있었다."}, {"s": "q:mk_daon", "t": "새 위패부터 깎아 두래요. 노을 할아버지가요. 옛날 위패는 너무 바래서 붓이 안 먹는대요."}, {"s": "q:mk_daon", "t": "먹비 숲 흑단으로 깎으면 백 년도 간대요. 세 개만 해 와 주세요. 할아버지가 깎아 준댔어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_1', 2, '노 깎는 손', '먹비 숲에서 먹비 흑단을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["meokbi_ebony"], "r": ["meokbi_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "흑단을 들고 선창에 가자 늙은 사공이 노를 손질하고 있었다. 사공은 흑단을 받아 결을 손톱으로 쓸어 보고, 고개를 한 번 끄덕였다."}, {"s": "q:sx_mk_sagong", "t": "좋은 나무일세. 노로 깎기엔 아깝고 위패로는 딱 맞네."}, {"s": null, "t": "사공은 칼을 꺼내 흑단을 다듬기 시작했다. 깎는 동안 다온이 그 옆에 쪼그려 앉아 대팻밥을 모았다."}, {"s": null, "t": "사공은 깎던 나무를 눈높이로 들어 결을 살폈다."}, {"s": "q:sx_mk_sagong", "t": "그런데 아가, 어느 위패가 누구 것인지는 사당에 가서 세어 봐야 알걸세. 위패를 세운 사람마다 나무를 다르게 깎았거든."}, {"s": null, "t": "다온이 대팻밥을 모으던 손을 멈추고 사공을 올려다보았다."}, {"s": "q:mk_daon", "t": "할아버지도 세웠어요?"}, {"s": null, "t": "사공은 칼질을 멈추지 않았다. 대답은 한참 뒤에 나왔다."}, {"s": "q:sx_mk_sagong", "t": "……하나 세웠지. 누구 것인지는 나도 이제 몰라."}, {"s": null, "t": "사공은 칼을 내려놓고 벌판 쪽을 바라보았다. 다온은 그 얼굴을 한참 보다가 내 손을 잡았다."}, {"s": "q:mk_daon", "t": "{이름} 님, 사당 가요. 위패 몇 개인지 같이 세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_1', 3, '서른 개', '빈칸 벌판에 간다, 빈칸 벌판을(를) 살핀다', '{"at": ["blank_field"], "tasks": [{"t": "travel", "r": ["blank_field"], "n": 1}, {"t": "search", "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "사당 터를 돌며 위패를 셌다. 맨 끝의 「서하」와 그 옆에 다온이 세운 「서율」·「이랑」을 빼고, 글자 없는 위패는 꼭 서른 개였다."}, {"s": null, "t": "다온은 위패 하나하나 앞에 쪼그려 앉아 밑동을 들여다보았다. 위패마다 깎은 자국이 조금씩 달랐다. 어떤 것은 모서리를 둥글렸고, 어떤 것은 밑에 금을 그어 두었다."}, {"s": "q:mk_daon", "t": "이건 칼자국이 세 번이에요. 이건 두 번이고. 노을 할아버지 말이 맞아요. 다 다르게 깎았어요."}, {"s": "q:mk_daon", "t": "그럼 깎은 사람을 찾으면 누구 건지 알 수 있겠네요."}, {"s": null, "t": "아이는 공책 새 장을 펼쳐 위패마다 번호를 매기고 칼자국 모양을 그렸다. 그림은 삐뚤빼뚤했지만 하나도 빠뜨리지 않았다."}, {"s": "q:mk_daon", "t": "사당 둘레 어딘가에 깎다 버린 나무가 있을지도 몰라요. 위패 깎은 사람이 연장을 두고 간 자리 같은 거요. 찾아봐 줘요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_1', 4, '버려진 칼', '빈칸 벌판에서 실마리를 찾는다', '{"at": ["blank_field"], "tasks": [{"t": "clue", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "사당 뒤 억새 속에서 녹슨 칼 한 자루와 깎다 만 나무토막 몇 개를 찾아냈다. 칼자루에는 「국밥」이라는 두 글자가 새겨져 있었다."}, {"s": "q:mk_daon", "t": "덕배 할아버지 거예요! 국밥집 칼이요. 할아버지는 칼에 다 이름 써 놔요."}, {"s": null, "t": "다온이 칼을 받아 들고 웃으려는 순간, 억새 그늘에서 길쭉한 손이 하나 솟아올랐다. 손은 사당 지붕으로 기어올라 위패 하나를 움켜쥐었다."}, {"s": "q:mk_daon", "t": "안 돼! 그거 아직 이름도 안 썼단 말이에요!"}, {"s": null, "t": "손 하나가 아니었다. 사당 둘레의 억새마다 손이 하나씩 솟아 위패를 뜯어 가려 했다. 나는 다온을 사당 안으로 밀어 넣었다."}, {"s": "q:mk_daon", "t": "{이름} 님, 저거 다 쫓아 줘요! 저는 위패 꼭 붙잡고 있을게요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_1', 5, '기억 보태기', '문패 뜯는 손을(를) 물리친다', '{"at": ["blank_field"], "tasks": [{"t": "win", "m": ["mk_field_3"], "n": 5}]}'::jsonb, '[{"s": null, "t": "마지막 손이 억새 속으로 스러지자 다온이 위패를 끌어안은 채 사당 밖으로 나왔다. 무릎에 흙이 묻어 있었다. 아이는 흙을 털지도 않고 칼을 품에 넣었다."}, {"s": "q:mk_daon", "t": "나루 가서 물어봐요. 덕배 할아버지랑, 묵창댁 아주머니랑, 노을 할아버지랑. 누가 어떤 위패 깎았는지요."}, {"s": "q:mk_daon", "t": "이름 쓸 먹도 있어야 해요. 서리님이 그랬어요. 이름 먹 부적 먹으로 쓰면 먹비 맞아도 안 지워진대요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_1', 6, '서른 개의 이름', '묵창 나루에 간다, 이름 먹 부적을(를) 만든다, 이름 먹 부적을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "travel", "r": ["mukchang_ferry"], "n": 1}, {"t": "craft", "items": ["name_ink_charm"], "n": 2}], "give": {"name_ink_charm": 2}}'::jsonb, '[{"s": null, "t": "주막 평상에 나루 사람들이 모였다. 다온이 그려 온 칼자국 그림을 하나씩 내밀면, 누군가 「그건 내가 깎은 거야」 하고 손을 들었다."}, {"s": null, "t": "국밥집 노인 덕배가 그림 하나를 오래 들여다보았다. 칼자국 세 번, 밑동에 그은 금 하나였다."}, {"s": "q:sx_mk_gukbap", "t": "이건 우리 아들 거야. 우리 아들 거. 이름은 생각이 안 나. 그래도 이건 우리 아들 거야."}, {"s": null, "t": "다온이 공책을 넘겨 덕배 앞에 내밀었다. 내가 풀어 보낸 이름들 가운데 「웃음소리가 큼」이라고 적힌 줄이었다. 덕배가 그 줄을 손가락으로 짚고, 한참 아무 말도 하지 못했다."}, {"s": "q:sx_mk_gukbap", "t": "……맞아. 웃음소리가 컸어. 우리 아들이 그랬어."}, {"s": null, "t": "그날 밤 서른 개 가운데 열둘의 주인을 찾았다. 다온은 내가 지어 온 이름 먹 부적을 녹인 먹으로 새 흑단 위패 열두 개에 이름을 적었다. 나머지 열여덟 개에는 이름 대신 「키가 큼」, 「노래를 잘함」 같은 공책의 작은 글씨를 옮겨 적었다."}, {"s": "q:mk_daon", "t": "이름을 몰라도 이렇게 쓰면 누군지 알잖아요. 나중에 이름 생각나는 사람이 있으면 그 옆에 쓰면 돼요."}, {"s": null, "t": "희수가 평상 끝에서 그 모습을 지켜보다가, 정청 명부를 펼쳐 열두 이름 옆 「불러 주는 이」 칸에 다온의 이름을 적었다."}, {"s": "q:mk_hisu", "t": "내일 사당에 세우러 가자. 조사원도 같이요."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
