values ('mke_daon_2', 'side', '외전·묵적록', '다온이라는 이름', '다온은 엄마 이랑이 왜 「다온」이라고 지었는지 알고 싶어 한다. 나루 사람들이 이랑의 기억을 한 조각씩 보탠다.', 'mukchang_ferry', 45, '{mke_daon_1}'::text[], null, 1329, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_daon_2' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_2', 1, '엄마가 지은 이름', '엄마가 지은 이름', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "다온이 새 공책 첫 장에 이름 둘을 나란히 적고 있었다. 하나는 「다온」, 하나는 「이랑」이었다. 엄마 이름을 안 지 보름이 지났는데, 아이는 아직도 그 두 글자를 하루에 몇 번씩 새로 적었다."}, {"s": null, "t": "다온은 붓을 내려놓고 두 이름을 번갈아 보다가 나를 올려다보았다."}, {"s": "q:mk_daon", "t": "{이름} 님. 다온은 엄마가 지어 준 이름이죠? 그럼 엄마는 왜 다온이라고 했을까요?"}, {"s": "q:mk_daon", "t": "엄마가 저를 부르던 소리는 생각나요. 근데 얼굴이 자꾸 흐려져요. 이름을 알게 됐으니까, 이제 엄마 얘기도 모으고 싶어요. 공책에 적어 두게요."}, {"s": null, "t": "아이는 공책 귀퉁이를 손톱으로 긁었다. 엄마 이름을 찾고 나서도 그 버릇은 그대로였다."}, {"s": "q:mk_daon", "t": "묵창댁 아주머니한테 물었더니 노을 할아버지한테 먼저 가 보래요. 엄마랑 저를 처음 나루로 건네준 사람이 할아버지래요."}, {"s": "q:mk_daon", "t": "근데 할아버지는 물고기 물 때만 말을 해요. 선창에서 같이 낚시해 주세요. 두 마리쯤 낚으면 말할 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_2', 2, '강을 건너온 사람', '묵창 나루에서 낚시를 한다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "n": 2}]}'::jsonb, '[{"s": null, "t": "두 번째 물고기가 올라오자 노을 영감은 찌를 거두고 노를 무릎에 얹었다. 다온이 그 옆에 바짝 붙어 앉았다."}, {"s": "q:sx_mk_sagong", "t": "먹비가 사흘 내리다 그친 아침이었네. 빙혼곡 쪽 나루터에서 젊은 아낙 하나가 내 배를 불러 세웠지."}, {"s": "q:sx_mk_sagong", "t": "등에는 포대기에 싼 갓난아이를 업고 있었어. 짐은 보따리 하나뿐이었고. 그 아이가 너였네, 아가. 그 아낙이 이랑이었고."}, {"s": null, "t": "다온은 숨을 죽이고 들었다. 노을 영감은 노의 갈라진 결을 손톱으로 쓸며 말을 이었다."}, {"s": "q:sx_mk_sagong", "t": "강을 건너는 내내 등에 업은 아이한테 뭐라고 중얼거리더군. 무슨 말인지는 노 젓는 소리에 묻혀 못 들었네."}, {"s": "q:sx_mk_sagong", "t": "나루에 와서는 덕배네 국밥집 부엌일을 했지. 그러니 그 사람 얘기라면 덕배가 제일 많이 알 걸세. 그런데 덕배는 빙혼곡 너머로 국거리를 사러 가서 사흘째 안 돌아왔네."}, {"s": null, "t": "다온의 어깨가 움츠러들었다. 그러다 벌떡 일어나 내 소매를 잡아끌었다."}, {"s": "q:mk_daon", "t": "빙혼곡이요? 거기 무서운데. 할아버지 혼자 갔어요? {이름} 님, 데리러 가요. 엄마 얘기도 물어보고요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_2', 3, '고갯마루의 노인', '빙혼곡에 간다, 빙혼곡을(를) 살핀다', '{"at": ["frost_valley"], "tasks": [{"t": "travel", "r": ["frost_valley"], "n": 1}, {"t": "search", "r": ["frost_valley"], "n": 3}]}'::jsonb, '[{"s": null, "t": "빙혼곡 고갯마루 바위 그늘에 덕배가 국거리 짐을 끌어안고 웅크리고 있었다. 머리 위 얼어붙은 가지마다 서리 까마귀가 새카맣게 앉아 짐을 노리고 있었다."}, {"s": "q:sx_mk_gukbap", "t": "아이고, 조사원. 왔구나. 왔어. 저것들이 내 짐을 노려. 무를 쪼아 먹었어. 무를."}, {"s": null, "t": "까마귀 한 마리가 내려와 짐 끈을 물어뜯었다. 덕배가 짐을 더 꼭 끌어안았다. 다온이 내 뒤에서 팔을 휘저었다."}, {"s": "q:mk_daon", "t": "저리 가! 할아버지 국 끓일 거란 말이야!"}, {"s": null, "t": "덕배가 그제야 다온을 알아보고 눈을 끔벅였다."}, {"s": "q:sx_mk_gukbap", "t": "다온이도 왔어? 이런 데까지 왔어?"}, {"s": null, "t": "까마귀들이 다온의 고함에 한꺼번에 날아올랐다. 그러고는 우리 머리 위를 빙빙 돌며 내려올 틈을 노렸다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_2', 4, '부엌의 노래', '서리 까마귀을(를) 물리친다', '{"at": ["frost_valley"], "tasks": [{"t": "win", "m": ["x_frost_valley_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "까마귀 떼가 흩어지자 덕배는 짐 위에 걸터앉아 숨을 골랐다. 다온이 엄마 이야기를 꺼내자, 노인은 한참 눈을 끔벅이다 무릎을 쳤다."}, {"s": "q:sx_mk_gukbap", "t": "이랑이. 그래, 이랑이. 지난달까지는 이 이름이 입에서 안 나왔어. 안 나왔어. 나루 이름이 다 흐려질 때였으니까."}, {"s": "q:sx_mk_gukbap", "t": "이랑이는 우리 집 부엌에서 국을 끓였어. 국을 젓는 내내 노래를 불렀지. 「따순 국, 따순 손, 다 따숩게 커라.」 그러다 끝에 꼭 「다온아」 하고 불렀어. 등에 업은 너를."}, {"s": null, "t": "덕배는 품을 더듬어 낡은 복주머니 하나를 꺼냈다. 안에서 접힌 한지 한 장이 나왔다. 서툰 글씨로 「다온」 두 글자가 적혀 있었다."}, {"s": "q:sx_mk_gukbap", "t": "이랑이는 글을 몰랐어. 몰랐어. 그래서 내가 종이에 네 이름을 써 줬지. 이랑이가 그걸 보고 따라 썼어. 이건 이랑이가 쓴 거야."}, {"s": "q:sx_mk_gukbap", "t": "이랑이가 쓰러지던 날 부엌 선반에서 이걸 주워 넣었어. 너한테 주려고 했는데 그만 잊어버렸지. 늙으면 이래. 미안하다."}, {"s": null, "t": "다온은 한지를 두 손으로 받아 들고 아무 말도 하지 못했다. 엄마가 쓴 글자는 획이 흔들리고 삐뚤빼뚤했다. 다온이 처음 공책에 내 이름을 따라 쓰던 날의 글씨와 닮아 있었다."}, {"s": null, "t": "덕배가 일어서려다 다리를 휘청였다. 사흘을 고갯마루에서 버틴 다리였다."}, {"s": "q:sx_mk_gukbap", "t": "배가 고파서 못 걷겠어. 못 걷겠어. 조사원, 건량 좀 지어 줄 수 있어? 먹고 같이 내려가자."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_2', 5, '한 조각씩', '노정 건량을(를) 만든다, 묵창 나루에 간다, 노정 건량을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["travel_ration"], "n": 2}, {"t": "travel", "r": ["mukchang_ferry"], "n": 1}], "give": {"travel_ration": 2}}'::jsonb, '[{"s": null, "t": "덕배를 부축해 나루로 돌아오자 주막에 사람들이 모여들었다. 다온은 엄마가 쓴 한지를 평상 한가운데 펼쳐 놓고 공책을 꺼내 들었다."}, {"s": "q:mk_daon", "t": "엄마 얘기 아는 거 있으면 하나씩 말해 주세요. 다 적을 거예요."}, {"s": null, "t": "묵창댁이 국자를 내려놓고 한지를 들여다보았다. 한참 보다가 코를 훌쩍였다."}, {"s": "q:sx_mk_jumak", "t": "이랑이는 빨래를 할 때도 노래를 불렀어. 방망이질에 맞춰서. 다 따숩게, 다 따숩게. 시끄럽다고 내가 몇 번이나 핀잔을 줬는데."}, {"s": null, "t": "노을 영감이 평상 끝에 걸터앉아 헛기침을 했다."}, {"s": "q:sx_mk_sagong", "t": "강을 건널 때 중얼거리던 말 말일세. 이제 생각해 보니 그것도 그 노래였던 것 같네."}, {"s": null, "t": "덕배가 국밥 한 그릇을 다 비우고 나서 숟가락을 내려놓았다."}, {"s": "q:sx_mk_gukbap", "t": "온이라는 글자가 따뜻하다는 뜻이래. 따뜻하다는 뜻. 누구한테든 다 따뜻한 사람으로 크라고, 그래서 다온이라고 지었다더라. 이랑이가 그랬어."}, {"s": "q:sx_mk_gukbap", "t": "저는 추운 데서 업고 건너왔으니, 너는 남한테 국 한 그릇 데워 주는 사람이 되라고. 그 말을 몇 번이나 했는지 몰라."}, {"s": null, "t": "다온은 한 줄씩 받아 적었다. 「노래를 잘함」, 「빨래할 때도 부름」, 「강 건널 때도 부름」. 적다가 붓을 멈추고 손등으로 눈가를 문질렀다."}, {"s": "q:mk_daon", "t": "엄마가 저 부를 때마다 따뜻하게 크라고 한 거네요. 매번요."}, {"s": null, "t": "희수가 사람들 틈에서 나와 엄마의 한지를 들여다보았다. 정청 명부를 펼쳐 무언가를 적으려다 말고 다온을 보았다."}, {"s": "q:mk_hisu", "t": "다온아, 네 집 문패 말이야. 아직 글자가 다 지워진 채지. 새로 하나 달자. 이번엔 네 이름으로."}, {"s": null, "t": "다온이 펄쩍 일어나 희수의 소매를 붙잡았다."}, {"s": "q:mk_daon", "t": "정말요? 그럼 흑단으로 해요! 위패처럼 백 년 가게요. {이름} 님, 흑단 두 개만 해 와 주세요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_2', 6, '새 문패', '먹비 숲에서 먹비 흑단을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["meokbi_ebony"], "r": ["meokbi_forest"], "n": 2}]}'::jsonb, '[{"s": null, "t": "노을 영감이 흑단으로 문패를 깎았다. 다온이 이름 먹으로 위 칸에 제 이름을 적었다. 이번에는 한 번에, 한 획도 흔들리지 않았다."}, {"s": null, "t": "다온은 붓을 내려놓으려다 다시 들었다. 문패 아래 칸에 엄마가 쓴 한지를 대고, 흔들리는 그 글씨를 그대로 따라 「다온」을 한 번 더 적었다. 그 옆에는 작게 「이랑」이라고 적었다."}, {"s": "q:mk_daon", "t": "위에 건 제가 쓴 거고, 아래 건 엄마 글씨예요. 엄마가 저 부르던 이름이니까 엄마 글씨로 하나 더 있어야 해요."}, {"s": null, "t": "아이는 문패 맨 끝에 내 이름도 작게 적었다. 그러고는 내 얼굴을 보고 쑥스러운 듯 웃었다."}, {"s": "q:mk_daon", "t": "{이름} 님은 이름 불러 준 사람이니까 써도 돼요."}, {"s": null, "t": "문패가 아이 집 대문에 걸렸다. 지워진 글자 위에 새 글자가 또렷했다. 묵창댁이 국자로 문패를 톡톡 두드렸다."}, {"s": "q:sx_mk_jumak", "t": "이제 이 집 이름은 안 지워지겠다. 먹비가 와도."}, {"s": null, "t": "다온은 문패를 올려다보며 고개를 힘차게 끄덕였다. 그러고는 아무도 듣지 않을 만큼 작게, 엄마의 노래를 한 소절 불렀다."}, {"s": "q:mk_daon", "t": "따순 국, 따순 손. 다 따숩게 커라."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
