values ('mke_daon_3', 'side', '외전·묵적록', '서당 가는 길', '다온이 정청 서당에서 글을 배우기로 한다. 조사원은 나루에서 본부까지 바래다준다.', 'mukchang_ferry', 45, '{mke_daon_2}'::text[], null, 1330, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_daon_3' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_3', 1, '서당 자리', '서당 자리', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "희수가 정청에서 온 편지를 들고 다온의 집 문 앞에 서 있었다. 새로 단 문패 아래에서 한참 망설이다가 문을 두드렸다."}, {"s": "q:mk_hisu", "t": "다온아. 연 서기관님이 정청 서당에 네 자리를 하나 내주시겠대. 글을 제대로 배울 수 있어."}, {"s": null, "t": "다온이 문간에서 편지를 받아 읽었다. 이제는 막힘없이 읽었다. 그런데 다 읽고 나서도 고개를 들지 않았다."}, {"s": "q:mk_daon", "t": "……나루를 떠나야 해요?"}, {"s": null, "t": "희수는 문간에 쪼그려 앉아 다온과 눈높이를 맞췄다."}, {"s": "q:mk_hisu", "t": "봄까지만. 봄이 되면 돌아와서 내 명부 일을 거들어 주면 돼."}, {"s": null, "t": "다온은 편지를 접고 벌판 쪽을 보았다. 그러다 무언가 결심한 얼굴로 나를 돌아보았다."}, {"s": "q:mk_daon", "t": "그럼 가기 전에 벌판 길부터 치워 줘요. 제가 없는 동안 나루 사람들이 사당 갈 때 안 무섭게요."}, {"s": "q:mk_daon", "t": "하루 다녀오는 걸로는 안 되잖아요. 원정으로요. 끝까지요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_3', 2, '두 권의 공책', '빈칸 벌판에 원정을 다녀온다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "expedition", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정에서 돌아오니 다온이 짐을 꾸리고 있었다. 보따리는 작았다. 옷 두 벌, 붓 한 자루, 그리고 공책 두 권이었다."}, {"s": "q:mk_daon", "t": "첫 권은 {이름} 님 이름 처음 쓴 거고요, 두 권째는 엄마 얘기랑 나루 사람들 이름 적은 거예요. 둘 다 가져가요."}, {"s": null, "t": "주막 처마 밑에서 월하가 엽전을 굴리며 그 모습을 지켜보았다. 다온이 보따리를 묶는 동안 다가와, 보따리 매듭 사이에 무언가를 슬쩍 끼워 넣었다."}, {"s": "q:mk_wolha", "t": "노잣돈이다, 꼬맹아. 빌려주는 거야. 이자는 글 배워서 갚아."}, {"s": null, "t": "다온이 보따리 매듭을 내려다보고 눈을 가늘게 떴다."}, {"s": "q:mk_daon", "t": "아저씨한테 빌리면 이자 무서운데요."}, {"s": null, "t": "월하는 다온의 머리를 손바닥으로 꾹 눌렀다."}, {"s": "q:mk_wolha", "t": "그러니까 열심히 배워."}, {"s": null, "t": "희수가 그 말을 듣고 월하를 흘겨보았다. 그러면서도 아무 말 하지 않았다. 대신 내 쪽으로 돌아섰다."}, {"s": "q:mk_hisu", "t": "{이름} 조사원, 빙혼곡을 넘으면 다온이 추위를 탈 거예요. 청심환을 두 알만 지어 챙겨 주세요. 저는 나루를 비울 수가 없어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_3', 3, '읽을 수 있는 이정표', '청심환을(를) 만든다, 빙혼곡에 간다, 청심환을(를) 넘긴다', '{"at": ["frost_valley"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 2}, {"t": "travel", "r": ["frost_valley"], "n": 1}], "give": {"tonic": 2}}'::jsonb, '[{"s": null, "t": "빙혼곡 고갯마루에 오르자 다온은 청심환 한 알을 입에 물고 길가 이정표 앞에 멈춰 섰다. 이정표 글씨를 한 자씩 소리 내어 읽었다."}, {"s": "q:mk_daon", "t": "「묵창 나루 반나절」. 「본부 사흘」. ……{이름} 님, 저 이거 다 읽혀요."}, {"s": null, "t": "아이는 이정표 앞에서 한참 서 있었다. 그러다 문패 하나 없는 고갯마루 오두막 쪽을 보고 고개를 갸웃했다."}, {"s": "q:mk_daon", "t": "저 집은 문패가 없네요. 이름이 없는 집이에요?"}, {"s": null, "t": "대답하기 전에 오두막 뒤 눈밭에서 낮은 으르렁 소리가 났다. 설원 늑대들이 눈 속에서 하나둘 일어서고 있었다. 다온이 보따리를 끌어안고 내 뒤로 물러났다."}, {"s": "q:mk_daon", "t": "공책은 제가 지킬게요! {이름} 님은 늑대요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_3', 4, '처음 보는 마을', '설원 늑대을(를) 물리친다', '{"at": ["frost_valley"], "tasks": [{"t": "win", "m": ["g_frost_valley"], "n": 8}]}'::jsonb, '[{"s": null, "t": "늑대들이 흩어진 눈밭을 지나 고개를 내려가는 동안, 다온은 길가에 늘어선 마을의 문패를 하나도 빠짐없이 읽었다. 읽을 때마다 공책에 적었다."}, {"s": "q:mk_daon", "t": "나루 밖에도 이름이 이렇게 많아요. 다 안 지워졌어요."}, {"s": null, "t": "아이의 목소리가 점점 작아졌다. 걸음도 느려졌다. 하루 종일 걷고 읽은 아이였다."}, {"s": "q:mk_daon", "t": "{이름} 님, 오늘은 어디서 자요? 서리님이 객사라는 데가 있다고 했어요."}, {"s": null, "t": "나는 본부 객사가 멀지 않다고 했다. 다온은 졸린 눈으로 고개를 끄덕이고, 내 소매 끝을 붙잡았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_3', 5, '객사의 아침', '본부 객사에 간다, 본부 객사에서 쉰다', '{"at": ["hq_dorm"], "tasks": [{"t": "travel", "r": ["hq_dorm"], "n": 1}, {"t": "rest", "r": ["hq_dorm"], "n": 1}]}'::jsonb, '[{"s": null, "t": "객사에서 하룻밤을 자고 나니 다온은 다시 기운이 넘쳤다. 아침 내내 객사 마당을 돌며 처마 밑 현판과 방문마다 붙은 이름표를 읽었다."}, {"s": "q:mk_daon", "t": "여기는 다 이름표가 붙어 있어요. 방에도, 우물에도, 말 매는 기둥에도요."}, {"s": null, "t": "아이는 문득 걸음을 멈추고 정청 쪽 지붕을 바라보았다. 보따리 끈을 쥔 손에 힘이 들어갔다."}, {"s": "q:mk_daon", "t": "……서당에서 저 받아 줄까요? 저 글 늦게 배웠는데."}, {"s": null, "t": "나는 연서희가 이미 자리를 내주었다고 했다. 다온은 고개를 끄덕였지만 발이 떨어지지 않는 얼굴이었다."}, {"s": "q:mk_daon", "t": "조금만 있다 가요. 마음 다 정하고요. {이름} 님은 그동안 할 일 하고 계세요. 다 끝나면 저도 갈게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_daon_3', 6, '서당의 첫 장', '야행국 본부 정청에 간다, 자율 활동을 끝까지 마친다', '{"at": ["hq_yard"], "tasks": [{"t": "travel", "r": ["hq_yard"], "n": 1}, {"t": "idle", "n": 1}]}'::jsonb, '[{"s": null, "t": "다온은 정청 대청 앞에서 보따리를 내려놓고 숨을 크게 쉬었다. 사건 서기관 연서희가 서당 문간에서 걸어 나왔다."}, {"s": "q:m_yeon", "t": "다온이구나. 희수한테 얘기 많이 들었어. 이름을 공책에 적어 두면 안 잊는다고 믿는다며."}, {"s": null, "t": "다온이 보따리 끈을 꼭 쥐고 턱을 들었다."}, {"s": "q:mk_daon", "t": "믿는 게 아니라 진짜예요."}, {"s": null, "t": "연서희가 웃음을 터뜨렸다. 아이 앞에 쪼그려 앉아 빈 공책 한 권을 내밀었다."}, {"s": "q:m_yeon", "t": "그럼 서당 첫날 숙제야. 여기 첫 장에 이름 둘을 적어 봐. 네 이름하고, 네가 제일 먼저 불러 준 사람 이름."}, {"s": null, "t": "다온은 붓을 쥐고 첫 장에 제 이름을 적었다. 그 옆에 내 이름을 적었다. 이번에는 획 하나 빠지지 않은, 반듯한 글씨였다."}, {"s": null, "t": "다온은 붓을 내려놓고 보따리를 풀었다. 그 안에서 작은 앉은뱅이책상 하나와 나무패 하나를 꺼내 내 앞에 놓았다."}, {"s": "q:mk_daon", "t": "이 책상은 나루 집에서 공책 쓰던 거예요. 여기는 서당 책상이 있으니까 {이름} 님 별채에 두세요. 두 권째 공책도 이 책상에서 썼어요."}, {"s": "q:mk_daon", "t": "이건 {이름} 님 이름패예요. 노을 할아버지한테 칼 쓰는 거 배워서 제가 팠어요. 좀 삐뚤어요. 그래도 안 지워져요."}, {"s": null, "t": "나무패의 글씨는 정말로 조금 삐뚤었다. 처음 공책에 내 이름을 따라 썼던 날의 글씨와 닮아 있었다."}, {"s": "q:mk_daon", "t": "봄에 나루로 돌아가요. 그때 데리러 와 줘요. 약속이에요."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_mk_notedesk": 1, "of_acc_mk_nameplate": 1}, "title": "mk_keep_daon"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
