values ('mke_hisu_1', 'side', '외전·묵적록', '감찰이 온다', '희수가 회수 명부에 일부러 틀리게 그은 한 획 때문에 기록감찰국 감찰이 나루로 온다.', 'mukchang_ferry', 45, '{mkq_5}'::text[], null, 1331, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_hisu_1' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_1', 1, '정청의 배', '정청의 배', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "봉인진이 닫히고 열흘쯤 지난 새벽이었다. 먹빛 강 위로 정청의 붉은 깃발을 단 배 한 척이 미끄러져 들어왔다."}, {"s": null, "t": "배에서 내린 사람은 회색 관복을 입은 감찰 하나였다. 감찰은 선창을 한 바퀴 둘러보고, 품에서 꺼낸 장부를 손끝으로 넘겼다. 장을 넘길 때마다 손끝을 혀에 댔다."}, {"s": "q:sx_mke_dangyeong", "t": "기록감찰국 감찰 단경이오. 묵창 나루 출납 서리 희수를 찾소."}, {"s": null, "t": "주막 문간에 서 있던 희수가 장부를 끌어안은 채 걸어 나왔다. 걸음은 흔들리지 않았지만, 장부를 쥔 손가락 마디가 하얬다."}, {"s": "q:mk_hisu", "t": "제가 희수입니다."}, {"s": null, "t": "감찰은 희수를 위아래로 한 번 훑고, 장부의 한 장을 펼쳐 들었다."}, {"s": "q:sx_mke_dangyeong", "t": "명부 탑 회수 명부 한 장에 틀린 획이 있소. 틀린 기록은 무효요. 일부러 틀렸다면 그 서리는 파직이오."}, {"s": "q:sx_mke_dangyeong", "t": "물어보겠소. 그 획은 손이 떨려 틀렸소, 일부러 그었소?"}, {"s": null, "t": "희수는 대답하기 전에 나를 한 번 보았다. 그러고는 감찰 쪽으로 똑바로 고개를 돌렸다."}, {"s": "q:mk_hisu", "t": "제가 일부러 그었습니다."}, {"s": null, "t": "감찰은 놀라지 않았다. 장부에 무언가를 한 줄 적고, 나를 돌아보았다."}, {"s": "q:sx_mke_dangyeong", "t": "그 명부에 이름이 오른 조사원이 당신이구려. 무효가 된 기록 대신 무엇이 남았는지, 내가 직접 보고 가겠소."}, {"s": "q:sx_mke_dangyeong", "t": "먼저 본청 서고에서 그날 들어온 보고를 맞춰 보시오. 나는 여기서 서리의 장부를 보겠소."}, {"s": null, "t": "희수가 감찰 몰래 내 소매를 짧게 당겼다. 목소리를 낮췄다."}, {"s": "q:mk_hisu", "t": "{이름} 조사원, 본청 서고 셋째 칸에 그날 봉인진 보고가 들어갔을 거예요. 연 서기관님께 여쭈면 찾아 주실 겁니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_1', 2, '셋째 칸의 보고', '야행국 본부 정청에 간다, 자율 활동을 끝까지 마친다', '{"at": ["hq_yard"], "tasks": [{"t": "travel", "r": ["hq_yard"], "n": 1}, {"t": "idle", "n": 1, "k": "research"}]}'::jsonb, '[{"s": null, "t": "본청 서고에서 반나절을 뒤졌다. 셋째 칸 맨 아래에서 봉인진 보고를 찾아냈을 때, 서고 문간에 사건 서기관 연서희가 서 있었다."}, {"s": null, "t": "연서희는 내가 든 보고를 보고 한숨을 쉬었다. 안으로 들어와 보고 끝장을 손가락으로 짚었다."}, {"s": "q:m_yeon", "t": "여기 보세요. 「봉인 닿음. 회수 늦게 닿음.」 봉인진 담당 서리가 적은 거예요. 늦은 까닭은 비어 있어요. 희수가 쓴 보고가 아니라서 다행이에요."}, {"s": "q:m_yeon", "t": "희수는 제가 처음 서고 일을 가르친 아이예요. 한 번도 틀린 적이 없어서, 다들 붓을 맡기면 걱정을 안 했죠."}, {"s": null, "t": "연서희는 보고 사본을 한 장 떠서 내 손에 쥐여 주었다. 종이를 건네는 손이 오래 머물렀다."}, {"s": "q:m_yeon", "t": "감찰 단경은 깐깐한 사람이에요. 대신 본 것만 믿어요. 보여 주세요. 희수가 남긴 게 무엇인지."}, {"s": "q:m_yeon", "t": "아마 빈칸 벌판부터 보자고 할 거예요. 먹귀가 아직 모이는지, 조사원 손에 먹이 다시 묻는지요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_1', 3, '묻지 않는 먹', '빈칸 벌판에 간다, 떠도는 먹귀을(를) 물리친다', '{"at": ["blank_field"], "tasks": [{"t": "travel", "r": ["blank_field"], "n": 1}, {"t": "win", "m": ["mk_field_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "벌판에서 먹귀를 부를 때마다 감찰이 서너 걸음 뒤에서 지켜보았다. 장부는 펼쳐 두기만 하고, 한동안 아무것도 적지 않았다."}, {"s": null, "t": "여덟째 먹귀가 흩어졌을 때 감찰이 내 손을 보자고 했다. 손등에 남은 것은 결말 날의 옅은 먹 자국 하나뿐이었다. 새로 번진 먹은 없었다."}, {"s": "q:sx_mke_dangyeong", "t": "먹이 묻지 않는구려. 매듭 안쪽이 비었다는 말이오."}, {"s": "q:sx_mke_dangyeong", "t": "진은 정해진 대로 돌았소. 매듭에 쌓인 먹도, 그 안의 기억도 거둬 갔소. 그런데 회수는 늦게 닿았고, 그사이 무슨 일이 있었는지는 어느 보고에도 없소."}, {"s": null, "t": "감찰은 그제야 장부에 한 줄을 적었다. 그러고는 벌판 저편, 나루 쪽 지붕들을 턱으로 가리켰다."}, {"s": "q:sx_mke_dangyeong", "t": "이제 사람들 차례요. 나루 사람들 이름이 그 사이 다시 흐려지지 않았는지 문패로 대 봐야겠소."}, {"s": "q:sx_mke_dangyeong", "t": "벌판에 버려진 지워진 문패 조각을 몇 개 주워 오시오. 지워진 것과 지금 것을 나란히 놓고 보겠소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_1', 4, '문패 대조', '빈칸 벌판에서 지워진 문패 조각을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["erased_plate"], "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "주워 온 문패 조각을 주막 평상에 늘어놓자, 감찰은 그 옆에 나루 문패를 하나씩 가져다 놓게 했다. 지워진 조각에는 획 몇 개만 남았고, 지금 문패에는 글자가 또렷했다."}, {"s": null, "t": "국밥집 노인 덕배가 제 집 문패를 떼어 들고 와 평상에 내려놓았다. 문패를 내려놓고도 한참 손을 떼지 못했다."}, {"s": "q:sx_mk_gukbap", "t": "내 이름이 덕배야. 덕배. 지난달엔 이걸 읽지도 못했어. 읽지도 못했다니까."}, {"s": null, "t": "다온이 공책을 펼쳐 들고 평상 둘레를 돌며 사람들 이름을 하나씩 읽었다. 이름이 불릴 때마다 누군가 「나요」 하고 손을 들었다."}, {"s": "q:mk_daon", "t": "묵창댁 아주머니. 덕배 할아버지. 노을 할아버지. 다 있어요. 하나도 안 빠졌어요."}, {"s": null, "t": "주막 처마 밑 기둥에는 월하가 기대 서 있었다. 엽전을 굴리다 말고 감찰 쪽으로 한마디를 던졌다."}, {"s": "q:mk_wolha", "t": "감찰 나리, 셈이 맞으면 그만 돌아가시죠. 서리님이 사흘째 밥을 안 먹어요."}, {"s": null, "t": "감찰은 월하 쪽을 보지도 않았다. 장부를 덮고 희수를 불렀다."}, {"s": "q:sx_mke_dangyeong", "t": "서리는 오늘 밤 진술서를 쓰시오. 무엇을 남기려고 획을 엇나가게 그었는지, 서리의 손으로."}, {"s": null, "t": "희수가 고개를 숙였다. 벼루를 들여다보다가 나를 보았다. 벼루 바닥이 또 말라 있었다."}, {"s": "q:mk_hisu", "t": "{이름} 조사원, 묵창 갈대 먹을 두 덩이만 부탁드려요. 진술서는 번지면 안 되니까요. 다녀오시면 주막에서 좀 쉬세요. 저 때문에 하루 종일 걸으셨어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_1', 5, '진술서', '빈칸 벌판에서 묵창 갈대 먹을(를) 모은다, 묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["mukchang_ink"], "r": ["blank_field"], "n": 2}, {"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "갈대 먹을 건네고 주막 객방에서 눈을 붙였다. 새벽에 깨어 보니 희수의 방에 아직 불이 켜져 있었다."}, {"s": null, "t": "아침이 되자 희수가 접은 종이 한 장을 들고 나왔다. 눈 밑이 검었는데 글씨는 반듯했다. 감찰은 진술서를 받아 소리 내어 읽었다."}, {"s": "q:sx_mke_dangyeong", "t": "「한 사람이 붙든 것들을 지우지 않으려고 마지막 획을 비껴 그었습니다. 진은 끝내 정해진 대로 돌았고, 저는 막지 못했습니다. 다만 획이 늦춘 그사이에, 그 사람이 매듭 안쪽에 묶여 있던 마지막 먹귀를 이름으로 불러 돌려보냈습니다.」"}, {"s": null, "t": "감찰은 끝까지 읽고 진술서를 접었다. 그러고는 희수가 아니라 나에게 물었다."}, {"s": "q:sx_mke_dangyeong", "t": "조사원, 그 회수 명부 원부는 아직 탑에 있소?"}, {"s": null, "t": "나는 탑 꼭대기 아래 뜰에서 마지막으로 보았다고 했다. 희수가 붓을 내려놓은 자리였다."}, {"s": "q:sx_mke_dangyeong", "t": "원부를 내 눈으로 보고 결정을 적겠소. 탑 안에 명부 갈피귀가 들끓는다던데, 길을 터 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_1', 6, '엇나간 획', '명부 탑에 간다, 명부 갈피귀을(를) 물리친다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "travel", "r": ["myeongbu_tower"], "n": 1}, {"t": "win", "m": ["mk_tower_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "갈피귀를 걷어 낸 서가 맨 아래에 회수 명부 원부가 끼워져 있었다. 감찰이 장을 넘기다 손을 멈췄다. 내 이름이 적힌 칸이었다. 마지막 획 하나가 옆으로 비껴 나가 있었다."}, {"s": null, "t": "그 칸 옆에는 희수의 글씨로 「돌려보냄 · 서율」이라고 적혀 있었다. 감찰은 그 획과 그 줄을 오래 보았다. 손끝을 혀에 대려다 그만두고, 원부를 덮었다."}, {"s": "q:sx_mke_dangyeong", "t": "서리 희수의 획은 일부러 그은 것이 맞소. 규정대로라면 파직이오."}, {"s": null, "t": "희수가 숨을 들이쉬었다. 감찰은 말을 끊지 않고 이어 갔다."}, {"s": "q:sx_mke_dangyeong", "t": "그러나 이 획이 늦춘 사이에 묶여 있던 이름 하나가 돌아갔소. 정청 기록이 백 년 동안 하지 못한 일이오. 무효가 된 줄이 남긴 것이 유효한 줄보다 많소."}, {"s": "q:sx_mke_dangyeong", "t": "결정을 적겠소. 서리 희수는 석 달 감봉. 그리고 묵창 나루 명부를 맡아 이곳에 머물 것."}, {"s": null, "t": "희수는 그 말이 벌인지 아닌지 한참 알아듣지 못한 얼굴이었다. 곁에 서 있던 다온이 먼저 알아들었다. 희수의 소매를 붙잡고 깡충 뛰었다."}, {"s": "q:mk_daon", "t": "서리님, 여기 있는 거예요? 계속요?"}, {"s": null, "t": "희수는 대답 대신 다온의 머리에 손을 얹었다. 감찰은 뒤돌아 계단을 내려가다 한 번 멈췄다."}, {"s": "q:sx_mke_dangyeong", "t": "다음에 정청에 올라올 것은 서식을 고치자는 청이겠지. 서리가 명부에 새로 그은 칸 말이오. 그건 내 소관이 아니오."}, {"s": null, "t": "감찰이 떠나고 나서야 희수가 나를 돌아보았다. 고개를 깊이 숙였다."}, {"s": "q:mk_hisu", "t": "고맙습니다, {이름} 조사원. 처음으로 틀렸는데, 틀린 덕에 남게 됐어요."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
