values ('mke_hisu_2', 'side', '외전·묵적록', '불러 주는 이 칸', '희수가 명부에 새로 그은 「불러 주는 이」 칸을 정청 서식으로 남기려고, 봉인고의 옛 서식을 찾는다.', 'mukchang_ferry', 45, '{mke_hisu_1}'::text[], null, 1332, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_hisu_2' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_2', 1, '서식에 없는 칸', '서식에 없는 칸', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "감찰이 다녀가고 보름이 지나 정청에서 공문이 내려왔다. 희수는 공문을 두 번 읽고, 세 번째로 읽다가 이마를 짚었다."}, {"s": "q:mk_hisu", "t": "「불러 주는 이」 칸은 서식에 없는 칸이라 받아 줄 수 없답니다. 백 년 동안 한 줄도 안 바뀐 서식이래요."}, {"s": "q:mk_hisu", "t": "서식을 고치려면 앞선 예가 있어야 해요. 예전 서식에 비슷한 칸이 있었다는 증거요."}, {"s": null, "t": "희수는 공문을 접어 장부 사이에 끼우고, 무언가 떠오른 듯 붓을 들었다."}, {"s": "q:mk_hisu", "t": "봉인고에 문수라는 서리가 있어요. 서고 맨 끝 칸을 맡은 아이예요. 옛 서식을 압수물 함에 넣어 둔다는 말을 들은 적이 있습니다."}, {"s": "q:mk_hisu", "t": "봉인고 함은 봉인 먹으로 다시 봉해야 열 수 있어요. 가시는 길에 봉인고에서 봉인 먹을 세 개쯤 거둬 문수에게 건네주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_2', 2, '맨 끝 칸의 서리', '봉인고에 간다, 봉인고에서 봉인 먹을(를) 모은다', '{"at": ["seal_vault"], "tasks": [{"t": "travel", "r": ["seal_vault"], "n": 1}, {"t": "gather", "items": ["sealing_ink"], "r": ["seal_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "봉인 먹을 들고 서고로 들어서자, 젊은 서리 하나가 함을 끌어안고 쪼그려 앉아 있었다. 나를 보더니 벌떡 일어났다."}, {"s": "q:dh_munsu", "t": "조사원님! 희수 언니 편지 받았어요. 묵창 나루 명부에 새 칸을 그었다면서요? 서고가 아주 시끄러웠어요."}, {"s": null, "t": "문수는 봉인 먹을 받아 들고 서고 안쪽으로 앞장섰다. 걸으면서도 말을 멈추지 않았다."}, {"s": "q:dh_munsu", "t": "옛 서식은 압수물 함에 들어 있어요. 고친 서식이 나오면 옛것은 압수물로 넣어 두거든요. 다시 쓰면 안 되니까요."}, {"s": "q:dh_munsu", "t": "그런데 저 안쪽 함들에서 손이 자꾸 기어 나와요. 제가 혼자 들어가면 목록을 다 뺏겨요."}, {"s": null, "t": "서가 끝 함 틈에서 하얀 손 하나가 기어 나와 문수의 치맛자락을 더듬었다. 문수가 비명을 지르며 내 뒤로 숨었다."}, {"s": "q:dh_munsu", "t": "저거요, 저거! 함에서 기어 나온 손들 좀 치워 주세요. 저는 봉인 먹을 꼭 쥐고 있을게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_2', 3, '긁어낸 칸', '함에서 기어 나온 손을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "손들이 함 속으로 물러나자 문수가 봉인 먹을 함 틈에 바르고 뚜껑을 열었다. 안에는 누렇게 바랜 서식 묶음이 들어 있었다."}, {"s": null, "t": "문수는 묶음을 한 장씩 넘기다 손을 멈췄다. 맨 아래 가장 오래된 서식에, 이름 칸 옆으로 칼로 긁어낸 자리가 하나 있었다."}, {"s": "q:dh_munsu", "t": "여기 칸이 하나 더 있었어요. 누가 긁어냈어요. 칸 이름도 같이요."}, {"s": "q:dh_munsu", "t": "긁은 자리는 먹이 아직 종이 속에 남아 있을 거예요. 이름 먹으로 비추면 떠오른다던데요. 희수 언니가 그런 걸 잘 알아요."}, {"s": null, "t": "문수는 서식을 봉투에 넣어 내게 건넸다. 그러고는 봉투 위에 제 이름을 또박또박 적었다."}, {"s": "q:dh_munsu", "t": "제가 빌려준 거예요. 꼭 돌려주셔야 해요. 서고에서 빠진 건 제가 다 외우고 있으니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_2', 4, '떠오른 글자', '이름 먹 부적을(를) 만든다, 묵창 나루에 간다, 이름 먹 부적을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["name_ink_charm"], "n": 2}, {"t": "travel", "r": ["mukchang_ferry"], "n": 1}], "give": {"name_ink_charm": 2}}'::jsonb, '[{"s": null, "t": "지어 온 이름 먹 부적을 건네자, 희수는 부적 한 장을 태워 그 재를 긁힌 자리 위에 고르게 펴 발랐다. 다른 한 장은 등불 앞에 세웠다."}, {"s": null, "t": "등불이 부적을 비추자 긁힌 자리에서 흐린 획이 하나씩 떠올랐다. 다온이 희수 어깨 너머로 목을 길게 뺐다."}, {"s": "q:mk_daon", "t": "「부르는 이」. 서리님, 이거 서리님이 그은 칸이랑 똑같아요."}, {"s": null, "t": "희수는 대답하지 않았다. 떠오른 글자를 손끝으로 따라 쓰다가, 손을 거두었다."}, {"s": "q:mk_hisu", "t": "백 년 전에는 있던 칸이에요. 누가 왜 긁었는지는 모르지만요."}, {"s": "q:mk_hisu", "t": "다만 서식 하나로는 앞선 예가 되지 않아요. 명부 탑에 쌓인 원부 가운데 이 칸을 실제로 채운 줄이 있어야 합니다."}, {"s": null, "t": "희수는 장부를 덮고 나를 보았다. 결말 날 이후로 처음, 부탁하는 눈이 아니라 함께 가자는 눈이었다."}, {"s": "q:mk_hisu", "t": "탑의 가장 오래된 원부는 맨 아래층 무너진 죽간 더미 속에 있어요. 하루로는 다 못 뒤집니다. 채비를 하고 원정으로 다녀와 주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_2', 5, '채워진 칸', '명부 탑에 원정을 다녀온다', '{"at": ["myeongbu_tower"], "tasks": [{"t": "expedition", "r": ["myeongbu_tower"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원정에서 끌어낸 죽간 더미 가운데 가장 오래된 묶음을 풀자, 희수가 숨을 멈췄다. 이름 줄 옆, 「부르는 이」 칸에 사람 이름이 적혀 있었다."}, {"s": null, "t": "한 줄이 아니었다. 이름마다 그 사람을 불러 준 이의 이름이 하나씩, 어떤 줄에는 셋씩 적혀 있었다."}, {"s": "q:mk_hisu", "t": "그때는 이름을 거둘 때 불러 준 사람도 함께 적었군요. 거둔 뒤에도 누가 그 이름을 기억하는지 알 수 있게요."}, {"s": "q:mk_hisu", "t": "이게 앞선 예예요. 이 묶음이면 청을 올릴 수 있어요."}, {"s": null, "t": "희수는 죽간을 비단에 싸 품에 넣었다. 그러고는 남은 더미를 아쉽다는 듯 돌아보았다."}, {"s": "q:mk_hisu", "t": "청에는 지금 나루의 줄도 함께 붙여야 해요. 원부와 같은 결의 죽간에 써서요. 명부 죽간을 몇 개만 더 거둬 주세요. 나루에 돌아가서는 좀 쉬시고요. 이번엔 저도 쉬겠습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_2', 6, '첫 줄', '명부 탑에서 명부 죽간을(를) 모은다, 묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["register_slip"], "r": ["myeongbu_tower"], "n": 3}, {"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "청을 올리고 열흘 뒤, 정청에서 편지 한 통이 왔다. 봉투에는 문수의 동글동글한 글씨가 적혀 있었다."}, {"s": null, "t": "희수는 편지를 읽고 나를 불렀다. 편지를 건네는 손이 이번에는 떨리지 않았다."}, {"s": "q:mk_hisu", "t": "「불러 주는 이」 칸을 묵창 나루 명부에 먼저 써 보기로 했답니다. 잘되면 다른 고을 명부에도 그을 거래요."}, {"s": "q:mk_hisu", "t": "문수가 끝에 한 줄을 붙였어요. 「빌려준 서식은 돌려받았습니다. 봉투에 제 이름도 그대로 있었고요.」"}, {"s": null, "t": "희수는 새 명부를 펼쳐 첫 줄에 다온의 이름을 적었다. 그 옆 「불러 주는 이」 칸에 붓을 대고, 나를 한 번 보았다."}, {"s": null, "t": "희수는 그 칸에 내 이름을 적고, 그 아래 제 이름을 적었다. 이번에는 두 이름 모두 마지막 획까지 똑바로 그었다."}, {"s": null, "t": "다온이 희수의 팔에 매달려 명부를 들여다보았다. 제 이름 옆에 두 이름이 나란히 있는 것을 보고 눈을 동그랗게 떴다."}, {"s": "q:mk_daon", "t": "서리님 이름도 들어갔어요? 그럼 저도 서리님 칸에 써 줄래요."}, {"s": null, "t": "희수는 붓을 씻다 말고 다온을 내려다보았다. 입꼬리가 아주 조금 올라가 있었다."}, {"s": "q:mk_hisu", "t": "……그건 네가 글을 다 배우고 나서."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mke_hisu_3', 'side', '외전·묵적록', '데운 국 한 그릇', '쉬지 않는 희수를 하루 쉬게 하려고 다온과 묵창댁이 꾀를 낸다. 처음 나루에 온 날 식어 버린 생선국 이야기다.', 'mukchang_ferry', 45, '{mke_hisu_2}'::text[], null, 1333, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_hisu_3' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_3', 1, '주막 뒤 작당', '주막 뒤 작당', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "주막 뒤뜰 장독대 뒤에서 다온과 주막 아낙 묵창댁이 머리를 맞대고 쪼그려 앉아 있었다. 묵창댁은 국자를 든 채였다. 나를 보자 둘이 동시에 손짓했다."}, {"s": "q:sx_mk_jumak", "t": "조사원, 이리 와 봐. 쉿, 크게 말하지 말고."}, {"s": null, "t": "다온이 손가락을 하나씩 꼽으며 속삭였다. 꼽을 때마다 볼이 부풀었다."}, {"s": "q:mk_daon", "t": "서리님이 또 밤새웠어요. 감찰 갔는데도요. 정청 편지 왔는데도요. 새 칸 생겼는데도요."}, {"s": null, "t": "묵창댁이 주막 안쪽을 흘끗 돌아보고 목소리를 더 낮췄다."}, {"s": "q:sx_mk_jumak", "t": "처음 나루 왔던 날 기억나? 내가 생선국 끓여 줬더니 그릇을 한쪽으로 밀어 두고 명부만 보더라고. 국이 다 식었어. 그 뒤로 한 번을 안 먹어."}, {"s": null, "t": "묵창댁은 국자로 제 손바닥을 탁 쳤다. 다온이 그 소리에 맞춰 고개를 끄덕였다."}, {"s": "q:sx_mk_jumak", "t": "오늘은 꼭 먹이고 재울 거야. 그날처럼 생선국을 끓이자고. 선창에서 물고기 두 마리만 낚아 와."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_3', 2, '다시 밀려난 그릇', '묵창 나루에서 낚시를 한다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "n": 2}]}'::jsonb, '[{"s": null, "t": "낚아 온 물고기로 묵창댁이 국을 끓였다. 다온이 두 손으로 그릇을 받쳐 들고, 주막 구석 희수의 서안까지 조심조심 걸어갔다."}, {"s": "q:mk_daon", "t": "서리님, 국이요."}, {"s": null, "t": "희수는 장부 위로 붓을 놀리며 고개를 끄덕였다. 눈은 여전히 글자에 머물러 있었다."}, {"s": "q:mk_hisu", "t": "고마워. 거기 두렴. 이것만 맞추고 먹을게."}, {"s": null, "t": "희수는 고개도 들지 않고 그릇을 한쪽으로 밀었다. 그날과 같은 자리, 같은 손짓이었다. 장독대 뒤에서 묵창댁이 국자로 이마를 짚었다."}, {"s": null, "t": "다온이 쪼르르 돌아와 내 소매를 잡아당겼다. 목소리는 작은데 눈은 진지했다."}, {"s": "q:mk_daon", "t": "{이름} 님, 작전 바꿔요. 서리님 명부 궤짝 위에 앉아 계세요. 안 비켜 주면 서리님도 일을 못 하잖아요."}, {"s": "q:mk_daon", "t": "그냥 앉아만 계시면 돼요. 푹 쉬시는 거예요. 서리님이 포기할 때까지요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_3', 3, '궤짝 위의 협상', '자율 활동을 끝까지 마친다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "idle", "n": 1, "k": "rest"}]}'::jsonb, '[{"s": null, "t": "명부 궤짝 위에 앉아 한나절을 쉬었다. 희수는 처음에는 옆에 서서 기다렸고, 다음에는 궤짝 모서리를 손가락으로 두드렸고, 끝내는 마주 앉았다."}, {"s": "q:mk_hisu", "t": "{이름} 조사원. 일어나 주세요."}, {"s": null, "t": "나는 국을 먹으면 일어나겠다고 했다. 희수가 눈을 가늘게 떴다. 그 뒤에서 다온이 손으로 입을 막고 웃음을 참았다."}, {"s": "q:mk_hisu", "t": "다온이 시켰군요."}, {"s": "q:mk_hisu", "t": "……좋아요. 대신 오늘 벌판 문패 대조는 해야 해요. 그것까지 끝나면 먹을게요."}, {"s": null, "t": "다온이 펄쩍 뛰며 내 쪽을 보았다."}, {"s": "q:mk_daon", "t": "그럼 {이름} 님이 대신 하면 되잖아요! 서리님은 여기 앉아서 국 데워지는 거 보고 있어요."}, {"s": null, "t": "희수는 반박하려다 다온의 얼굴을 보고 입을 다물었다. 장부를 펼쳐 대조할 문패 목록을 손가락으로 짚어 주었다."}, {"s": "q:mk_hisu", "t": "벌판 들머리 둔덕부터 사당 터까지예요. 세 군데 돌고 바로 돌아오세요. 바로요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_3', 4, '식어 버린 국', '빈칸 벌판을(를) 살핀다, 묵창 나루에 간다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "search", "r": ["blank_field"], "n": 3}, {"t": "travel", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "벌판을 돌고 돌아오니 주막 안에 이상한 정적이 감돌았다. 희수는 약속대로 서안 앞에 앉아 있었다. 그 앞의 국그릇은 이번에도 식어 있었다."}, {"s": null, "t": "묵창댁이 부뚜막 앞에서 국자를 휘휘 저으며 투덜거렸다. 아궁이 속이 휑했다."}, {"s": "q:sx_mk_jumak", "t": "장작이 다 떨어졌어! 데우려고 했더니 불이 안 붙어. 먹비 맞은 장작은 연기만 나고."}, {"s": "q:sx_mk_jumak", "t": "먹비 숲 흑단은 젖어도 불이 잘 붙어. 두어 개만 해 와. 그동안 저 서리님 국 한 술도 못 뜨게 지켜볼 테니까."}, {"s": null, "t": "희수가 서안 앞에서 작게 웃었다. 처음 듣는 소리였다. 다온이 그 소리에 놀라 희수를 쳐다보았다."}, {"s": "q:mk_hisu", "t": "{이름} 조사원, 이왕 가시는 김에 어죽도 두 그릇 지어 와 주세요. 국만 먹으면 다온이 또 배고프다고 할 테니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_3', 5, '데운 국', '먹비 숲에서 먹비 흑단을(를) 모은다, 어죽을(를) 만든다, 어죽을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["meokbi_ebony"], "r": ["meokbi_forest"], "n": 2}, {"t": "craft", "items": ["fish_porridge"], "n": 2}], "give": {"fish_porridge": 2}}'::jsonb, '[{"s": null, "t": "흑단을 아궁이에 넣자 불이 단번에 붙었다. 묵창댁이 국을 다시 데워 김이 오르는 그릇을 희수 앞에 놓았다. 내가 지어 온 어죽 두 그릇이 그 곁에 나란히 놓였다."}, {"s": null, "t": "그때 주막 문이 열리고 월하가 고개를 들이밀었다. 코를 킁킁거리며 들어와 앉을 자리부터 찾았다."}, {"s": "q:mk_wolha", "t": "냄새 좋네. 마침 배가 고팠는데."}, {"s": null, "t": "묵창댁이 국자를 치켜들고 월하 앞을 막아섰다."}, {"s": "q:sx_mk_jumak", "t": "너는 낄 데 안 낄 데도 모르냐!"}, {"s": null, "t": "월하는 국자 끝을 손가락으로 살짝 밀어내며 능청스럽게 웃었다."}, {"s": "q:mk_wolha", "t": "모르죠. 그래서 흑련회에 있잖아요."}, {"s": null, "t": "월하는 쫓겨나지 않고 다온 옆에 끼어 앉았다. 희수는 월하를 한 번 흘겨보았다. 그러고는 숟가락을 들었다."}, {"s": null, "t": "희수가 국을 한 술 떠 입에 넣었다. 그대로 한참 움직이지 않았다. 그러다 한 술 더 떴다."}, {"s": "q:mk_hisu", "t": "……따뜻하네요."}, {"s": null, "t": "다온이 숟가락을 든 채 희수 쪽으로 몸을 기울였다."}, {"s": "q:mk_daon", "t": "처음 먹어 보는 거예요? 서리님, 그날 거 진짜 하나도 안 먹었어요?"}, {"s": null, "t": "희수는 숟가락을 든 채 고개를 끄덕였다."}, {"s": "q:mk_hisu", "t": "응. 하나도."}, {"s": null, "t": "희수는 그릇을 끝까지 비웠다. 다온이 빈 그릇을 들어 올려 묵창댁에게 흔들어 보였다. 묵창댁은 국자를 머리 위로 치켜들었다."}, {"s": "q:sx_mk_jumak", "t": "됐다! 조사원, 오늘은 다들 여기서 자. 주막 객방 비워 놨어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_hisu_3', 6, '붓꽂이와 비녀', '묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "이튿날 아침, 희수는 해가 꽤 오른 뒤에야 객방에서 나왔다. 머리가 반쯤 풀려 있었다. 다온이 그 모습을 보고 웃음을 터뜨렸다."}, {"s": null, "t": "희수는 머리를 틀어 올리려다 말고, 품에서 작은 꾸러미 둘을 꺼내 내 앞에 내려놓았다."}, {"s": "q:mk_hisu", "t": "나루에 처음 올 때 정청에서 가져온 것들이에요. 이제 저는 여기 있을 거라 필요가 없어요."}, {"s": null, "t": "하나는 대나무를 엮어 만든 서리의 붓꽂이였다. 칸마다 먹이 배어 검게 길이 나 있었다. 다른 하나는 붓대를 깎아 만든 비녀였다. 끝에 먹이 한 점 묻어 있었다."}, {"s": "q:mk_hisu", "t": "붓꽂이는 {이름} 조사원 별채에 두세요. 비녀는…… 끝에 먹이 묻은 건 제가 그날 마지막 획을 비껴 그은 붓이라서예요. 버리지 못했어요."}, {"s": null, "t": "희수는 비녀를 내 손에 쥐여 주고 손을 놓았다. 그러고는 다시 머리를 틀어 올렸다. 이번에는 붓 대신 다온이 내민 나뭇가지를 꽂았다."}, {"s": "q:mk_hisu", "t": "오늘은 쉬는 날이에요. 명부는 내일 볼게요."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_mk_brushstand": 1, "of_acc_mk_hairpin": 1}, "title": "mk_keep_hisu"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mke_wolha_1', 'side', '외전·묵적록', '안 파는 항아리', '흑련회 거둠꾼 일곱째가 금 간 항아리를 들고 나루에 온다. 항아리 속 목소리가 부르는 이름은 「서하」였다.', 'mukchang_ferry', 45, '{mkq_5}'::text[], null, 1334, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_wolha_1' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_1', 1, '등에 진 보따리', '등에 진 보따리', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "나루 주막 문이 열리고 검은 도포를 입은 사내 하나가 들어섰다. 등에 보따리를 지고 있었다. 달 없는 저잣거리에서 「먹을 삽니다」 좌판을 지키던 흑련회 거둠꾼 일곱째였다."}, {"s": "q:sx_ilgopjjae", "t": "오랜만이구려, 조사원. 비를 맞지 말라고 했더니 결국 먹비 한가운데까지 오셨군."}, {"s": null, "t": "일곱째는 보따리를 평상에 내려놓았다. 보따리 안에서 항아리 하나가 떨리고 있었다. 옆구리에 엇갈려 붙인 정화 부적 두 장이 누렇게 바래 있었다."}, {"s": null, "t": "처마 밑에 기대 서 있던 월하가 그 항아리를 보았다. 손가락 사이에서 구르던 엽전이 멈췄다."}, {"s": "q:mk_wolha", "t": "……그걸 왜 가져왔어."}, {"s": null, "t": "일곱째는 어깨를 한 번 으쓱하고 보따리 매듭을 고쳐 맸다."}, {"s": "q:sx_ilgopjjae", "t": "값을 못 매기는 물건은 파는 게 아니오. 그러니 돌려보내는 게 장사꾼의 셈이지. 원래 있던 자리로."}, {"s": null, "t": "일곱째는 월하를 한 번 보고, 나에게로 고개를 돌렸다."}, {"s": "q:sx_ilgopjjae", "t": "그런데 거둔 기록을 적은 봉함 종이를 저잣거리 좌판에 두고 왔소. 얼굴 없는 손님 떼가 좌판을 에워싸서 꺼내 오지를 못했지. 그게 없으면 이 먹이 어디서 왔는지 증명할 수가 없소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_1', 2, '봉함 종이', '달 없는 저잣거리에 간다, 얼굴 없는 손님 떼을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "travel", "r": ["moonless_market"], "n": 1}, {"t": "win", "m": ["gw_market_2"], "n": 8}]}'::jsonb, '[{"s": null, "t": "손님 떼가 흩어진 좌판 밑에서 봉함 종이 한 장을 찾아냈다. 항아리 아가리에 붙어 있던 종이였다. 거둔 날짜와 곳, 거둔 이가 적혀 있었다."}, {"s": null, "t": "종이에는 「묵창 나루 빈칸 벌판 · 부르다 만 고개. 거둔 것: 아이 이름을 부르는 여인. 거둔 이: 월하. 첫 거둠.」이라고 적혀 있었다."}, {"s": null, "t": "나는 종이를 두 번 읽었다. 거둔 이의 칸에 적힌 호칭은 몇 번을 읽어도 같았다."}, {"s": null, "t": "저잣거리 끝에서 반요 노파 솥덕이 갓을 눌러쓴 채 지나가다 멈춰 섰다. 내가 든 종이를 보고 작게 중얼거렸다."}, {"s": "q:sx_sotdeok", "t": "그 항아리, 밤마다 같은 이름만 불렀어. 같은 이름만. 대답할 사람이 없어서 못 그쳐."}, {"s": null, "t": "노파는 그 말만 남기고 어둠 속으로 사라졌다. 항아리 옆구리의 부적은 이미 반쯤 떨어져 있었다. 나루까지 돌아가는 동안 버티지 못할 것 같았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_1', 3, '첫 거둠', '정화 부적을(를) 만든다, 묵창 나루에 간다, 정화 부적을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}, {"t": "travel", "r": ["mukchang_ferry"], "n": 1}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "새 정화 부적을 항아리에 덧대고 봉함 종이를 평상에 내려놓았다. 월하는 종이를 보지 않았다. 처마 밑에서 몸을 떼지도 않았다."}, {"s": null, "t": "다온이 종이를 집어 소리 내어 읽었다. 「거둔 이: 월하」에서 목소리가 멈췄다. 아이는 고개를 들어 월하를 보았다."}, {"s": "q:mk_daon", "t": "아저씨가 거둔 거예요?"}, {"s": null, "t": "월하는 한참 대답하지 않았다. 엽전을 한 번 튕겨 받아 쥐고 나서야 입을 열었다."}, {"s": "q:mk_wolha", "t": "거둠꾼이 되고 처음 거둔 먹이었어. 열댓 살 때였나. 회에서 처음 보낸 데가 하필 이 벌판이더라."}, {"s": "q:mk_wolha", "t": "고개에서 여자 먹귀 하나가 아이 이름을 부르고 있었지. 서하, 서하, 하고. 담장 너머로 날마다 듣던 목소리였어. 옆집 아주머니였지."}, {"s": null, "t": "월하는 거기서 말을 끊고 담장 쪽을 보았다. 다온의 집 담장이었다. 한참 뒤에야 엽전을 다시 굴리며 말을 이었다."}, {"s": "q:mk_wolha", "t": "회에서는 값이 꽤 나갈 거라고 했어. 이렇게 또렷하게 부르는 먹은 드물다고. 그런데 팔 수가 없더라. 들고 있으면 밤새 그 이름만 들려서."}, {"s": "q:mk_wolha", "t": "그래서 멀리 보냈어. 저잣거리로. 안 들리는 데로."}, {"s": null, "t": "희수가 다온 뒤에서 걸어 나왔다. 월하를 오래 보았다. 그날 사당에서 월하가 「서하」 위패를 보고 엽전을 멈췄던 일을 희수도 기억하는 얼굴이었다."}, {"s": "q:mk_hisu", "t": "……옆집이면, 서하의 어머니였군요. 그분 이름은 정청 명부에도 없어요. 서하보다 먼저 거둬졌으니까요."}, {"s": null, "t": "월하는 웃으려다 말았다. 대신 항아리를 들어 올려 내 앞에 놓았다."}, {"s": "q:mk_wolha", "t": "{이름}, 이거 사당에 데려다줘. 혼자 가면 벌판 먹귀들이 이 냄새를 맡고 다 몰려올 거야. 같이 가."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_1', 4, '대답할 사람', '빈칸 벌판에 간다, 떠도는 먹귀을(를) 물리친다', '{"at": ["blank_field"], "tasks": [{"t": "travel", "r": ["blank_field"], "n": 1}, {"t": "win", "m": ["mk_field_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "항아리 냄새를 맡고 몰려든 먹귀들을 풀어 보내며 사당까지 왔다. 다온이 「서하」·「서율」·「이랑」 위패 앞에 항아리를 내려놓았다. 항아리는 그래도 떨기를 멈추지 않았다."}, {"s": null, "t": "항아리 속 목소리가 또렷해졌다. 서하, 서하. 대답이 올 때까지 기다리듯 천천히 되풀이했다."}, {"s": "q:mk_daon", "t": "왜 안 멈춰요? 여기 서하 이름 있잖아요."}, {"s": null, "t": "월하가 항아리 앞에 쪼그려 앉아 봉함 종이를 다시 읽었다. 「부르다 만 고개」에서 손가락이 멈췄다."}, {"s": "q:mk_wolha", "t": "여기가 아니야. 이 사람은 고개에서 거둬졌어. 아이를 부르다 만 그 자리에서. 거기서 대답을 들어야 그칠 거야."}, {"s": "q:mk_wolha", "t": "그 고개가 벌판 어디쯤인지는 나도 이제 기억이 안 나. 흔적을 찾아 줘, {이름}."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_1', 5, '부르다 만 고개', '빈칸 벌판에서 실마리를 찾는다', '{"at": ["blank_field"], "tasks": [{"t": "clue", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "벌판 끝 낮은 고개에서 땅에 깊이 박힌 말뚝 하나를 찾았다. 말뚝에는 끊어진 명줄 한 가닥이 감겨 있었다. 월하가 그 말뚝을 보자 숨을 길게 내쉬었다."}, {"s": "q:mk_wolha", "t": "여기야. 여기서 거뒀어."}, {"s": null, "t": "다온이 「서하」 위패를 끌어안고 따라왔다. 아이는 말뚝 앞에 위패를 세우고, 항아리를 그 앞에 내려놓았다."}, {"s": null, "t": "항아리 속 목소리가 다시 불렀다. 서하. 다온이 위패를 두 손으로 붙잡고 숨을 한 번 들이쉬었다."}, {"s": "q:mk_daon", "t": "여기 있어요."}, {"s": null, "t": "목소리가 멈췄다. 항아리 옆구리의 금에서 먹이 한 줄기 흘러나와 말뚝 밑 흙으로 스며들었다. 먹이 다 빠져나가자 항아리는 가볍게 흔들리다 조용해졌다."}, {"s": null, "t": "월하는 오래 말뚝 앞에 서 있었다. 그러다 빈 항아리 앞에 쪼그려 앉아, 담장 너머로 말을 걸던 아이처럼 낮게 말했다."}, {"s": "q:mk_wolha", "t": "……아주머니. 형이 서하한테 먼저 갔어요. 이번엔 아주머니 차례예요."}, {"s": null, "t": "월하는 빈 항아리를 들어 품에 안았다. 다온이 그 소매를 붙잡았다."}, {"s": "q:mk_daon", "t": "아저씨, 울어요?"}, {"s": null, "t": "월하는 고개를 돌린 채 대답했다."}, {"s": "q:mk_wolha", "t": "먹비가 눈에 들어갔어."}, {"s": null, "t": "다온이 하늘을 올려다보고 다시 월하를 보았다."}, {"s": "q:mk_daon", "t": "오늘 먹비 안 와요."}, {"s": null, "t": "월하는 대답 대신 엽전을 한 번 튕겼다. 받지 못하고 떨어뜨렸다."}, {"s": "q:mk_wolha", "t": "돌아가자. 주막에서 한잔하고 자야겠어. {이름}도 와."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_1', 6, '빈 항아리', '묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "주막에서 하룻밤을 쉬고 나니, 일곱째가 보따리를 다시 꾸리고 있었다. 보따리는 아까보다 가벼웠다."}, {"s": "q:sx_ilgopjjae", "t": "빈 항아리는 놓고 가겠소. 값이 없는 물건이니."}, {"s": null, "t": "일곱째는 문간에서 월하를 돌아보았다. 웃음 없이, 손가락 하나로 제 가슴께를 툭 쳤다."}, {"s": "q:sx_ilgopjjae", "t": "첫 거둠을 돌려보낸 거둠꾼은 회에서 처음 보오. 회에서 뭐라 할지는 모르겠소."}, {"s": null, "t": "월하는 빈 항아리를 쓰다듬으며 어깨를 으쓱했다."}, {"s": "q:mk_wolha", "t": "손해라고 하겠지. 맞는 말이고."}, {"s": null, "t": "일곱째가 떠난 뒤, 월하는 빈 항아리를 주막 선반 맨 위에 올려놓았다. 그러고는 나를 보았다. 늘 하던 장사꾼 얼굴로 돌아가려다, 그러지 못했다."}, {"s": "q:mk_wolha", "t": "고마워, {이름}. 이건 값을 안 부를게. 처음이자 마지막이야."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mke_wolha_2', 'side', '외전·묵적록', '맡긴 이름', '월하가 흑련 장부고에 맡긴 제 이름 장의 「맡김 자리」를 옮길 수 있는지 묻는다. 본명은 끝까지 나오지 않는다.', 'mukchang_ferry', 45, '{mke_wolha_1}'::text[], null, 1335, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_wolha_2' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_2', 1, '불러 줄 사람이 생기면', '불러 줄 사람이 생기면', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "월하가 주막 선반의 빈 항아리를 내려다보며 엽전을 굴리고 있었다. 내가 들어서자 엽전을 손바닥에 탁 쥐었다."}, {"s": "q:mk_wolha", "t": "{이름}, 결말 날 꼬맹이가 물었잖아. 진짜 이름은 언제 찾느냐고. 내가 뭐라 했지?"}, {"s": null, "t": "나는 불러 줄 사람이 생기면, 이라고 했다고 대답했다. 월하가 피식 웃었다."}, {"s": "q:mk_wolha", "t": "그 말이 자꾸 걸려. 흑련회에 맡긴 이름은 맡긴 사람이 찾으러 가야 돌려줘. 근데 나는 찾으러 갈 생각이 없거든."}, {"s": "q:mk_wolha", "t": "대신 맡김 자리를 옮길 수는 있는지 알아보고 싶어. 내 이름을 쥐고 있을 사람을 바꾸는 거지. 흑련 장부고에 가면 장부지기가 알 거야."}, {"s": null, "t": "월하는 도포 자락을 털고 일어섰다. 문간에서 한 번 돌아보았다."}, {"s": "q:mk_wolha", "t": "같이 가 줘. 장부고는 서가가 미로라, 혼자 가면 길을 잃어. 들어가서 길부터 익혀 두자."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_2', 2, '호칭으로만', '흑련 장부고에 간다, 흑련 장부고을(를) 살핀다', '{"at": ["ledger_cellar"], "tasks": [{"t": "travel", "r": ["ledger_cellar"], "n": 1}, {"t": "search", "r": ["ledger_cellar"], "n": 3}]}'::jsonb, '[{"s": null, "t": "장부고 깊은 서가 앞에서 장부지기 소담이 촛불을 들고 기다리고 있었다. 월하를 보자 고개를 살짝 숙였다."}, {"s": "q:r220_sodam", "t": "오랜만입니다. 이름은 묻지 않겠습니다. 여기서는 호칭으로만 부르니까요."}, {"s": null, "t": "월하는 촛불 앞에서 손사래를 치고 서가 쪽을 턱으로 가리켰다."}, {"s": "q:mk_wolha", "t": "이름 말고 자리를 물으러 왔어. 맡김 자리를 옮길 수 있나?"}, {"s": null, "t": "소담은 대답하지 않고 서가 안쪽을 돌아보았다. 서가 틈에서 검은 손이 장부 한 권을 붙잡고 찢어발기고 있었다. 찢긴 장에서 이름 하나가 새어 나와 촛불을 흔들었다."}, {"s": "q:r220_sodam", "t": "그 이야기는 저 손들을 치운 다음에 하지요. 요즘 장부 찢는 손이 부쩍 늘었습니다. 회원들이 맡긴 이름이 자꾸 새어 나가요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_2', 3, '옮김의 예', '장부 찢는 손을(를) 물리친다', '{"at": ["ledger_cellar"], "tasks": [{"t": "win", "m": ["r220_ledger_4"], "n": 5}]}'::jsonb, '[{"s": null, "t": "손들이 물러난 서가에서 소담이 찢긴 장부를 하나씩 다시 꽂았다. 그러면서 월하의 물음에 답했다."}, {"s": "q:r220_sodam", "t": "맡김 자리를 옮긴 예가 아주 없지는 않습니다. 다만 백 년에 한두 번이라, 규칙을 적은 장이 어디 있는지 저도 정확히 모릅니다."}, {"s": "q:r220_sodam", "t": "옛 서가 어딘가에 「옮김」이라고 적힌 쪽지가 끼워져 있다고 들었습니다. 그걸 찾아 주시면 규칙대로 해 드리지요."}, {"s": null, "t": "월하는 서가를 올려다보며 혀를 찼다. 서가는 천장 너머 어둠 속까지 이어져 있었다."}, {"s": "q:mk_wolha", "t": "백 년 묵은 쪽지를 이 안에서 찾으라고. 흑련회 장사는 늘 이렇다니까."}, {"s": "q:mk_wolha", "t": "{이름}, 눈 밝은 쪽이 찾아. 나는 촛불이나 들게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_2', 4, '금고 앞의 거인', '흑련 장부고에서 실마리를 찾는다', '{"at": ["ledger_cellar"], "tasks": [{"t": "clue", "r": ["ledger_cellar"], "n": 1}]}'::jsonb, '[{"s": null, "t": "서가 맨 아래 칸 장부 사이에서 「옮김」이라고 적힌 쪽지 한 장을 찾아냈다. 소담이 쪽지를 받아 촛불에 비추고 소리 내어 읽었다."}, {"s": "q:r220_sodam", "t": "「맡긴 이가 새 맡을 이를 정하고, 장부지기가 원장의 맡김 칸을 봉하여 새 맡을 이에게 건넨다. 이름은 펼치지 않는다.」"}, {"s": "q:r220_sodam", "t": "원장은 장부고 맨 밑 금고에 있습니다. 그런데 금고 앞에 먹 거인이 버티고 있어요. 장부를 쓰고 남은 먹이 쌓여 사람 꼴이 된 놈이지요."}, {"s": null, "t": "월하가 금고 쪽 어둠을 보았다. 거기서 무언가 무거운 것이 천천히 몸을 일으키는 소리가 났다."}, {"s": "q:mk_wolha", "t": "장부를 쓰고 남은 먹이라. 내 이름 쓴 먹도 저 안에 있겠네."}, {"s": "q:mk_wolha", "t": "두 번은 쓰러뜨려야 비켜 줄 거야. 저런 건 한 번 쓰러져도 다시 엉겨 붙거든."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_2', 5, '펼치지 않는 장', '장부고의 먹 거인을(를) 물리친다', '{"at": ["ledger_cellar"], "tasks": [{"t": "win", "m": ["r220_ledger_5"], "n": 2}]}'::jsonb, '[{"s": null, "t": "먹 거인이 두 번째로 무너지자 금고 문이 드러났다. 소담이 열쇠를 돌려 원장 한 권을 꺼냈다. 월하의 장을 찾아 펼치되, 이름 칸은 손바닥으로 덮었다."}, {"s": "q:r220_sodam", "t": "보시겠습니까. 맡긴 사람은 볼 수 있습니다."}, {"s": null, "t": "월하는 원장 가장자리만 내려다보았다. 손바닥 너머를 보지 않았다."}, {"s": "q:mk_wolha", "t": "안 볼래. 보면 도로 찾아가고 싶어질 것 같아서."}, {"s": null, "t": "소담은 고개를 끄덕이고 맡김 칸을 오려 접었다. 접은 종이를 먹으로 봉해 월하에게 건넸다."}, {"s": "q:r220_sodam", "t": "이 봉함 쪽지를 새로 맡을 사람에게 건네시면 됩니다. 받는 사람도 펼쳐서는 안 됩니다. 불러 줄 때만, 쪽지를 쥐고 부르면 됩니다."}, {"s": null, "t": "월하는 쪽지를 받아 손바닥에 올려놓고 한참 내려다보았다."}, {"s": "q:mk_wolha", "t": "누구한테 줄지는 아직 안 정했어."}, {"s": null, "t": "월하는 쪽지를 품에 넣고 나를 돌아보았다. 웃는 눈인데 이번에는 정말로 웃고 있었다."}, {"s": "q:mk_wolha", "t": "돌아가자. 나루 주막 객방이 그립네. 흑련회 장부고는 너무 춥단 말이야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_2', 6, '아직', '묵창 나루에 간다, 묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "travel", "r": ["mukchang_ferry"], "n": 1}, {"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "주막에서 하룻밤을 쉬고 나오니, 다온이 평상에 앉아 공책을 쓰고 있었다. 월하를 보자 붓을 놓고 달려왔다."}, {"s": "q:mk_daon", "t": "아저씨, 장부고 다녀왔어요? 진짜 이름 찾았어요?"}, {"s": null, "t": "월하는 엽전을 굴리며 짧게 대답했다."}, {"s": "q:mk_wolha", "t": "아직."}, {"s": null, "t": "다온은 고개를 갸웃하다가 손뼉을 쳤다."}, {"s": "q:mk_daon", "t": "아직이면 언젠가는 찾는 거네요."}, {"s": null, "t": "월하는 대답하지 않았다. 품 안의 봉함 쪽지를 손으로 한 번 눌러 보았을 뿐이었다. 다온은 그 손을 빤히 보다가 공책으로 돌아갔다."}, {"s": null, "t": "월하가 내 옆에 서서 낮게 말했다."}, {"s": "q:mk_wolha", "t": "{이름}, 꼬맹이한테는 아직 말하지 마. 줄 사람은 정했는데, 줄 날을 못 정했어."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mke_wolha_3', 'side', '외전·묵적록', '공짜 손님', '월하가 주막 한쪽에 좌판을 열어, 맡아 둔 기억을 유족에게 값 없이 돌려준다. 흑련회에서 셈꾼이 온다.', 'mukchang_ferry', 45, '{mke_wolha_2}'::text[], null, 1336, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mke_wolha_3' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_3', 1, '「먹을 돌려드립니다」', '「먹을 돌려드립니다」', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "주막 한쪽 구석에 좌판이 하나 차려져 있었다. 기둥에 걸린 나무패에는 「먹을 돌려드립니다」라고 적혀 있었다. 그 앞에서 월하가 팔짱을 끼고 앉아 있었다."}, {"s": "q:mk_wolha", "t": "왔어, {이름}? 개업 첫날이야. 손님은 아직 없지만."}, {"s": null, "t": "나는 무엇을 돌려주는 좌판이냐고 물었다. 월하는 턱으로 좌판 뒤의 상자들을 가리켰다. 상자마다 「묵창」이라는 꼬리표가 붙어 있었다."}, {"s": "q:mk_wolha", "t": "내가 이 나루에서 거둔 먹들이야. 흑련회에 넘기지 않고 탑에 숨겨 둔 거. 이제 유족한테 돌려주려고. 공짜로."}, {"s": "q:mk_wolha", "t": "그런데 어느 먹이 누구 집 건지 적은 꼬리표가 탑에 두고 온 죽간에 있어. 명부 죽간 두어 개만 가져와 줘. 꼬리표를 맞춰 봐야 하니까."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_3', 2, '첫 손님과 셈꾼', '명부 탑에서 명부 죽간을(를) 모은다, 묵창 나루에 간다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["register_slip"], "r": ["myeongbu_tower"], "n": 2}, {"t": "travel", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "죽간 꼬리표를 맞추자 첫 손님이 정해졌다. 국밥집 노인 덕배였다. 월하가 작은 먹 단지 하나를 덕배 앞에 내려놓고 뚜껑을 열었다."}, {"s": null, "t": "단지에서 젊은 사내의 웃음소리가 흘러나왔다. 크고, 숨이 넘어갈 듯한 웃음이었다. 덕배가 단지를 두 손으로 감싸 쥐었다."}, {"s": "q:sx_mk_gukbap", "t": "우리 아들이야. 우리 아들. 웃음소리가 컸어."}, {"s": null, "t": "덕배는 품에서 엽전 꾸러미를 꺼내 내밀었다. 월하는 손사래를 쳤다. 그때 주막 문이 벌컥 열리고 주판을 낀 젊은 사내 하나가 들어섰다."}, {"s": "q:sx_mke_ssangyeop", "t": "흑련회 셈꾼 쌍엽이오. 월하 거둠꾼이 회의 물건을 공짜로 나눠 준다는 소문이 들어서 왔소."}, {"s": "q:sx_mke_ssangyeop", "t": "먹 단지 하나에 쌀 두 섬. 오늘 하나 나갔으니 두 섬 손해요. 손해는 메워야 하오. 셈이 그렇소."}, {"s": null, "t": "쌍엽은 주판알을 튕기고 월하를 노려보았다. 월하는 귀찮다는 듯 머리를 긁었다."}, {"s": "q:mk_wolha", "t": "그럼 회가 좋아하는 물건으로 메우지. {이름}, 벌판에 먹귀 응어리가 쌓여 있어. 원정으로 넉넉히 거둬서 셋만 이 사람한테 넘겨 줘."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_3', 3, '맞지 않는 셈', '빈칸 벌판에 원정을 다녀온다, 먹귀 응어리을(를) 넘긴다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "expedition", "r": ["blank_field"], "n": 1}], "give": {"meokgwi_lump": 3}}'::jsonb, '[{"s": null, "t": "원정에서 거둔 먹귀 응어리 셋을 쌍엽 앞에 내려놓았다. 쌍엽은 응어리를 하나씩 들어 무게를 가늠하고 주판을 튕겼다."}, {"s": "q:sx_mke_ssangyeop", "t": "응어리 셋이면 쌀 한 섬 반. 아직 반 섬이 비오. 그리고 저 상자들이 다 나가면 손해가 쉰 섬이 넘소."}, {"s": null, "t": "그때 주막 안쪽에서 희수가 명부를 끼고 걸어 나왔다. 쌍엽 앞에 명부를 펼쳐 놓았다."}, {"s": "q:mk_hisu", "t": "정청 명부에는 「돌려줌」이라는 줄이 있어요. 거둔 기억을 유족에게 돌려준 일은 정청이 증서로 남깁니다. 증서 한 장은 정청이 그 집안에 진 빚을 한 줄 덜어 줘요."}, {"s": "q:mk_hisu", "t": "그 빚을 흑련회 앞으로 돌려 적어 드리지요. 흑련회가 정청에 받을 셈이 생기는 거예요. 쌀 두 섬보다는 쓸모가 있을걸요."}, {"s": null, "t": "쌍엽은 주판을 멈추고 희수를 빤히 보았다. 월하는 그보다 더 놀란 얼굴로 희수를 보았다. 희수가 처음으로 월하 편을 든 날이었다."}, {"s": "q:mk_wolha", "t": "……서리님, 지금 저 도와주는 겁니까?"}, {"s": null, "t": "희수는 월하 쪽을 보지 않고 명부의 줄을 손가락으로 짚었다."}, {"s": "q:mk_hisu", "t": "정청 셈을 맞추는 겁니다. {이름} 조사원, 증서에 쓸 빈칸 한지를 세 장만 구해 주세요. 정청 증서는 빈 칸이 하나 있는 종이에 써야 해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_3', 4, '증서 석 장', '빈칸 벌판에서 빈칸 한지을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["blank_hanji"], "r": ["blank_field"], "n": 3}]}'::jsonb, '[{"s": null, "t": "빈칸 한지에 희수가 증서 석 장을 썼다. 쌍엽은 증서를 받아 한참 들여다보고, 주판을 두 번 튕기고, 마지막에 한숨을 쉬었다."}, {"s": "q:sx_mke_ssangyeop", "t": "셈이 맞소. 맞아서 기분이 나쁘오. 회에는 그대로 올리겠소."}, {"s": null, "t": "쌍엽이 떠나자 주막 문밖에 사람들이 줄을 서 있었다. 소문을 들은 나루 사람들이었다. 모두 이름이 흐려진 식구 하나씩을 가슴에 품고 온 얼굴이었다."}, {"s": null, "t": "월하는 줄을 보고 머리를 감싸 쥐었다. 상자는 서른 개가 넘었고 꼬리표는 반쯤 지워져 있었다."}, {"s": "q:mk_wolha", "t": "이걸 다 맞추려면 오늘 밤을 새워야겠네. {이름}, 같이 맞춰 줘. 조사원 일 아니냐, 이런 게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_3', 5, '맡김 자리', '자율 활동을 끝까지 마친다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "idle", "n": 1, "k": "research"}]}'::jsonb, '[{"s": null, "t": "밤을 새워 꼬리표를 맞추고 상자를 하나씩 돌려주었다. 새벽녘 마지막 손님이 단지를 안고 돌아가자, 좌판 뒤에는 빈 상자만 남았다."}, {"s": null, "t": "월하는 빈 상자 위에 털썩 걸터앉았다. 다온이 졸린 눈으로 그 옆에 다가가 앉았다. 밤새 줄 선 사람들 이름을 공책에 받아 적던 아이였다."}, {"s": "q:mk_daon", "t": "아저씨, 다 돌려줬어요? 하나도 안 남았어요?"}, {"s": null, "t": "월하는 빈 상자를 손바닥으로 두드리며 하품을 했다."}, {"s": "q:mk_wolha", "t": "하나도. 장사 망했다."}, {"s": null, "t": "월하는 품에서 먹으로 봉한 쪽지 하나를 꺼냈다. 흑련 장부고에서 받아 온 맡김 쪽지였다. 쪽지를 다온 앞에 내밀었다."}, {"s": "q:mk_wolha", "t": "꼬맹아, 이거 맡아 줘. 펼쳐 보면 안 돼. 그냥 가지고 있다가, 내가 한참 안 보이면 이거 쥐고 한 번 불러 줘."}, {"s": null, "t": "다온이 쪽지를 받지 않고 월하의 얼굴부터 보았다."}, {"s": "q:mk_daon", "t": "아저씨 이름이에요?"}, {"s": null, "t": "월하는 쪽지를 아이 손에 쥐여 주며 고개를 끄덕였다."}, {"s": "q:mk_wolha", "t": "응. 불러 줄 사람이 생기면 찾는다고 했잖아. 생겼으니까."}, {"s": null, "t": "다온은 쪽지를 두 손으로 받아 들었다. 펼쳐 보지 않고 공책 맨 뒷장 사이에 끼웠다. 그러고는 공책을 가슴에 꼭 끌어안았다."}, {"s": "q:mk_daon", "t": "안 펼쳐 볼게요. 대신 안 잊어요."}, {"s": null, "t": "월하는 웃었다. 이번에는 정말로 웃었다. 그러고는 상자 위에 드러누워 눈을 감았다."}, {"s": "q:mk_wolha", "t": "{이름}, 나 좀 자게 둬. 너도 좀 쉬어. 밤새웠잖아."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mke_wolha_3', 6, '엽전 발', '묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "한숨 자고 나오니 좌판 기둥의 나무패가 바뀌어 있었다. 새 나무패에는 「먹을 돌려드립니다. 값은 받지 않음. 단, 이름은 불러 주고 갈 것.」이라고 적혀 있었다."}, {"s": null, "t": "월하는 좌판 앞에서 엽전 꿰미를 풀어 무언가를 엮고 있었다. 엽전마다 연꽃 매듭을 지어 길게 늘어뜨린 발이었다."}, {"s": "q:mk_wolha", "t": "거둠꾼 노릇 하면서 받은 엽전들이야. 이제 셈할 일이 없으니 쓸 데가 없어서. 네 별채 문간에 걸어 둬, {이름}. 바람 불면 소리가 꽤 좋아."}, {"s": null, "t": "월하는 발을 내게 건네고, 도포 자락에 달려 있던 연꽃 매듭 하나를 풀어 함께 내밀었다. 매듭 끝에 엽전 한 닢이 매달린 노리개였다."}, {"s": "q:mk_wolha", "t": "이건 흑련회 표식이야. 회원이 아닌 사람이 차고 다니면 다들 뭐라 할걸. 그래서 주는 거야. 너한테는 값을 안 부른다는 표시로."}, {"s": null, "t": "나는 노리개를 받아 허리에 찼다. 월하는 그걸 보고 엽전을 한 번 튕겼다. 이번에는 떨어뜨리지 않고 받아 쥐었다."}, {"s": "q:mk_wolha", "t": "잘 어울리네. 값으로 치면 쌀 두 섬쯤."}, {"s": null, "t": "평상에서 공책을 쓰던 다온이 붓을 든 채 벌떡 일어났다."}, {"s": "q:mk_daon", "t": "아저씨, 값 안 부른다면서요!"}, {"s": null, "t": "월하는 엽전을 품에 넣으며 시치미를 뗐다."}, {"s": "q:mk_wolha", "t": "부른 게 아니라 쳐 본 거야."}]'::jsonb, '{"gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_mk_coinblind": 1, "of_acc_mk_lotus": 1}, "title": "mk_keep_wolha"}'::jsonb)
