values ('mks_n_dragon', 'side', '낚시·아홉 칸 뜰', '우물 밑의 눈', '이름으로 본다는 우물 밑 눈먼 용에게 먹줄꾼의 질문을 전한다.', 'nine_court', 45, '{mkq_4}'::text[], null, 1337, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_n_dragon' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_dragon', 1, '우물가의 먹줄꾼', '우물가의 먹줄꾼', '{"at": ["nine_court"]}'::jsonb, '[{"s": null, "t": "아홉 칸 뜰 끝, 바닥이 보이지 않는 우물가에 늙은 서리 하나가 앉아 있었다. 손목에는 먹줄을 감은 줄자가 걸려 있었다."}, {"s": null, "t": "서리는 우물 안으로 먹줄을 조금씩 풀어 내리고 있었다. 줄이 다 풀려도 아무것에도 닿지 않았는지, 다시 감아올렸다."}, {"s": "q:sx_mk_muhyeon", "t": "조사원이구려. 나는 정청에서 봉인진 먹줄을 치는 사람이오. 먹줄꾼 무현이라 하오."}, {"s": "q:sx_mk_muhyeon", "t": "이 뜰의 진을 그릴 때 내가 먹줄을 쳤소. 아홉 칸 모두 내 손으로 그었지. 그런데 이 우물만은 진 안에 넣을지 밖에 둘지 아직 정하지 못했소."}, {"s": null, "t": "나는 왜 정하지 못했느냐고 물었다. 무현은 줄자를 손에 감으며 우물을 내려다보았다."}, {"s": "q:sx_mk_muhyeon", "t": "이 우물 밑에 눈먼 용이 산다는 말이 있소. 용은 눈 대신 이름으로 본다지. 진 안에 든 것이 무슨 이름인지, 그 용이 제일 잘 안다는 거요."}, {"s": "q:sx_mk_muhyeon", "t": "용을 한 번 불러 올려 물어보고 싶소. 그런데 용은 깊은 물고기 냄새에만 올라온다 하오. 수궁 복어나 우물 장님고기, 청동 메기 같은 것."}, {"s": "q:sx_mk_muhyeon", "t": "이 뜰에는 깊은 물고기가 귀하오. 용잠 수궁까지 가서 두 번만 낚아 오시오. 거기 깊은 회랑의 물고기면 용이 마다하지 않을 거요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_dragon', 2, '진의 첫 획', '용잠 수궁에서 낚시를 한다', '{"at": ["nine_court"], "tasks": [{"t": "fish", "r": ["sunken_palace"], "n": 2}]}'::jsonb, '[{"s": null, "t": "용잠 수궁에서 낚은 깊은 물고기를 들고 뜰로 돌아오자, 무현은 바구니를 들여다보고 고개를 끄덕였다."}, {"s": "q:sx_mk_muhyeon", "t": "잘 낚았소. 미끼는 가방에 넣어 두었다가, 낚시할 때 낚시 칸에서 골라 거시오."}, {"s": "q:sx_mk_muhyeon", "t": "용을 부르기 전에 하나 확인할 것이 있소. 진의 칸마다 내가 그은 먹줄이 아직 제자리에 있는지 봐 주시오. 줄이 하나라도 끊겼으면 용이 진 밖으로 나올지도 모르오."}, {"s": null, "t": "무현은 줄자를 풀어 뜰 바닥의 먹줄을 하나씩 가리켰다. 줄은 길고 곧았다. 몇 군데는 먹이 마르지 않아 번들거렸다."}, {"s": "q:sx_mk_muhyeon", "t": "뜰을 두 번만 돌며 살펴 주시오. 나는 우물가에서 줄을 지키겠소."}]'::jsonb, '{"xp": 2880}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_dragon', 3, '맑은 한낮', '아홉 칸 뜰을(를) 살핀다', '{"at": ["nine_court"], "tasks": [{"t": "search", "r": ["nine_court"], "n": 2}]}'::jsonb, '[{"s": null, "t": "뜰을 돌고 오니 먹줄은 모두 제자리에 있었다. 한 군데, 둘째 칸 모서리만 먹이 조금 번져 있었다고 알렸다. 무현은 그리로 가서 손가락으로 번진 먹을 바로잡았다."}, {"s": "q:sx_mk_muhyeon", "t": "고맙소. 이제 용을 부를 차례요."}, {"s": "q:sx_mk_muhyeon", "t": "용은 한낮에 올라오오. 하늘이 맑아 해가 우물 바닥까지 비치는 날, 청명한 한낮이어야 하오. 햇빛이 닿아야 용이 위를 올려다보거든."}, {"s": null, "t": "무현은 우물가에 다시 앉아 줄자를 손목에 감았다."}, {"s": "q:sx_mk_muhyeon", "t": "청명한 한낮에 아홉째 칸 우물에서 눈먼 용을 낚아 주시오. 낚으면 내가 묻고 싶은 것을 묻겠소."}]'::jsonb, '{"xp": 2880}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_dragon', 4, '이름으로 보는 눈', '아홉 칸 뜰에서 눈먼 용을(를) 낚는다', '{"at": ["nine_court"], "tasks": [{"t": "fish", "r": ["nine_court"], "f": ["blind_dragon"], "n": 1}]}'::jsonb, '[{"s": null, "t": "햇빛이 우물 바닥까지 닿은 한낮, 줄 끝에 무거운 것이 걸렸다. 끌어올린 것은 비늘이 돌처럼 굳은 용이었다. 눈이 있어야 할 자리가 하얗게 감겨 있었다."}, {"s": null, "t": "용은 물 밖에서도 몸부림치지 않았다. 대신 고개를 천천히 돌려 나를 향했다. 감긴 눈 너머에서 무언가가 나를 읽는 것 같았다."}, {"s": null, "t": "무현이 무릎을 꿇고 용 앞에 앉았다. 그리고 낮은 목소리로 물었다."}, {"s": "q:sx_mk_muhyeon", "t": "이 진 안에 든 것이 무슨 이름이오."}, {"s": null, "t": "용은 대답하지 않았다. 다만 고개를 돌려 가운데 칸을 향했다. 가운데 칸의 먹은 아직 마르지 않았다."}, {"s": null, "t": "무현은 오래 그 칸을 보았다. 그러다 줄자를 손목에서 풀었다."}, {"s": "q:sx_mk_muhyeon", "t": "……그렇구려. 진이 지키는 것은 먹귀가 아니었소. 아직 먹이 다 마르지 않은, 누군가의 이름이었소."}, {"s": "q:sx_mk_muhyeon", "t": "이 용으로 용안 정수를 하나 지어 주시오. 이름으로 보는 눈을 빌려, 내가 진을 다시 보아야겠소."}]'::jsonb, '{"xp": 2880}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_n_dragon', 5, '우물은 진 밖에', '용안 정수을(를) 만든다, 용안 정수을(를) 넘긴다', '{"at": ["nine_court"], "tasks": [{"t": "craft", "items": ["dragon_eye_essence"], "n": 1}], "give": {"dragon_eye_essence": 1}}'::jsonb, '[{"s": null, "t": "용안 정수를 건네자, 무현은 그것을 눈에 한 방울 떨어뜨렸다. 그러고는 뜰 한가운데 서서 아홉 칸을 천천히 둘러보았다."}, {"s": "q:sx_mk_muhyeon", "t": "진이 다르게 보이오. 칸마다 누가 서 있었는지 보이는 것 같소."}, {"s": null, "t": "무현은 우물로 돌아와 먹줄을 감아 넣었다. 우물 둘레에는 줄을 치지 않았다."}, {"s": "q:sx_mk_muhyeon", "t": "우물은 진 밖에 두겠소. 이름을 보는 눈은 가둘 것이 아니오. 누가 돌아오는지 지켜봐 줄 눈이 하나쯤은 있어야지."}, {"s": null, "t": "우물 밑에서 물이 한 번 크게 일렁였다. 무현은 물결이 잦아들 때까지 우물가에 앉아 있었다."}]'::jsonb, '{"xp": 2880, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
