values ('mks_stone_turtle', 'side', '전투·아홉 칸 뜰', '뜰 가장자리의 돌거북', '진의 칸마다 엎드린 돌거북 하나가 어귀까지 기어 나왔다. 등의 글자가 반쯤 지워져 제 칸을 찾지 못한다.', 'nine_court', 45, '{mkq_4}'::text[], null, 1338, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mks_stone_turtle' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_stone_turtle', 1, '어귀의 작은 돌거북', '어귀의 작은 돌거북', '{"at": ["nine_court"]}'::jsonb, '[{"s": null, "t": "아홉 칸 뜰 어귀 돌문 아래에 손바닥만 한 돌거북 하나가 엎드려 있었다. 등껍질에 새긴 글자가 반쯤 지워져 있었다. 돌거북은 목을 쭉 빼고 뜰 안쪽을 바라보다가, 한 걸음 기었다가, 다시 멈췄다."}, {"s": null, "t": "허리춤에 먹통을 찬 소년이 쪼그려 앉아 그 돌거북을 들여다보고 있었다. 나를 보더니 반갑게 손을 흔들었다."}, {"s": "q:sx_mk_dano", "t": "조사원님! 마침 잘 오셨어요. 저는 단오예요. 정청에서 이 뜰 바닥에 먹줄 고치는 일을 해요."}, {"s": "q:sx_mk_dano", "t": "얘 좀 보세요. 진의 칸마다 돌거북이 한 마리씩 엎드려 칸을 지키거든요. 그런데 얘만 어귀까지 나와 버렸어요. 등에 적힌 칸 번호가 지워져서 제자리를 못 찾나 봐요."}, {"s": null, "t": "돌거북이 단오의 손가락에 머리를 비볐다. 돌로 된 머리가 차갑고 매끄러웠다."}, {"s": "q:sx_mk_dano", "t": "등에 칸 번호를 다시 써 주면 될 것 같은데, 그냥 먹으로 쓰면 이 뜰에선 금방 지워져요."}, {"s": "q:sx_mk_dano", "t": "이름 먹 부적 하나만 지어 주세요. 부적 먹으로 쓰면 안 지워진대요. 얘가 제 칸 번호를 알아보게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_stone_turtle', 2, '등에 쓴 번호', '이름 먹 부적을(를) 만든다, 이름 먹 부적을(를) 넘긴다', '{"at": ["nine_court"], "tasks": [{"t": "craft", "items": ["name_ink_charm"], "n": 1}], "give": {"name_ink_charm": 1}}'::jsonb, '[{"s": null, "t": "지어 온 이름 먹 부적을 건네자 단오는 부적을 물에 개어 붓에 묻혔다. 돌거북 등의 지워진 글자를 한 획씩 따라 덧썼다. 「일곱째」."}, {"s": "q:sx_mk_dano", "t": "일곱째 칸이었구나! 이제 알겠지?"}, {"s": null, "t": "돌거북은 등에 새로 쓴 글자를 보려는 듯 목을 뒤로 쭉 뺐다. 등이 보일 리 없었다. 돌거북은 한참을 끙끙대다가 포기하고, 대신 뜰 안쪽으로 똑바로 기기 시작했다."}, {"s": "q:sx_mk_dano", "t": "갔어요! 따라가요, 조사원님!"}, {"s": null, "t": "돌거북은 아주 느렸다. 한 걸음 가고 쉬고, 또 한 걸음 가고 쉬었다. 그러다 진의 갈림길에서 고개를 갸웃하더니 엉뚱한 쪽으로 방향을 틀었다."}, {"s": "q:sx_mk_dano", "t": "아, 저기가 아닌데. 일곱째 칸은 진 바깥 금을 따라 돌아야 나와요. 얘가 헤매면 길을 찾아 주세요. 뜰을 두어 번 살펴보면 일곱째 칸 가는 길이 보일 거예요."}]'::jsonb, '{"xp": 3840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_stone_turtle', 3, '칸을 차지한 덩치들', '아홉 칸 뜰을(를) 살핀다', '{"at": ["nine_court"], "tasks": [{"t": "search", "r": ["nine_court"], "n": 2}]}'::jsonb, '[{"s": null, "t": "진 바깥 금을 따라 돌아 일곱째 칸 앞에 닿았다. 작은 돌거북은 칸 앞에서 우뚝 멈춰 섰다. 칸 안에는 커다란 돌거북 여럿이 등을 맞대고 엎드려 있었다."}, {"s": null, "t": "커다란 돌거북들의 등에도 글자가 반쯤 지워져 있었다. 저마다 제 칸을 잃고 아무 칸에나 눌러앉은 것 같았다. 작은 돌거북이 다가가자 덩치들이 목을 내밀어 쉿쉿 소리를 냈다."}, {"s": "q:sx_mk_dano", "t": "쟤들이 남의 칸을 차지했어요. 칸을 잃은 돌거북은 요기가 들어서 사납대요."}, {"s": null, "t": "작은 돌거북은 내 발등 뒤로 쏙 숨어들었다. 등껍질이 내 발목에 닿았다."}, {"s": "q:sx_mk_dano", "t": "쟤들은 정청에서 나중에 등 번호를 새로 써서 제자리로 보낼게요. 지금은 일곱째 칸을 비워 줘야 해요. 칸 지키는 돌거북 여덟만 물러나게 해 주세요."}]'::jsonb, '{"xp": 3840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mks_stone_turtle', 4, '일곱째 칸', '칸 지키는 돌거북을(를) 물리친다', '{"at": ["nine_court"], "tasks": [{"t": "win", "m": ["mk_court_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "덩치들이 물러난 일곱째 칸은 텅 비어 있었다. 작은 돌거북은 내 발등 뒤에서 고개만 빼꼼 내밀고 칸을 살폈다. 그러고는 아주 천천히, 칸 한가운데까지 기어갔다."}, {"s": null, "t": "돌거북이 칸 한가운데에 엎드리자 바닥의 먹줄이 희미하게 빛났다. 지워져 가던 칸 둘레의 금이 한 줄 또렷해졌다."}, {"s": "q:sx_mk_dano", "t": "됐다! 제자리예요! 봐요, 진이 한 칸 고쳐졌어요!"}, {"s": null, "t": "단오는 먹통을 흔들며 펄쩍 뛰었다. 먹물이 튀어 소년의 볼에 점이 찍혔다. 돌거북이 그 소리에 놀라 목을 등껍질 속으로 쏙 집어넣었다가, 다시 천천히 내밀었다."}, {"s": "q:sx_mk_dano", "t": "얘 이름도 지어 줄까요? 칸 번호 말고 진짜 이름이요. 정청 기록에는 「일곱째 칸 돌거북」이라고만 적혀 있거든요."}, {"s": null, "t": "나는 단오가 지어 주라고 했다. 소년은 한참 고민하다가 활짝 웃었다."}, {"s": "q:sx_mk_dano", "t": "느림보요! 아니다, 그건 너무하다. 꾹꾹이. 한 걸음 갈 때마다 꾹꾹 누르면서 가니까요."}, {"s": null, "t": "단오는 먹통 붓으로 돌거북 등 번호 옆에 작게 「꾹꾹이」라고 적었다. 돌거북은 등에 무엇을 적는지 모르는 채, 칸 한가운데서 만족스럽게 눈을 감았다."}]'::jsonb, '{"xp": 3840, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
